description:
## Overview

This task implements a compatibility layer that allows gradual migration from traditional
message-based APIs to the new symbol-native paradigm. Users can adopt RaptorQ incrementally
while maintaining compatibility with existing code.

## Rationale

Production systems cannot switch protocols overnight. We need:
1. **Gradual adoption** - Enable RaptorQ on a per-operation basis
2. **API compatibility** - Existing code continues to work unchanged
3. **Performance parity** - Non-RaptorQ paths remain efficient
4. **Clear migration path** - Documentation and tooling for transition

## Technical Specification

### Compatibility Traits

```rust
/// Marker trait for types that can work with both paradigms
pub trait DualMode: Send + Sync {
    /// Whether this instance uses RaptorQ encoding
    fn uses_raptorq(&self) -> bool;

    /// Convert to symbol-native representation if not already
    fn to_symbol_native(self) -> Self;

    /// Convert to traditional representation if not already
    fn to_traditional(self) -> Self;
}

/// Extension trait for Result types in dual-mode context
pub trait ResultExt<T, E> {
    /// Convert result to symbol-native representation
    fn symbolize(self) -> Result<SymbolizedValue<T>, SymbolizedError<E>>;

    /// Convert result to traditional representation
    fn traditionalize(self) -> Result<T, E>;
}

/// Wrapper that can hold either traditional or symbol-native value
pub enum DualValue<T> {
    /// Traditional direct value
    Traditional(T),
    /// Symbol-encoded value with metadata
    SymbolNative {
        symbols: SymbolSet,
        object_id: ObjectId,
        _phantom: PhantomData<T>,
    },
}

impl<T: Serialize + DeserializeOwned> DualValue<T> {
    /// Get the underlying value, decoding if necessary
    pub fn get(&self) -> Result<T, DecodeError> {
        match self {
            Self::Traditional(v) => Ok(v.clone()),
            Self::SymbolNative { symbols, .. } => {
                decode_from_symbols(symbols)
            }
        }
    }

    /// Encode to symbols if not already symbol-native
    pub fn ensure_symbols(&mut self, config: &EncodingConfig) -> &SymbolSet {
        if let Self::Traditional(v) = self {
            let (symbols, object_id) = encode_to_symbols(v, config);
            *self = Self::SymbolNative {
                symbols,
                object_id,
                _phantom: PhantomData,
            };
        }
        match self {
            Self::SymbolNative { symbols, .. } => symbols,
            _ => unreachable\!(),
        }
    }
}
```

### Migration Mode Enum

```rust
/// Migration mode controls how operations handle dual-mode values
#[derive(Debug, Clone, Copy, Default)]
pub enum MigrationMode {
    /// Only use traditional mode (no RaptorQ)
    TraditionalOnly,
    /// Default to traditional, RaptorQ opt-in
    #[default]
    PreferTraditional,
    /// Use RaptorQ when beneficial, fall back to traditional
    Adaptive,
    /// Default to RaptorQ, traditional opt-in
    PreferSymbolNative,
    /// Only use RaptorQ (errors on traditional-only operations)
    SymbolNativeOnly,
}

impl MigrationMode {
    /// Whether to use RaptorQ for a given operation
    pub fn should_use_raptorq(&self, hint: Option<bool>, data_size: usize) -> bool {
        match (self, hint) {
            // Explicit hints always win
            (_, Some(true)) => true,
            (_, Some(false)) => false,
            // Mode-specific defaults
            (Self::TraditionalOnly, None) => false,
            (Self::SymbolNativeOnly, None) => true,
            (Self::PreferTraditional, None) => false,
            (Self::PreferSymbolNative, None) => true,
            // Adaptive mode uses heuristics
            (Self::Adaptive, None) => {
                // Use RaptorQ for larger payloads or distributed operations
                data_size > 1024 || is_distributed_context()
            }
        }
    }
}
```

### Compatibility Combinators

```rust
/// Run a combinator with migration mode control
pub async fn with_migration_mode<F, Fut, T>(
    mode: MigrationMode,
    f: F,
) -> T
where
    F: FnOnce() -> Fut,
    Fut: Future<Output = T>,
{
    MIGRATION_MODE.scope(mode, f()).await
}

/// Combinator wrapper that supports both modes
pub struct DualJoin<T> {
    traditional: Option<Join<T>>,
    symbol_native: Option<SymbolJoin<T>>,
}

impl<T: Clone + Send + Sync> DualJoin<T> {
    pub fn new(mode: MigrationMode) -> Self {
        match mode {
            MigrationMode::TraditionalOnly |
            MigrationMode::PreferTraditional => Self {
                traditional: Some(Join::new()),
                symbol_native: None,
            },
            MigrationMode::SymbolNativeOnly |
            MigrationMode::PreferSymbolNative => Self {
                traditional: None,
                symbol_native: Some(SymbolJoin::new()),
            },
            MigrationMode::Adaptive => Self {
                traditional: Some(Join::new()),
                symbol_native: Some(SymbolJoin::new()),
            },
        }
    }

    /// Join futures, using appropriate implementation
    pub async fn join_all<I, F, Fut>(self, futures: I) -> Vec<Result<T, E>>
    where
        I: IntoIterator<Item = F>,
        F: FnOnce() -> Fut,
        Fut: Future<Output = Result<T, E>>,
    {
        if let Some(join) = self.symbol_native {
            // Symbol-native path with encoding/distribution
            join.join_all(futures).await
        } else if let Some(join) = self.traditional {
            // Traditional path
            join.join_all(futures).await
        } else {
            unreachable\!()
        }
    }
}
```

### Gradual Migration API

```rust
/// Builder for gradual migration
pub struct MigrationBuilder {
    /// Features to enable
    features: HashSet<MigrationFeature>,
    /// Per-operation overrides
    overrides: HashMap<String, MigrationMode>,
}

#[derive(Debug, Clone, Copy, Hash, Eq, PartialEq)]
pub enum MigrationFeature {
    /// Enable RaptorQ for join operations
    JoinEncoding,
    /// Enable RaptorQ for race operations
    RaceEncoding,
    /// Enable distributed region encoding
    DistributedRegions,
    /// Enable symbol-based cancellation
    SymbolCancellation,
    /// Enable symbol-based tracing
    SymbolTracing,
    /// Enable epoch barriers
    EpochBarriers,
}

impl MigrationBuilder {
    /// Enable a specific migration feature
    pub fn enable(mut self, feature: MigrationFeature) -> Self {
        self.features.insert(feature);
        self
    }

    /// Disable a specific feature
    pub fn disable(mut self, feature: MigrationFeature) -> Self {
        self.features.remove(&feature);
        self
    }

    /// Enable all features (full RaptorQ mode)
    pub fn full_raptorq(mut self) -> Self {
        self.features = MigrationFeature::all().collect();
        self
    }

    /// Build the migration configuration
    pub fn build(self) -> MigrationConfig {
        MigrationConfig {
            features: self.features,
            overrides: self.overrides,
        }
    }
}

/// Use migration configuration
pub fn configure_migration() -> MigrationBuilder {
    MigrationBuilder::default()
}

// Example usage:
// let config = configure_migration()
//     .enable(MigrationFeature::JoinEncoding)
//     .enable(MigrationFeature::DistributedRegions)
//     .build();
```

### Legacy API Adapters

```rust
/// Adapter that presents traditional API over symbol-native implementation
pub mod legacy {
    use super::*;

    /// Traditional join that internally uses symbols
    pub async fn join_all<T, E, I, F, Fut>(futures: I) -> Vec<Result<T, E>>
    where
        T: Serialize + DeserializeOwned + Send + Sync,
        E: Serialize + DeserializeOwned + Send + Sync,
        I: IntoIterator<Item = F>,
        F: FnOnce() -> Fut,
        Fut: Future<Output = Result<T, E>>,
    {
        // Check migration config
        let config = current_migration_config();

        if config.is_enabled(MigrationFeature::JoinEncoding) {
            // Use symbol-native implementation, decode results
            let symbol_results = symbol_join_all(futures).await;
            symbol_results.into_iter()
                .map(|r| r.traditionalize())
                .collect()
        } else {
            // Use traditional implementation
            traditional_join_all(futures).await
        }
    }

    /// Traditional race that internally uses symbols
    pub async fn race_all<T, E, I, F, Fut>(futures: I) -> Result<T, Vec<E>>
    where
        T: Serialize + DeserializeOwned + Send,
        E: Serialize + DeserializeOwned + Send,
        I: IntoIterator<Item = F>,
        F: FnOnce() -> Fut,
        Fut: Future<Output = Result<T, E>>,
    {
        let config = current_migration_config();

        if config.is_enabled(MigrationFeature::RaceEncoding) {
            symbol_race_all(futures).await.traditionalize()
        } else {
            traditional_race_all(futures).await
        }
    }
}
```

## Unit Tests

```rust
#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_dual_value_traditional() {
        let value = DualValue::Traditional(42i32);
        assert_eq\!(value.get().unwrap(), 42);
        assert\!(\!value.uses_raptorq());
    }

    #[test]
    fn test_dual_value_conversion() {
        let mut value = DualValue::Traditional("hello".to_string());
        let config = EncodingConfig::default();

        // Convert to symbol-native
        value.ensure_symbols(&config);
        assert\!(matches\!(value, DualValue::SymbolNative { .. }));

        // Still get same value
        assert_eq\!(value.get().unwrap(), "hello".to_string());
    }

    #[test]
    fn test_migration_mode_decisions() {
        // Traditional only never uses RaptorQ
        assert\!(\!MigrationMode::TraditionalOnly.should_use_raptorq(None, 10000));

        // Symbol-native only always uses RaptorQ
        assert\!(MigrationMode::SymbolNativeOnly.should_use_raptorq(None, 10));

        // Hints override mode
        assert\!(MigrationMode::TraditionalOnly.should_use_raptorq(Some(true), 10));
        assert\!(\!MigrationMode::SymbolNativeOnly.should_use_raptorq(Some(false), 10));

        // Adaptive uses heuristics
        assert\!(\!MigrationMode::Adaptive.should_use_raptorq(None, 100));
        assert\!(MigrationMode::Adaptive.should_use_raptorq(None, 10000));
    }

    #[test]
    fn test_migration_builder() {
        let config = configure_migration()
            .enable(MigrationFeature::JoinEncoding)
            .enable(MigrationFeature::RaceEncoding)
            .build();

        assert\!(config.is_enabled(MigrationFeature::JoinEncoding));
        assert\!(config.is_enabled(MigrationFeature::RaceEncoding));
        assert\!(\!config.is_enabled(MigrationFeature::DistributedRegions));
    }

    #[test]
    fn test_full_raptorq_mode() {
        let config = configure_migration()
            .full_raptorq()
            .build();

        for feature in MigrationFeature::all() {
            assert\!(config.is_enabled(feature));
        }
    }
}
```

## E2E Tests

```rust
#[cfg(test)]
mod e2e {
    use super::*;
    use tracing_subscriber::fmt::format::FmtSpan;

    fn setup_logging() {
        tracing_subscriber::fmt()
            .with_span_events(FmtSpan::FULL)
            .with_env_filter("raptorq_migration=debug")
            .try_init()
            .ok();
    }

    #[tokio::test]
    async fn test_gradual_migration_join() {
        setup_logging();
        tracing::info\!("Testing gradual migration for join operations");

        // Start with traditional mode
        let config = configure_migration().build();
        assert\!(\!config.is_enabled(MigrationFeature::JoinEncoding));

        let results = with_config(config, || async {
            legacy::join_all(vec\![
                || async { Ok::<_, ()>(1) },
                || async { Ok::<_, ()>(2) },
            ]).await
        }).await;

        tracing::info\!(results = ?results, "Traditional mode results");
        assert_eq\!(results, vec\![Ok(1), Ok(2)]);

        // Enable RaptorQ for join
        let config = configure_migration()
            .enable(MigrationFeature::JoinEncoding)
            .build();

        let results = with_config(config, || async {
            legacy::join_all(vec\![
                || async { Ok::<_, ()>(3) },
                || async { Ok::<_, ()>(4) },
            ]).await
        }).await;

        tracing::info\!(results = ?results, "Symbol-native mode results");
        assert_eq\!(results, vec\![Ok(3), Ok(4)]);
    }

    #[tokio::test]
    async fn test_mixed_mode_operation() {
        setup_logging();
        tracing::info\!("Testing mixed mode operation");

        // Enable only some features
        let config = configure_migration()
            .enable(MigrationFeature::DistributedRegions)
            // JoinEncoding not enabled
            .build();

        // Create a region (uses RaptorQ)
        let region = with_config(config.clone(), || async {
            create_distributed_region().await
        }).await;
        tracing::info\!(region_id = ?region.id(), "Created distributed region");

        // Join within region (uses traditional, not RaptorQ)
        let results = with_config(config, || async {
            region.run(|cx| async move {
                legacy::join_all(vec\![
                    || async { Ok::<_, ()>(1) },
                    || async { Ok::<_, ()>(2) },
                ]).await
            }).await
        }).await;

        tracing::info\!(
            results = ?results,
            region_used_raptorq = true,
            join_used_raptorq = false,
            "Mixed mode operation complete"
        );
    }

    #[tokio::test]
    async fn test_migration_feature_toggle_at_runtime() {
        setup_logging();
        tracing::info\!("Testing runtime feature toggle");

        let config = Arc::new(RwLock::new(configure_migration().build()));

        // Run with initial config
        {
            let c = config.read().await.clone();
            tracing::info\!(features_enabled = ?c.enabled_features(), "Initial config");
        }

        // Toggle feature at runtime
        {
            let mut c = config.write().await;
            *c = configure_migration()
                .enable(MigrationFeature::JoinEncoding)
                .build();
            tracing::info\!(features_enabled = ?c.enabled_features(), "Updated config");
        }

        // Subsequent operations use new config
        let c = config.read().await.clone();
        assert\!(c.is_enabled(MigrationFeature::JoinEncoding));
    }

    #[tokio::test]
    async fn test_backward_compatible_api() {
        setup_logging();
        tracing::info\!("Testing backward compatible API surface");

        // This test verifies that existing code patterns work unchanged

        // Old API pattern: direct join_all
        let results: Vec<Result<i32, ()>> = futures::future::join_all(vec\![
            Box::pin(async { Ok(1) }) as Pin<Box<dyn Future<Output = _> + Send>>,
            Box::pin(async { Ok(2) }),
        ]).await;

        tracing::info\!(results = ?results, "Old API pattern works");

        // New API pattern with migration: legacy::join_all
        let config = configure_migration().full_raptorq().build();
        let results = with_config(config, || async {
            legacy::join_all(vec\![
                || async { Ok::<_, ()>(1) },
                || async { Ok::<_, ()>(2) },
            ]).await
        }).await;

        tracing::info\!(results = ?results, "New API with migration works");

        // Results are identical
        assert_eq\!(results, vec\![Ok(1), Ok(2)]);
    }
}
```

