## Logging Strategy

```rust
use crate::observability::{LogEntry, LogLevel};

impl RecoveryOrchestrator {
    fn log_recovery_start(&self, trigger: &RecoveryTrigger) {
        let level = if trigger.is_critical() {
            LogLevel::Warn
        } else {
            LogLevel::Info
        };

        LogEntry::new(level, "recovery_started")
            .with_field("region_id", trigger.region_id().to_string())
            .with_field("trigger_type", format!("{:?}", trigger))
            .with_field("attempt", self.attempt.to_string())
            .with_field("max_attempts", self.config.max_attempts.to_string());
    }

    fn log_recovery_complete(&self, result: &RecoveryResult) {
        LogEntry::new(LogLevel::Info, "recovery_complete")
            .with_field("region_id", result.snapshot.region_id.to_string())
            .with_field("symbols_used", result.symbols_used.to_string())
            .with_field("replicas_contributed", result.contributing_replicas.len().to_string())
            .with_field("duration_ms", result.duration.as_millis().to_string())
            .with_field("attempt", result.attempt.to_string())
            .with_field("verified", result.verified.to_string());
    }

    fn log_recovery_failed(&self, error: &Error) {
        LogEntry::new(LogLevel::Error, "recovery_failed")
            .with_field("error_kind", format!("{:?}", error.kind()))
            .with_field("attempt", self.attempt.to_string())
            .with_field("context", error.to_string());
    }
}

impl RecoveryCollector {
    fn log_collection_progress(&self) {
        LogEntry::new(LogLevel::Debug, "symbol_collection_progress")
            .with_field("collected", self.progress.symbols_collected.to_string())
            .with_field("needed", self.progress.symbols_needed.to_string())
            .with_field("replicas_queried", self.progress.replicas_queried.to_string())
            .with_field("phase", format!("{:?}", self.progress.phase));
    }

    fn log_symbol_received(&self, symbol: &CollectedSymbol) {
        LogEntry::new(LogLevel::Trace, "symbol_received")
            .with_field("esi", symbol.symbol.esi().to_string())
            .with_field("source", symbol.source_replica.clone())
            .with_field("size", symbol.symbol.len().to_string());
    }
}

impl StateDecoder {
    fn log_decode_attempt(&self, params: &ObjectParams) {
        LogEntry::new(LogLevel::Debug, "decode_attempt")
            .with_field("object_id", params.object_id.to_string())
            .with_field("symbols_received", self.symbols_received().to_string())
            .with_field("symbols_needed", self.symbols_needed(params).to_string());
    }

    fn log_decode_result(&self, success: bool, duration: Duration) {
        let level = if success { LogLevel::Info } else { LogLevel::Warn };

        LogEntry::new(level, "decode_result")
            .with_field("success", success.to_string())
            .with_field("duration_ms", duration.as_millis().to_string());
    }
}

// Log level guidelines:
// - TRACE: Individual symbol received, replica queries
// - DEBUG: Collection progress, decode attempts
// - INFO:  Recovery started (non-critical), recovery complete
// - WARN:  Recovery started (critical), decode failed (retry available)
// - ERROR: Recovery failed (all attempts exhausted), unrecoverable errors
