### DNS Cache

```rust
// dns/src/cache.rs

use std::collections::HashMap;
use std::net::IpAddr;
use std::time::{Duration, Instant};

use crate::LookupIp;

/// Cache entry with expiration.
struct CacheEntry<T> {
    data: T,
    expires_at: Instant,
}

impl<T> CacheEntry<T> {
    fn new(data: T, ttl: Duration) -> Self {
        CacheEntry {
            data,
            expires_at: Instant::now() + ttl,
        }
    }

    fn is_expired(&self) -> bool {
        Instant::now() >= self.expires_at
    }
}

/// DNS cache.
pub(crate) struct DnsCache {
    ip_cache: HashMap<String, CacheEntry<LookupIp>>,
    max_size: usize,
    hits: u64,
    misses: u64,
}

impl DnsCache {
    pub fn new() -> Self {
        DnsCache {
            ip_cache: HashMap::new(),
            max_size: 10_000,
            hits: 0,
            misses: 0,
        }
    }

    pub fn get_ip(&mut self, host: &str) -> Option<LookupIp> {
        if let Some(entry) = self.ip_cache.get(host) {
            if !entry.is_expired() {
                self.hits += 1;
                return Some(entry.data.clone());
            }
            // Remove expired entry
            self.ip_cache.remove(host);
        }
        self.misses += 1;
        None
    }

    pub fn put_ip(&mut self, host: &str, lookup: &LookupIp) {
        // Evict if at capacity
        if self.ip_cache.len() >= self.max_size {
            self.evict_expired();

            // If still at capacity, remove oldest
            if self.ip_cache.len() >= self.max_size {
                if let Some(oldest_key) = self.ip_cache.keys().next().cloned() {
                    self.ip_cache.remove(&oldest_key);
                }
            }
        }

        self.ip_cache.insert(
            host.to_string(),
            CacheEntry::new(lookup.clone(), lookup.ttl()),
        );
    }

    fn evict_expired(&mut self) {
        self.ip_cache.retain(|_, entry| !entry.is_expired());
    }

    pub fn clear(&mut self) {
        self.ip_cache.clear();
        self.hits = 0;
        self.misses = 0;
    }

    pub fn stats(&self) -> CacheStats {
        CacheStats {
            size: self.ip_cache.len(),
            hits: self.hits,
            misses: self.misses,
            hit_rate: if self.hits + self.misses > 0 {
                self.hits as f64 / (self.hits + self.misses) as f64
            } else {
                0.0
            },
        }
    }
}

/// Cache statistics.
#[derive(Debug, Clone)]
pub struct CacheStats {
    pub size: usize,
    pub hits: u64,
    pub misses: u64,
    pub hit_rate: f64,
}
```

