    packet_id: u64,
    size_bytes: usize,
    enqueued_at: Time,
}

impl BandwidthLimiter {
    pub fn new(bandwidth: u64, burst_size: u64) -> Self {
        Self {
            bandwidth,
            tokens: burst_size,
            burst_size,
            last_refill: Time::ZERO,
            pending: VecDeque::new(),
        }
    }

    /// Refill tokens based on elapsed time
    pub fn refill(&mut self, now: Time) {
        if now <= self.last_refill {
            return;
        }

        let elapsed = now.duration_since(self.last_refill);
        let tokens_to_add = (self.bandwidth as f64 * elapsed.as_secs_f64()) as u64;

        self.tokens = (self.tokens + tokens_to_add).min(self.burst_size);
        self.last_refill = now;
    }

    /// Try to transmit a packet, returns delay if queued
    pub fn try_transmit(&mut self, size_bytes: usize, now: Time) -> TransmitResult {
        self.refill(now);

        if self.tokens >= size_bytes as u64 {
            self.tokens -= size_bytes as u64;
            TransmitResult::Immediate
        } else {
            // Calculate transmission time
            let bytes_needed = size_bytes as u64 - self.tokens;
            let delay = Duration::from_secs_f64(bytes_needed as f64 / self.bandwidth as f64);

            TransmitResult::Delayed(delay)
        }
    }

    /// Get current utilization (0.0 - 1.0)
    pub fn utilization(&self) -> f64 {
        1.0 - (self.tokens as f64 / self.burst_size as f64)
    }
}

#[derive(Debug)]
pub enum TransmitResult {
    /// Packet transmitted immediately
    Immediate,

    /// Packet delayed by specified duration
    Delayed(Duration),

    /// Packet dropped (queue full)
    Dropped,
}
