        let mut network = SimulatedNetwork::new(NetworkConfig::default());

        let hosts: Vec<_> = (0..5).map(|i| network.add_host(&format!("node-{}", i))).collect();

        // Send from h0 to all others
        for &h in &hosts[1..] {
            network.send(hosts[0], h, Bytes::from("broadcast"));
        }

        network.run_for(Duration::from_secs(1));

