                ..NetworkConditions::ideal()
            },
            tick_resolution: Duration::from_millis(1),
            ..Default::default()
        });

        let h1 = network.add_host("node-1");
        let h2 = network.add_host("node-2");

        network.send(h1, h2, Bytes::from("test"));

        // At t=49ms, not yet delivered
        network.run_for(Duration::from_millis(49));
        assert!(network.hosts.get(&h2).unwrap().inbox.is_empty());

        // At t=51ms, should be delivered
        network.run_for(Duration::from_millis(2));
        assert_eq!(network.hosts.get(&h2).unwrap().inbox.len(), 1);
    }

    #[test]
    fn uniform_latency_bounds() {
        let min = Duration::from_millis(10);
        let max = Duration::from_millis(100);

        let mut network = SimulatedNetwork::new(NetworkConfig {
            default_conditions: NetworkConditions {
                latency: LatencyModel::Uniform { min, max },
                ..NetworkConditions::ideal()
            },
            ..Default::default()
        });

        let h1 = network.add_host("node-1");
        let h2 = network.add_host("node-2");

        // Send many packets and check latency distribution
        for _ in 0..100 {
            network.send(h1, h2, Bytes::from("test"));
        }

        network.run_for(Duration::from_secs(1));

        let latencies: Vec<_> = network.hosts.get(&h2).unwrap().inbox.iter()
            .map(|p| p.received_at.duration_since(p.sent_at))
            .collect();

        for lat in latencies {
