        }

        network.run_for(Duration::from_secs(1));

        let delivered = network.hosts.get(&h2).unwrap().inbox.len();
        // With 50% loss, expect ~500 delivered (allow variance)
        assert!(delivered > 400 && delivered < 600, "Expected ~500, got {}", delivered);
    }

