            network.hosts.get(&h2).unwrap().inbox.iter()
                .map(|p| p.received_at)
                .collect()
        }

        let times1 = run_scenario(42);
        let times2 = run_scenario(42);

        assert_eq!(times1, times2, "Same seed must produce identical delivery times");
