### Limit Adapter (for BufMut)

```rust
// bytes/src/buf/limit.rs

use super::{BufMut, UninitSlice};

/// Limit the number of bytes that can be written to a `BufMut`.
pub struct Limit<T> {
    inner: T,
    limit: usize,
}

impl<T> Limit<T> {
    /// Create a new Limit.
    pub(crate) fn new(inner: T, limit: usize) -> Self {
        Limit { inner, limit }
    }

    /// Get a reference to the underlying buffer.
    pub fn get_ref(&self) -> &T {
        &self.inner
    }

    /// Get a mutable reference to the underlying buffer.
    pub fn get_mut(&mut self) -> &mut T {
        &mut self.inner
    }

    /// Destructure into the underlying buffer.
    pub fn into_inner(self) -> T {
        self.inner
    }

    /// Returns the current limit.
    pub fn limit(&self) -> usize {
        self.limit
    }

    /// Set the limit.
    pub fn set_limit(&mut self, limit: usize) {
        self.limit = limit;
    }
}

impl<T: BufMut> BufMut for Limit<T> {
    fn remaining_mut(&self) -> usize {
        std::cmp::min(self.inner.remaining_mut(), self.limit)
    }

    fn chunk_mut(&mut self) -> &mut UninitSlice {
        let chunk = self.inner.chunk_mut();
        let limit = std::cmp::min(chunk.len(), self.limit);

        // Return a limited view
        unsafe {
            UninitSlice::from_raw_parts_mut(
                chunk.as_mut_ptr() as *mut std::mem::MaybeUninit<u8>,
                limit,
            )
        }
    }

    unsafe fn advance_mut(&mut self, cnt: usize) {
        assert!(cnt <= self.limit, "cannot advance past limit");
        self.inner.advance_mut(cnt);
        self.limit -= cnt;
    }
}
