### Reader and Writer Adapters

```rust
// bytes/src/buf/reader.rs

use std::io::{self, Read};
use super::Buf;

/// Adapts a `Buf` to `std::io::Read`.
pub struct Reader<B> {
    buf: B,
}

impl<B> Reader<B> {
    /// Create a new Reader.
    pub fn new(buf: B) -> Self {
        Reader { buf }
    }

    /// Get a reference to the underlying buffer.
    pub fn get_ref(&self) -> &B {
        &self.buf
    }

    /// Get a mutable reference to the underlying buffer.
    pub fn get_mut(&mut self) -> &mut B {
        &mut self.buf
    }

    /// Consume and return the underlying buffer.
    pub fn into_inner(self) -> B {
        self.buf
    }
}

impl<B: Buf> Read for Reader<B> {
    fn read(&mut self, dst: &mut [u8]) -> io::Result<usize> {
        if !self.buf.has_remaining() {
            return Ok(0);
        }

        let chunk = self.buf.chunk();
        let cnt = std::cmp::min(chunk.len(), dst.len());
        dst[..cnt].copy_from_slice(&chunk[..cnt]);
        self.buf.advance(cnt);

        Ok(cnt)
    }
}

// bytes/src/buf/writer.rs

use std::io::{self, Write};
use super::BufMut;

/// Adapts a `BufMut` to `std::io::Write`.
pub struct Writer<B> {
    buf: B,
}

impl<B> Writer<B> {
    /// Create a new Writer.
    pub fn new(buf: B) -> Self {
        Writer { buf }
    }

    /// Get a reference to the underlying buffer.
    pub fn get_ref(&self) -> &B {
        &self.buf
    }

    /// Get a mutable reference to the underlying buffer.
    pub fn get_mut(&mut self) -> &mut B {
        &mut self.buf
    }

    /// Consume and return the underlying buffer.
    pub fn into_inner(self) -> B {
        self.buf
    }
}

impl<B: BufMut> Write for Writer<B> {
    fn write(&mut self, src: &[u8]) -> io::Result<usize> {
        if !self.buf.has_remaining_mut() {
            return Err(io::Error::new(
                io::ErrorKind::WriteZero,
                "buffer full"
            ));
        }

        let chunk = self.buf.chunk_mut();
        let cnt = std::cmp::min(chunk.len(), src.len());

        unsafe {
            std::ptr::copy_nonoverlapping(
                src.as_ptr(),
                chunk.as_mut_ptr(),
                cnt,
            );
            self.buf.advance_mut(cnt);
        }

        Ok(cnt)
    }

    fn flush(&mut self) -> io::Result<()> {
        Ok(())
    }
}
