        });

        // Trigger massive cancellation
        let region = Region::new();
        for _ in 0..1000 {
            region.spawn(async {
                loop { yield_now().await; }
            });
        }
        region.cancel(); // All 1000 tasks enter cancel lane

        // Original work should complete despite cancellation flood
        let result = timeout(Duration::from_secs(1), handle).await;
        assert_eq!(result.unwrap().unwrap(), 42);
    });
}
