### Configuration Loading

```rust
/// Configuration loader with layered sources
pub struct ConfigLoader {
    /// Base profile
    profile: RuntimeProfile,
    /// Environment variable overrides
    env_overrides: HashMap<String, String>,
    /// File-based overrides
    file_config: Option<PathBuf>,
}

impl ConfigLoader {
    /// Load configuration with precedence:
    /// 1. File config (lowest)
    /// 2. Profile defaults
    /// 3. Environment variables
    /// 4. Programmatic overrides (highest)
    pub fn load(&self) -> Result<RaptorQConfig, ConfigError> {
        let mut config = if let Some(path) = &self.file_config {
            load_from_file(path)?
        } else {
            self.profile.to_config()
        };

        apply_env_overrides(&mut config, &self.env_overrides)?;
        config.validate()?;
        Ok(config)
    }
}
```

