## E2E Tests

```rust
#[cfg(test)]
mod e2e {
    use super::*;
    use tracing_subscriber::fmt::format::FmtSpan;

    fn setup_logging() {
        tracing_subscriber::fmt()
            .with_span_events(FmtSpan::FULL)
            .with_env_filter("raptorq_config=debug")
            .try_init()
            .ok();
    }

    #[test]
    fn test_config_hot_reload() {
        setup_logging();
        tracing::info!("Testing configuration hot reload");

        // Create initial config file
        let temp_dir = tempdir().unwrap();
        let config_path = temp_dir.path().join("config.toml");

        std::fs::write(&config_path, r#"
            [encoding]
            symbol_size = 256
        "#).unwrap();

        // Load config
        let (config, watcher) = ConfigLoader::new()
            .file(&config_path)
            .with_hot_reload()
            .load()
            .unwrap();

        tracing::info!(symbol_size = %config.encoding.symbol_size, "Initial config loaded");
        assert_eq!(config.encoding.symbol_size, 256);

        // Modify config file
        std::fs::write(&config_path, r#"
            [encoding]
            symbol_size = 512
        "#).unwrap();

        // Wait for reload
        std::thread::sleep(Duration::from_millis(100));

        let reloaded = watcher.current_config();
        tracing::info!(symbol_size = %reloaded.encoding.symbol_size, "Config reloaded");
        assert_eq!(reloaded.encoding.symbol_size, 512);
    }

    #[test]
    fn test_runtime_profile_switching() {
        setup_logging();

        let runtime = Runtime::builder()
            .profile(RuntimeProfile::Development)
            .build()
            .unwrap();

        tracing::info!(profile = "development", "Runtime started");

        // Run some operations
        runtime.run(async {
            // Operations use development config
        });

        // Switch to production
        runtime.switch_profile(RuntimeProfile::Production);
        tracing::info!(profile = "production", "Switched to production profile");

        // Verify settings changed
        let config = runtime.config();
        assert_eq!(config.observability.log_level, LogLevel::Warn);
    }
}
