    id: RegionId,
    parent: Option<RegionId>,

    // Hot path: lock-free
    state: AtomicRegionState,
    cancel_requested: AtomicBool,

    // Mutations: locked
    inner: RwLock<RegionInner>,
}
```

## Critical Operations

### 1. spawn_in_region(region_id, task_id)
```rust
fn spawn_in_region(&self, region_id: RegionId, task_id: TaskId) -> Result<(), Error> {
    let region = self.regions.get(region_id)?;

    // Fast path: check state without lock
    if region.state.load() != RegionState::Open {
        return Err(Error::region_closed());
    }

    // Slow path: acquire lock, recheck, add
    let mut inner = region.inner.write();
    if region.state.load() != RegionState::Open {
        return Err(Error::region_closed());
    }
    inner.tasks.push(task_id);
    Ok(())
}
```

### 2. request_cancel(region_id, reason)
```rust
fn request_cancel(&self, region_id: RegionId, reason: CancelReason) {
    let region = self.regions.get(region_id);

    // Set atomic flag
    region.cancel_requested.store(true);

    // Propagate to children (needs lock)
    let inner = region.inner.read();
    for child_id in &inner.children {
        self.request_cancel(*child_id, reason.clone());
    }
    for task_id in &inner.tasks {
        self.tasks.request_cancel(*task_id, reason.clone());
    }
}
```

### 3. close_region(region_id)
Must wait for all children and tasks to complete.
```rust
