async fn write_frame(stream: &mut TcpStream, header: &[u8], payload: &[u8]) -> io::Result<()> {
    let bufs = [
        IoSlice::new(header),
        IoSlice::new(payload),
    ];

    // Single syscall for header + payload
    stream.write_vectored(&bufs).await?;
    Ok(())
}
