// Error Types
// =========================================================================

/// Errors from circuit breaker
#[derive(Debug, Clone)]
pub enum CircuitBreakerError<E = Error> {
    /// Circuit is open, call rejected
    Open { remaining: Duration },

    /// Circuit is half-open with max probes active
    HalfOpenFull,

    /// Underlying operation error
    Inner(E),
}

impl<E: std::fmt::Display> std::fmt::Display for CircuitBreakerError<E> {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        match self {
            Self::Open { remaining } => write!(f, "circuit open, retry after {:?}", remaining),
            Self::HalfOpenFull => write!(f, "circuit half-open, max probes active"),
            Self::Inner(e) => write!(f, "{}", e),
        }
    }
}

impl<E: std::error::Error> std::error::Error for CircuitBreakerError<E> {}

// =========================================================================
// Permit Types (internal)
// =========================================================================

#[derive(Debug, Clone, Copy)]
enum Permit {
    Normal,  // Closed state
    Probe,   // Half-open state
}

// =========================================================================
// Combinator Function
// =========================================================================

/// Execute operation with circuit breaker protection
pub async fn with_circuit_breaker<T, E, F>(
    cx: &Cx,
    breaker: &CircuitBreaker,
    op: F,
) -> Result<T, CircuitBreakerError<E>>
where
    F: Future<Output = Result<T, E>>,
    E: Into<Error> + Clone,
{
    let now = cx.now();

    // Check if call is allowed
    let permit = breaker.should_allow(now)?;

    tracing::trace!(
        circuit = %breaker.policy.name,
        permit = ?permit,
        state = ?breaker.state(),
        "circuit_breaker: call allowed"
    );

    // Execute with cancellation handling
    let result = op.await;
    let now = cx.now();  // Get time after operation

    match result {
        Ok(value) => {
            breaker.record_success(permit, now);
            Ok(value)
        }
        Err(e) => {
            let error: Error = e.clone().into();
            breaker.record_failure(permit, &error, now);
            Err(CircuitBreakerError::Inner(e))
        }
    }
}
