// Event levels:
// - WARN: State transitions to open
// - INFO: State transitions to closed (recovery)
// - DEBUG: Failures recorded
// - TRACE: All calls (success, allowed, rejected)

tracing::warn!(
    circuit = %name,
    from = ?old_state,
    to = ?new_state,
    failures = failure_count,
    "circuit_breaker: state_change"
);

tracing::debug!(
    circuit = %name,
    error = ?error,
    failure_count = count,
    "circuit_breaker: failure_recorded"
);

tracing::trace!(
    circuit = %name,
    result = "success",
    latency_ms = latency.as_millis(),
    "circuit_breaker: call_complete"
);
