### LoadShedLayer
```rust
pub struct LoadShedLayer;
pub struct LoadShed<S> {
    inner: S,
    overloaded: bool,
}

impl<S, Req> Service<Req> for LoadShed<S>
where S: Service<Req> {
    fn poll_ready(&mut self, cx: &mut Context<'_>) -> Poll<Result<(), Self::Error>> {
        match self.inner.poll_ready(cx) {
            Poll::Ready(r) => { self.overloaded = false; Poll::Ready(r.map_err(Into::into)) }
            Poll::Pending => { self.overloaded = true; Poll::Ready(Ok(())) }
        }
    }

    fn call(&mut self, req: Req) -> Self::Future {
        if self.overloaded {
            return LoadShedFuture::overloaded();
        }
        LoadShedFuture::inner(self.inner.call(req))
    }
}
```

