```

## Future Types

```rust
/// Future for read_exact
pub struct ReadExact<'a, R: ?Sized> {
    reader: &'a mut R,
    buf: &'a mut [u8],
    pos: usize,
}

impl<R: AsyncRead + Unpin + ?Sized> Future for ReadExact<'_, R> {
    type Output = io::Result<()>;

    fn poll(self: Pin<&mut Self>, cx: &mut Context<'_>) -> Poll<Self::Output> {
        let this = self.get_mut();
        while this.pos < this.buf.len() {
            let mut read_buf = ReadBuf::new(&mut this.buf[this.pos..]);
            ready!(Pin::new(&mut *this.reader).poll_read(cx, &mut read_buf))?;

            let n = read_buf.filled().len();
            if n == 0 {
                return Poll::Ready(Err(io::Error::from(io::ErrorKind::UnexpectedEof)));
            }
            this.pos += n;
        }
        Poll::Ready(Ok(()))
    }
}
```

## Cancel-Safety
- poll_read: cancel-safe (partial data discarded)
- read_exact: NOT cancel-safe (partial state)
- read_to_end: cancel-safe (vec can be inspected)

