```rust
#[test]
fn test_wake_unblocks_poll() {
    let reactor = Arc::new(create_test_reactor());
    let reactor_clone = Arc::clone(&reactor);

    // Spawn thread to poll
    let handle = std::thread::spawn(move || {
        let mut events = Events::with_capacity(16);
        reactor_clone.poll(&mut events, None) // Blocks forever without wake
    });

    // Give thread time to start polling
    std::thread::sleep(Duration::from_millis(50));

    // Wake it
    reactor.wake().unwrap();

    // Should return quickly
    let result = handle.join().unwrap();
    assert!(result.is_ok());
}

