### 2. HashMap Determinism
```rust
// src/util/det_hash.rs

use std::hash::{BuildHasher, Hasher};

/// Deterministic hasher using a fast, non-cryptographic algorithm.
/// 
/// Uses FxHash-style mixing with a fixed seed for reproducibility.
/// The algorithm is:
/// 1. Initialize with fixed seed
/// 2. For each byte, multiply state by prime and XOR with byte
/// 3. Final mixing to distribute bits
#[derive(Clone)]
pub struct DetHasher {
    state: u64,
}

impl DetHasher {
    /// Fixed seed ensures all instances produce identical hashes
    const SEED: u64 = 0x16f11fe89b0d677c;
    /// FxHash prime multiplier
    const MULTIPLIER: u64 = 0x517cc1b727220a95;
}

impl Default for DetHasher {
    fn default() -> Self {
        Self { state: Self::SEED }
    }
}

impl Hasher for DetHasher {
    fn write(&mut self, bytes: &[u8]) {
        for &byte in bytes {
            self.state = self.state.wrapping_mul(Self::MULTIPLIER);
            self.state ^= byte as u64;
        }
    }

    fn write_u8(&mut self, i: u8) {
        self.state = self.state.wrapping_mul(Self::MULTIPLIER) ^ (i as u64);
    }

    fn write_u64(&mut self, i: u64) {
        self.state = self.state.wrapping_mul(Self::MULTIPLIER) ^ i;
    }

    fn finish(&self) -> u64 {
        // Final mixing for better distribution
        let mut h = self.state;
        h ^= h >> 33;
        h = h.wrapping_mul(0xff51afd7ed558ccd);
        h ^= h >> 33;
        h = h.wrapping_mul(0xc4ceb9fe1a85ec53);
        h ^= h >> 33;
        h
    }
}

#[derive(Clone, Default)]
pub struct DetBuildHasher;

impl BuildHasher for DetBuildHasher {
    type Hasher = DetHasher;
    fn build_hasher(&self) -> Self::Hasher {
        DetHasher::default()
    }
}

/// Deterministic HashMap with consistent iteration order across runs.
/// 
/// IMPORTANT: Always use this instead of std::collections::HashMap in
/// code that must be deterministic under the lab runtime.
pub type DetHashMap<K, V> = std::collections::HashMap<K, V, DetBuildHasher>;

/// Deterministic HashSet with consistent iteration order across runs.
pub type DetHashSet<K> = std::collections::HashSet<K, DetBuildHasher>;

/// BTreeMap/BTreeSet are naturally deterministic (use when order matters)
pub use std::collections::{BTreeMap, BTreeSet};

/// Macro to detect non-deterministic HashMap usage at compile time.
/// 
/// Add to lib.rs:
/// ```rust
/// #[cfg(feature = "det-lint")]
/// #[deny(clippy::disallowed_types)]
/// ```
/// 
/// And in clippy.toml:
/// ```toml
/// disallowed-types = [
///     { path = "std::collections::HashMap", reason = "Use DetHashMap for determinism" },
///     { path = "std::collections::HashSet", reason = "Use DetHashSet for determinism" },
/// ]
/// ```
#[doc(hidden)]
pub const _DET_HASH_LINT_HINT: () = ();
