### 5. Ambient Entropy Detection
```rust
// src/lab/entropy_guard.rs

use std::sync::atomic::{AtomicBool, Ordering};

/// Global flag indicating we are in strict deterministic mode
static STRICT_MODE: AtomicBool = AtomicBool::new(false);

/// Enable strict entropy isolation mode
pub fn enable_strict_mode() {
    STRICT_MODE.store(true, Ordering::SeqCst);
}

/// Disable strict entropy isolation mode  
pub fn disable_strict_mode() {
    STRICT_MODE.store(false, Ordering::SeqCst);
}

/// Check if strict mode is enabled
pub fn is_strict_mode() -> bool {
    STRICT_MODE.load(Ordering::SeqCst)
}

/// Panic if strict mode is enabled (call from ambient entropy sources)
#[inline]
pub fn check_no_ambient_entropy(source: &str) {
    if is_strict_mode() {
        panic!(
            "Ambient entropy source "\"{}\"" used in strict deterministic mode. \
             Use Cx::random_u64() or Cx::random_bytes() instead.",
            source
        );
    }
}

/// RAII guard for strict mode during test execution
pub struct StrictModeGuard {
    was_enabled: bool,
}

impl StrictModeGuard {
    pub fn new() -> Self {
        let was_enabled = STRICT_MODE.swap(true, Ordering::SeqCst);
        Self { was_enabled }
    }
}

impl Drop for StrictModeGuard {
    fn drop(&mut self) {
        STRICT_MODE.store(self.was_enabled, Ordering::SeqCst);
    }
}
