//! End-to-end tests for entropy isolation in lab runtime.
//! 
//! These tests verify that the lab runtime provides fully deterministic
//! execution when using the same entropy seed.

use asupersync::lab::{LabRuntime, LabConfig};
use asupersync::trace::{TraceBuffer, TraceEvent};
use std::time::Duration;

/// Capture all trace events during execution
fn capture_trace<F, T>(seed: u64, f: F) -> (T, Vec<TraceEvent>)
where
    F: FnOnce(&mut LabRuntime) -> T,
{
    let config = LabConfig {
        entropy_seed: seed,
        verify_entropy_isolation: true,
        ..Default::default()
    };

    let trace_buffer = TraceBuffer::new();
    let trace_handle = trace_buffer.handle();

    let mut runtime = LabRuntime::with_config(config);
    runtime.set_trace_sink(trace_handle);

    let result = f(&mut runtime);
    let events = trace_buffer.drain();

    (result, events)
}

#[test]
fn e2e_same_seed_identical_traces() {
    // This is the META-TEST from S2.dev
    let seed = 0x12345678_ABCDEF00;

    let (result1, trace1) = capture_trace(seed, |rt| {
        rt.block_on(async {
            let cx = rt.root_cx();

            cx.region(|sub| async move {
                let mut handles = vec![];

                // Spawn 10 tasks that use entropy
                for _ in 0..10 {
                    handles.push(sub.spawn(async move |cx| {
                        let random_val = cx.random_u64();
                        cx.sleep(Duration::from_millis(random_val % 100)).await;
                        random_val
                    }));
                }

                let mut results = vec![];
                for h in handles {
                    results.push(h.await);
                }
                results
            }).await
        })
    });

    let (result2, trace2) = capture_trace(seed, |rt| {
        rt.block_on(async {
            let cx = rt.root_cx();

            cx.region(|sub| async move {
                let mut handles = vec![];

                for _ in 0..10 {
                    handles.push(sub.spawn(async move |cx| {
                        let random_val = cx.random_u64();
