                    }));
                }

                let mut results = vec![];
                for h in handles {
                    results.push(h.await);
                }
                results
            }).await
        })
    });

    assert_eq!(result1, result2, "Same seed must produce identical results");

    let trace1_normalized = normalize_trace(&trace1);
    let trace2_normalized = normalize_trace(&trace2);

    assert_eq!(
        trace1_normalized, trace2_normalized,
        "Same seed must produce identical traces\n\
         Trace 1 len: {}\n\
         Trace 2 len: {}\n\
         First diff at: {:?}",
        trace1.len(),
        trace2.len(),
