    events.iter()
        .map(|e| e.with_normalized_timestamp())
        .collect()
}

fn find_first_diff(a: &[TraceEvent], b: &[TraceEvent]) -> Option<(usize, TraceEvent, TraceEvent)> {
    a.iter().zip(b.iter())
        .enumerate()
        .find(|(_, (ea, eb))| ea != eb)
        .map(|(i, (ea, eb))| (i, ea.clone(), eb.clone()))
}
