#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_obligation_commit() {
        let obligation = SymbolicObligation::new_for_test(
            1,
            ObjectId::new_for_test(1),
            10,
        );

        assert_eq!(obligation.state(), SymbolicObligationState::Reserved);
        assert!(obligation.is_pending());

        obligation.commit();

        // Note: We can't check state after commit because `commit` consumes self
        // This is by design - the linear type ensures single use
    }

    #[test]
    fn test_progress_complete_detection() {
        let progress = FulfillmentProgress::new(10);

        assert!(!progress.is_complete());
        assert_eq!(progress.percent(), 0.0);

        for _ in 0..5 {
            progress.increment();
        }

        assert!(!progress.is_complete());
        assert!((progress.percent() - 0.5).abs() < f64::EPSILON);

        for _ in 0..5 {
            progress.increment();
        }

        assert!(progress.is_complete());
        assert!((progress.percent() - 1.0).abs() < f64::EPSILON);
    }

    #[test]
    fn test_registry_creates_obligations() {
        let registry = SymbolicObligationRegistry::new();
        let object_id = ObjectId::new_for_test(1);
        let params = ObjectParams::new_for_test(1, 10000);
        let holder = TaskId::new_for_test(0, 0);
        let region = RegionId::new_for_test(0, 0);

        let obligation = registry.create_send_object(
            object_id,
            &params,
            holder,
            region,
            Time::ZERO,
        );

        assert_eq!(obligation.object_id(), object_id);
        assert_eq!(obligation.kind(), SymbolicObligationKind::SendObject);

        let stats = registry.stats();
        assert_eq!(stats.pending, 1);
        assert_eq!(stats.total, 1);

        // Clean up
        obligation.abort();
    }

    #[test]
    fn test_registry_pending_detection() {
        let registry = SymbolicObligationRegistry::new();
        let object_id = ObjectId::new_for_test(1);
        let params = ObjectParams::new_for_test(1, 10000);
        let holder = TaskId::new_for_test(0, 0);
        let region = RegionId::new_for_test(0, 0);

        let obligation = registry.create_send_object(
            object_id,
            &params,
            holder,
            region,
            Time::ZERO,
        );

        assert!(registry.has_pending_in_region(region));

        let pending = registry.pending_in_region(region);
        assert_eq!(pending.len(), 1);
        assert_eq!(pending[0].object_id, object_id);

        obligation.commit();

        // After commit, should update state
        registry.update_state(obligation.id(), SymbolicObligationState::Committed);
        assert!(!registry.has_pending_in_region(region));
    }

    #[test]
    fn test_fulfillment_snapshot() {
        let progress = FulfillmentProgress::new(100);

        progress.add(25);

        let snapshot = progress.snapshot();
        assert_eq!(snapshot.total, 100);
        assert_eq!(snapshot.fulfilled, 25);
        assert!((snapshot.percent - 0.25).abs() < f64::EPSILON);
        assert!(!snapshot.complete);
    }

    #[test]
    fn test_commit_or_abort_complete() {
        let obligation = SymbolicObligation::new_for_test(
            1,
            ObjectId::new_for_test(1),
            2,
        );

        // Fulfill all
        obligation.fulfill_many(2);

        // Should commit (complete)
        obligation.commit_or_abort();
        // No panic = success (committed)
    }

    #[test]
    fn test_commit_or_abort_incomplete() {
        let obligation = SymbolicObligation::new_for_test(
            1,
            ObjectId::new_for_test(1),
            10,
        );

        // Fulfill partially
        obligation.fulfill_many(5);

        // Should abort (incomplete)
        obligation.commit_or_abort();
        // No panic = success (aborted)
    }
}
