// build.rs usage:
// asupersync_grpc_build::compile_protos(&["proto/service.proto"], &["proto"])?;

pub fn compile_protos(
    protos: &[impl AsRef<Path>],
    includes: &[impl AsRef<Path>],
) -> Result<(), CompileError> {
    let mut config = Config::new();
    config.out_dir(std::env::var("OUT_DIR")?);

    for proto in protos {
        let proto = proto.as_ref();
        config.compile_proto(proto, includes)?;
    }

    Ok(())
}

pub struct Config {
    out_dir: PathBuf,
    build_client: bool,
    build_server: bool,
    extern_path: Vec<(String, String)>,
}

impl Config {
    pub fn build_client(mut self, enable: bool) -> Self { self.build_client = enable; self }
    pub fn build_server(mut self, enable: bool) -> Self { self.build_server = enable; self }
    pub fn extern_path(mut self, proto_path: &str, rust_path: &str) -> Self {
        self.extern_path.push((proto_path.into(), rust_path.into()));
        self
    }
}
