```rust
/// Cx is not Clone or Copy - must be explicitly passed
pub struct Cx<'a> {
    capabilities: CapabilitySet,
    tracker: &'a CapabilityTracker,
    _marker: PhantomData<&'a mut ()>, // Prevent sharing
}

impl<'a> Cx<'a> {
    /// Create a narrowed context for a child task
    pub fn narrow(&mut self, narrowing: impl FnOnce(&mut CapabilitySet)) -> Cx<'_> {
        let mut caps = self.capabilities.clone();
        narrowing(&mut caps);
        Cx {
            capabilities: caps,
            tracker: self.tracker,
            _marker: PhantomData,
        }
    }
}
