## Overview

Implement the core routing system for the web framework, providing type-safe, composable route definitions with support for path parameters, method matching, and middleware.

## Implementation Steps

### Step 1: Create Route Matching Types

```rust
// src/web/router/route.rs

use std::collections::HashMap;

/// A segment in a route pattern.
#[derive(Debug, Clone, PartialEq, Eq)]
pub enum RouteSegment {
    /// Exact match: `/users`
    Static(String),
    /// Parameter capture: `/:id`
    Param(String),
    /// Wildcard: `/*path` (captures rest)
    Wildcard(String),
}

/// Compiled route pattern for efficient matching.
#[derive(Debug, Clone)]
pub struct RoutePattern {
    segments: Vec<RouteSegment>,
    param_names: Vec<String>,
}

impl RoutePattern {
    /// Parse a route pattern string.
    pub fn parse(pattern: &str) -> Result<Self, RouteError> {
        let mut segments = Vec::new();
        let mut param_names = Vec::new();

        for part in pattern.split('/').filter(|s| !s.is_empty()) {
            let segment = if let Some(name) = part.strip_prefix(':') {
                if name.is_empty() {
                    return Err(RouteError::InvalidPattern("empty parameter name".into()));
                }
                param_names.push(name.to_string());
                RouteSegment::Param(name.to_string())
            } else if let Some(name) = part.strip_prefix('*') {
                if name.is_empty() {
                    return Err(RouteError::InvalidPattern("empty wildcard name".into()));
                }
                param_names.push(name.to_string());
                RouteSegment::Wildcard(name.to_string())
            } else {
                RouteSegment::Static(part.to_string())
            };
            segments.push(segment);
        }

        Ok(Self { segments, param_names })
    }

    /// Match a path and extract parameters.
    pub fn match_path(&self, path: &str) -> Option<PathParams> {
        let parts: Vec<&str> = path.split('/').filter(|s| !s.is_empty()).collect();
        let mut params = HashMap::new();
        let mut part_idx = 0;

        for segment in &self.segments {
            match segment {
                RouteSegment::Static(expected) => {
                    if part_idx >= parts.len() || parts[part_idx] != expected {
                        return None;
                    }
                    part_idx += 1;
                }
                RouteSegment::Param(name) => {
                    if part_idx >= parts.len() {
                        return None;
                    }
                    params.insert(name.clone(), parts[part_idx].to_string());
                    part_idx += 1;
                }
                RouteSegment::Wildcard(name) => {
                    // Capture all remaining segments
                    let rest = parts[part_idx..].join("/");
                    params.insert(name.clone(), rest);
                    return Some(PathParams(params));
                }
            }
        }

        // Must consume all parts
        if part_idx == parts.len() {
            Some(PathParams(params))
        } else {
            None
        }
    }
}

/// Extracted path parameters.
#[derive(Debug, Clone, Default)]
pub struct PathParams(HashMap<String, String>);

impl PathParams {
    /// Get a parameter value.
    pub fn get(&self, name: &str) -> Option<&str> {
        self.0.get(name).map(|s| s.as_str())
    }

    /// Parse a parameter as a specific type.
    pub fn parse<T: std::str::FromStr>(&self, name: &str) -> Option<T> {
        self.0.get(name).and_then(|s| s.parse().ok())
    }
}
```

### Step 2: Implement Router Core

```rust
// src/web/router/mod.rs

use crate::http::{Method, Request, Response};
use crate::service::{Service, Layer};
use std::future::Future;
use std::pin::Pin;
use std::sync::Arc;

/// Type-erased handler function.
pub type BoxedHandler = Arc<
    dyn Fn(Request, PathParams) -> Pin<Box<dyn Future<Output = Response> + Send>> + Send + Sync
>;

/// A single route entry.
struct RouteEntry {
    pattern: RoutePattern,
    method: MethodFilter,
    handler: BoxedHandler,
}

/// Method filter for routes.
#[derive(Debug, Clone, Copy)]
pub enum MethodFilter {
    Any,
    Specific(Method),
}

impl MethodFilter {
    fn matches(&self, method: &Method) -> bool {
        match self {
            MethodFilter::Any => true,
            MethodFilter::Specific(m) => m == method,
        }
    }
}

/// The main router type.
pub struct Router<S = ()> {
    routes: Vec<RouteEntry>,
    fallback: Option<BoxedHandler>,
    state: S,
    middleware: Vec<Arc<dyn Layer<BoxedHandler, Service = BoxedHandler> + Send + Sync>>,
}

impl Router<()> {
    /// Create a new router.
    pub fn new() -> Self {
        Self {
            routes: Vec::new(),
            fallback: None,
            state: (),
            middleware: Vec::new(),
        }
    }
}

impl<S: Clone + Send + Sync + 'static> Router<S> {
    /// Add state to the router.
    pub fn with_state<S2>(self, state: S2) -> Router<S2> {
        Router {
            routes: self.routes,
            fallback: self.fallback,
            state,
            middleware: self.middleware,
        }
    }

    /// Add a route with a specific method.
    pub fn route<H, T>(mut self, pattern: &str, method: Method, handler: H) -> Self
    where
        H: Handler<T, S> + Send + Sync + 'static,
        T: 'static,
    {
        let pattern = RoutePattern::parse(pattern)
            .expect("invalid route pattern");

        let state = self.state.clone();
        let handler: BoxedHandler = Arc::new(move |req, params| {
            let handler = handler.clone();
            let state = state.clone();
            Box::pin(async move {
                handler.call(req, params, state).await
            })
        });

        self.routes.push(RouteEntry {
            pattern,
            method: MethodFilter::Specific(method),
            handler,
        });
        self
    }

    /// GET route shorthand.
    pub fn get<H, T>(self, pattern: &str, handler: H) -> Self
    where
        H: Handler<T, S> + Send + Sync + 'static,
        T: 'static,
    {
        self.route(pattern, Method::GET, handler)
    }

    /// POST route shorthand.
    pub fn post<H, T>(self, pattern: &str, handler: H) -> Self
    where
        H: Handler<T, S> + Send + Sync + 'static,
        T: 'static,
    {
        self.route(pattern, Method::POST, handler)
    }

    /// PUT route shorthand.
    pub fn put<H, T>(self, pattern: &str, handler: H) -> Self
    where
        H: Handler<T, S> + Send + Sync + 'static,
        T: 'static,
    {
        self.route(pattern, Method::PUT, handler)
    }

    /// DELETE route shorthand.
    pub fn delete<H, T>(self, pattern: &str, handler: H) -> Self
    where
        H: Handler<T, S> + Send + Sync + 'static,
        T: 'static,
    {
        self.route(pattern, Method::DELETE, handler)
    }

    /// Set fallback handler for unmatched routes.
    pub fn fallback<H, T>(mut self, handler: H) -> Self
    where
        H: Handler<T, S> + Send + Sync + 'static,
        T: 'static,
    {
        let state = self.state.clone();
        self.fallback = Some(Arc::new(move |req, params| {
            let handler = handler.clone();
            let state = state.clone();
            Box::pin(async move {
                handler.call(req, params, state).await
            })
        }));
        self
    }

    /// Nest another router under a prefix.
    pub fn nest(mut self, prefix: &str, other: Router<S>) -> Self {
        for entry in other.routes {
            let combined = format!("{}{}", prefix.trim_end_matches('/'),
                                   format!("/{}", entry.pattern.to_string()).as_str());
            let pattern = RoutePattern::parse(&combined)
                .expect("invalid nested pattern");
            self.routes.push(RouteEntry {
                pattern,
                method: entry.method,
                handler: entry.handler,
            });
        }
        self
    }

    /// Match a request to a route.
    pub fn match_route(&self, req: &Request) -> Option<(&BoxedHandler, PathParams)> {
        for entry in &self.routes {
            if entry.method.matches(req.method()) {
                if let Some(params) = entry.pattern.match_path(req.uri().path()) {
                    return Some((&entry.handler, params));
                }
            }
        }
        self.fallback.as_ref().map(|h| (h, PathParams::default()))
    }
}

impl<S: Clone + Send + Sync + 'static> Service<Request> for Router<S> {
    type Response = Response;
    type Error = Infallible;
    type Future = Pin<Box<dyn Future<Output = Result<Response, Infallible>> + Send>>;

    fn poll_ready(&mut self, _cx: &mut Context<'_>) -> Poll<Result<(), Self::Error>> {
        Poll::Ready(Ok(()))
    }

    fn call(&mut self, req: Request) -> Self::Future {
        match self.match_route(&req) {
            Some((handler, params)) => {
                let handler = handler.clone();
                Box::pin(async move {
                    Ok(handler(req, params).await)
                })
            }
            None => {
                Box::pin(async {
                    Ok(Response::builder()
                        .status(404)
                        .body("Not Found".into())
                        .unwrap())
                })
            }
        }
    }
}
```

