// src/lab/network/config.rs

use std::time::Duration;
use crate::util::DetRng;

/// Configuration for the simulated network
#[derive(Clone, Debug)]
pub struct NetworkConfig {
    /// Random seed for deterministic simulation
    pub seed: u64,

    /// Default network conditions between hosts
    pub default_conditions: NetworkConditions,

    /// Whether to capture trace for replay
    pub capture_trace: bool,

    /// Maximum queue depth per link
    pub max_queue_depth: usize,

    /// Simulation tick resolution
    pub tick_resolution: Duration,

    /// Enable bandwidth simulation
    pub enable_bandwidth: bool,

    /// Default bandwidth per link (bytes/second)
    pub default_bandwidth: u64,
}

impl Default for NetworkConfig {
    fn default() -> Self {
        Self {
            seed: 0xNETWORK_SEED,
            default_conditions: NetworkConditions::ideal(),
            capture_trace: false,
            max_queue_depth: 10_000,
            tick_resolution: Duration::from_micros(100),
            enable_bandwidth: false,
            default_bandwidth: 1_000_000_000, // 1 Gbps
        }
    }
}

/// Network conditions between two hosts
#[derive(Clone, Debug)]
pub struct NetworkConditions {
    /// Latency model for this link
    pub latency: LatencyModel,

    /// Packet loss probability (0.0 - 1.0)
    pub packet_loss: f64,

    /// Packet corruption probability (0.0 - 1.0)  
    pub packet_corrupt: f64,

    /// Packet reordering probability (0.0 - 1.0)
    pub packet_reorder: f64,

    /// Maximum packets in flight
    pub max_in_flight: usize,

    /// Bandwidth limit (bytes/second), None = unlimited
    pub bandwidth: Option<u64>,

    /// Jitter model for variable latency
    pub jitter: Option<JitterModel>,
}

impl NetworkConditions {
    /// Perfect network - no latency, loss, or corruption
    pub fn ideal() -> Self {
        Self {
            latency: LatencyModel::Fixed(Duration::ZERO),
            packet_loss: 0.0,
            packet_corrupt: 0.0,
            packet_reorder: 0.0,
            max_in_flight: usize::MAX,
            bandwidth: None,
            jitter: None,
        }
    }

    /// Local network - 1ms latency
    pub fn local() -> Self {
        Self {
            latency: LatencyModel::Fixed(Duration::from_millis(1)),
            ..Self::ideal()
        }
    }

    /// LAN - 1-5ms latency, very low loss
    pub fn lan() -> Self {
        Self {
            latency: LatencyModel::Uniform {
                min: Duration::from_millis(1),
                max: Duration::from_millis(5),
            },
            packet_loss: 0.0001,
            bandwidth: Some(1_000_000_000), // 1 Gbps
            ..Self::ideal()
        }
    }

    /// WAN - 20-100ms latency, low loss
    pub fn wan() -> Self {
        Self {
            latency: LatencyModel::Normal {
                mean: Duration::from_millis(50),
                std_dev: Duration::from_millis(20),
            },
            packet_loss: 0.001,
            packet_reorder: 0.001,
            bandwidth: Some(100_000_000), // 100 Mbps
            jitter: Some(JitterModel::Uniform {
                max: Duration::from_millis(10),
            }),
            ..Self::ideal()
        }
    }

    /// Lossy - high packet loss (10%)
    pub fn lossy() -> Self {
        Self {
            packet_loss: 0.1,
            ..Self::lan()
        }
    }

    /// Satellite - high latency (500ms+), moderate loss
    pub fn satellite() -> Self {
        Self {
            latency: LatencyModel::Normal {
                mean: Duration::from_millis(600),
                std_dev: Duration::from_millis(50),
            },
            packet_loss: 0.01,
            bandwidth: Some(10_000_000), // 10 Mbps
            ..Self::ideal()
        }
    }

    /// Congested network
    pub fn congested() -> Self {
        Self {
            latency: LatencyModel::Normal {
                mean: Duration::from_millis(100),
                std_dev: Duration::from_millis(50),
            },
            packet_loss: 0.05,
            packet_reorder: 0.02,
            bandwidth: Some(1_000_000), // 1 Mbps
            max_in_flight: 100,
            jitter: Some(JitterModel::Bursty {
                normal_jitter: Duration::from_millis(5),
                burst_jitter: Duration::from_millis(100),
                burst_probability: 0.1,
            }),
            ..Self::ideal()
        }
    }
}

/// Model for latency distribution
#[derive(Clone, Debug)]
pub enum LatencyModel {
    /// Fixed latency
    Fixed(Duration),

    /// Uniform distribution between min and max
    Uniform { min: Duration, max: Duration },

    /// Normal (Gaussian) distribution
    Normal { mean: Duration, std_dev: Duration },

    /// Log-normal distribution (common in real networks)
    LogNormal { mu: f64, sigma: f64 },

    /// Bimodal - two peaks (models route switching)
    Bimodal {
        low: Duration,
        high: Duration,
        high_probability: f64,
    },
}

impl LatencyModel {
    /// Sample latency using the given RNG
    pub fn sample(&self, rng: &mut DetRng) -> Duration {
        match self {
            Self::Fixed(d) => *d,

            Self::Uniform { min, max } => {
                let range = max.as_nanos() - min.as_nanos();
                let offset = (rng.next_u64() as u128) % (range + 1);
                Duration::from_nanos((min.as_nanos() + offset) as u64)
            }

            Self::Normal { mean, std_dev } => {
                // Box-Muller transform for normal distribution
                let u1 = (rng.next_u64() as f64) / (u64::MAX as f64);
                let u2 = (rng.next_u64() as f64) / (u64::MAX as f64);

                let z = (-2.0 * u1.ln()).sqrt() * (2.0 * std::f64::consts::PI * u2).cos();
                let sample = mean.as_secs_f64() + std_dev.as_secs_f64() * z;

                Duration::from_secs_f64(sample.max(0.0))
            }

            Self::LogNormal { mu, sigma } => {
                // Sample normal, then exponentiate
                let u1 = (rng.next_u64() as f64) / (u64::MAX as f64);
                let u2 = (rng.next_u64() as f64) / (u64::MAX as f64);

                let z = (-2.0 * u1.ln()).sqrt() * (2.0 * std::f64::consts::PI * u2).cos();
                let sample = (mu + sigma * z).exp();

                Duration::from_secs_f64(sample)
            }

            Self::Bimodal { low, high, high_probability } => {
                let r = (rng.next_u64() as f64) / (u64::MAX as f64);
                if r < *high_probability { *high } else { *low }
            }
        }
    }
}

/// Jitter model for variable latency
#[derive(Clone, Debug)]
pub enum JitterModel {
    /// Uniform jitter up to max
    Uniform { max: Duration },

    /// Bursty jitter (occasional spikes)
    Bursty {
        normal_jitter: Duration,
        burst_jitter: Duration,
        burst_probability: f64,
    },
}

impl JitterModel {
    pub fn sample(&self, rng: &mut DetRng) -> Duration {
        match self {
            Self::Uniform { max } => {
                let nanos = (rng.next_u64() as u128) % (max.as_nanos() + 1);
                Duration::from_nanos(nanos as u64)
            }

            Self::Bursty { normal_jitter, burst_jitter, burst_probability } => {
                let r = (rng.next_u64() as f64) / (u64::MAX as f64);
                let max = if r < *burst_probability { *burst_jitter } else { *normal_jitter };
                let nanos = (rng.next_u64() as u128) % (max.as_nanos() + 1);
                Duration::from_nanos(nanos as u64)
            }
        }
    }
}
