### Network Coordinator

```rust
// src/lab/network/network.rs

use super::*;
use bytes::Bytes;
use std::collections::{HashMap, BinaryHeap, HashSet};
use std::cmp::Reverse;
use crate::types::Time;
use crate::util::DetRng;

/// A simulated network coordinating multiple hosts
pub struct SimulatedNetwork {
    config: NetworkConfig,
    rng: DetRng,

    /// All hosts in the network
    hosts: HashMap<HostId, SimulatedHost>,

    /// Per-link conditions (overrides default)
    link_conditions: HashMap<(HostId, HostId), NetworkConditions>,

    /// Per-link bandwidth limiters
    bandwidth_limiters: HashMap<(HostId, HostId), BandwidthLimiter>,

    /// Active network partitions
    partitions: Vec<Partition>,

    /// Scheduled events (time, event)
    event_queue: BinaryHeap<Reverse<(Time, NetworkEvent)>>,

    /// Current virtual time
    current_time: Time,

    /// Captured trace for replay
    trace: Option<NetworkTrace>,

    /// Network metrics
    metrics: NetworkMetrics,

    /// Next host ID
    next_host_id: u64,

    /// Next packet ID
    next_packet_id: u64,
}

impl SimulatedNetwork {
    pub fn new(config: NetworkConfig) -> Self {
        let rng = DetRng::new(config.seed);
        let trace = if config.capture_trace {
            Some(NetworkTrace::new())
        } else {
            None
        };

        Self {
            config,
            rng,
            hosts: HashMap::new(),
            link_conditions: HashMap::new(),
            bandwidth_limiters: HashMap::new(),
            partitions: Vec::new(),
            event_queue: BinaryHeap::new(),
            current_time: Time::ZERO,
            trace,
            metrics: NetworkMetrics::default(),
            next_host_id: 0,
            next_packet_id: 0,
        }
    }

    /// Add a host to the network
    pub fn add_host(&mut self, name: &str) -> HostId {
        let id = HostId(self.next_host_id);
        self.next_host_id += 1;

        self.hosts.insert(id, SimulatedHost::new(id, name.to_string()));

        // Initialize bandwidth limiters for this host
        if self.config.enable_bandwidth {
            for &other_id in self.hosts.keys() {
                if other_id != id {
                    let bw = self.config.default_bandwidth;
                    self.bandwidth_limiters.insert((id, other_id), BandwidthLimiter::new(bw, bw / 10));
                    self.bandwidth_limiters.insert((other_id, id), BandwidthLimiter::new(bw, bw / 10));
                }
            }
        }

        if let Some(ref mut trace) = self.trace {
            trace.record(TraceEntry::HostAdded { id, name: name.to_string(), time: self.current_time });
        }

        id
    }

    /// Send a packet from one host to another
    pub fn send(&mut self, from: HostId, to: HostId, payload: Bytes) {
        let packet_id = self.next_packet_id;
        self.next_packet_id += 1;

        let conditions = self.get_conditions(from, to);

        // Check partition
        if self.is_partitioned(from, to) {
            self.metrics.packets_dropped += 1;
            if let Some(ref mut trace) = self.trace {
                trace.record(TraceEntry::PacketDropped { 
                    id: packet_id, 
                    from, 
                    to, 
                    reason: "partition".into(),
                    time: self.current_time,
                });
            }
            return;
        }

        // Check packet loss
        if self.rng.next_f64() < conditions.packet_loss {
            self.metrics.packets_dropped += 1;
            if let Some(ref mut trace) = self.trace {
                trace.record(TraceEntry::PacketDropped { 
                    id: packet_id, 
                    from, 
                    to, 
                    reason: "loss".into(),
                    time: self.current_time,
                });
            }
            return;
        }

        // Calculate base latency
        let mut latency = conditions.latency.sample(&mut self.rng);

        // Add jitter
        if let Some(ref jitter) = conditions.jitter {
            latency += jitter.sample(&mut self.rng);
        }

        // Apply bandwidth limiting
        if self.config.enable_bandwidth {
            if let Some(limiter) = self.bandwidth_limiters.get_mut(&(from, to)) {
                match limiter.try_transmit(payload.len(), self.current_time) {
                    TransmitResult::Immediate => {}
                    TransmitResult::Delayed(delay) => {
                        latency += delay;
                    }
                    TransmitResult::Dropped => {
                        self.metrics.packets_dropped += 1;
                        return;
                    }
                }
            }
        }

        // Check corruption
        let payload = if self.rng.next_f64() < conditions.packet_corrupt {
            self.metrics.packets_corrupted += 1;
            corrupt_payload(&payload, &mut self.rng)
        } else {
            payload
        };

        // Schedule delivery
        let delivery_time = self.current_time + latency;

        let packet = Packet {
            id: packet_id,
            from,
            to,
            payload,
            sent_at: self.current_time,
            received_at: delivery_time,
        };

        self.event_queue.push(Reverse((delivery_time, NetworkEvent::Deliver(packet.clone()))));
        self.metrics.packets_sent += 1;

        if let Some(ref mut trace) = self.trace {
            trace.record(TraceEntry::PacketSent { 
                id: packet_id, 
                from, 
                to, 
                size: packet.payload.len(),
                latency,
                time: self.current_time,
            });
        }
    }

    /// Advance simulation by one tick
    pub fn step(&mut self) {
        self.current_time += self.config.tick_resolution;
        self.process_events();
    }

    /// Advance simulation to specific time
    pub fn advance_to(&mut self, time: Time) {
        while self.current_time < time {
            self.step();
        }
    }

    /// Run simulation for specified duration
    pub fn run_for(&mut self, duration: Duration) {
        let end_time = self.current_time + duration;
        self.advance_to(end_time);
    }

    /// Process all events at or before current time
    fn process_events(&mut self) {
        while let Some(Reverse((time, event))) = self.event_queue.peek() {
            if *time > self.current_time {
                break;
            }

            let Reverse((_, event)) = self.event_queue.pop().unwrap();

            match event {
                NetworkEvent::Deliver(packet) => {
                    if let Some(host) = self.hosts.get_mut(&packet.to) {
                        host.receive(packet.clone());
                        self.metrics.packets_delivered += 1;

                        if let Some(ref mut trace) = self.trace {
                            trace.record(TraceEntry::PacketDelivered { 
                                id: packet.id, 
                                time: self.current_time,
                            });
                        }
                    }
                }

                NetworkEvent::InjectFault(fault) => {
                    self.apply_fault(&fault);
                }
            }
        }
    }

    /// Inject a fault into the network
    pub fn inject_fault(&mut self, fault: &Fault) {
        if let Some(ref mut trace) = self.trace {
            trace.record(TraceEntry::FaultInjected { 
                fault: fault.clone(), 
                time: self.current_time,
            });
        }

        self.apply_fault(fault);
    }

    /// Schedule a fault for future injection
    pub fn schedule_fault(&mut self, fault: Fault, at: Time) {
        self.event_queue.push(Reverse((at, NetworkEvent::InjectFault(fault))));
    }

    fn apply_fault(&mut self, fault: &Fault) {
        match fault {
            Fault::Partition { hosts_a, hosts_b } => {
                self.partitions.push(Partition {
                    hosts_a: hosts_a.iter().copied().collect(),
                    hosts_b: hosts_b.iter().copied().collect(),
                });
            }

            Fault::Heal { hosts_a, hosts_b } => {
                self.partitions.retain(|p| {
                    !(p.hosts_a == hosts_a.iter().copied().collect::<HashSet<_>>() &&
                      p.hosts_b == hosts_b.iter().copied().collect::<HashSet<_>>())
                });
            }

            Fault::HostCrash { host } => {
                if let Some(h) = self.hosts.get_mut(host) {
                    h.crash();
                }
            }

            Fault::HostRestart { host } => {
                if let Some(h) = self.hosts.get_mut(host) {
                    h.restart();
                }
            }

            Fault::LinkCondition { from, to, conditions } => {
                self.link_conditions.insert((*from, *to), conditions.clone());
            }

            Fault::LinkBandwidth { from, to, bandwidth } => {
                if let Some(limiter) = self.bandwidth_limiters.get_mut(&(*from, *to)) {
                    *limiter = BandwidthLimiter::new(*bandwidth, *bandwidth / 10);
                }
            }
        }
    }

    fn is_partitioned(&self, from: HostId, to: HostId) -> bool {
        self.partitions.iter().any(|p| {
            (p.hosts_a.contains(&from) && p.hosts_b.contains(&to)) ||
            (p.hosts_b.contains(&from) && p.hosts_a.contains(&to))
        })
    }

    fn get_conditions(&self, from: HostId, to: HostId) -> NetworkConditions {
        self.link_conditions
            .get(&(from, to))
            .cloned()
            .unwrap_or_else(|| self.config.default_conditions.clone())
    }

    /// Get current metrics
    pub fn metrics(&self) -> &NetworkMetrics {
        &self.metrics
    }

    /// Get captured trace
    pub fn trace(&self) -> Option<&NetworkTrace> {
        self.trace.as_ref()
    }

    /// Get current virtual time
    pub fn virtual_now(&self) -> Time {
        self.current_time
    }

    /// Get host by ID
    pub fn host(&self, id: HostId) -> Option<&SimulatedHost> {
        self.hosts.get(&id)
    }

    /// Get mutable host by ID
    pub fn host_mut(&mut self, id: HostId) -> Option<&mut SimulatedHost> {
        self.hosts.get_mut(&id)
    }
}

fn corrupt_payload(payload: &Bytes, rng: &mut DetRng) -> Bytes {
    let mut data = payload.to_vec();
    if !data.is_empty() {
        let idx = rng.next_usize(data.len());
        data[idx] ^= 1 << (rng.next_u64() % 8);
    }
    Bytes::from(data)
}

/// Network event for the simulation queue
#[derive(Clone, Debug, PartialEq, Eq, PartialOrd, Ord)]
enum NetworkEvent {
    Deliver(Packet),
    InjectFault(Fault),
}

/// Fault types that can be injected
#[derive(Clone, Debug, PartialEq, Eq, PartialOrd, Ord)]
pub enum Fault {
    /// Network partition between two sets of hosts
    Partition { hosts_a: Vec<HostId>, hosts_b: Vec<HostId> },

    /// Heal a partition
    Heal { hosts_a: Vec<HostId>, hosts_b: Vec<HostId> },

    /// Crash a host (drops all pending messages)
    HostCrash { host: HostId },

    /// Restart a crashed host
    HostRestart { host: HostId },

    /// Change link conditions
    LinkCondition { from: HostId, to: HostId, conditions: NetworkConditions },

    /// Change link bandwidth
    LinkBandwidth { from: HostId, to: HostId, bandwidth: u64 },
}
