    #[test]
    fn concurrent_acquire_release_safe() {
        use std::thread;

        let bh = Arc::new(Bulkhead::new(BulkheadPolicy {
            max_concurrent: 10,
            ..Default::default()
        }));

        let handles: Vec<_> = (0..100).map(|_| {
            let bh = bh.clone();
            thread::spawn(move || {
                for _ in 0..100 {
                    if let Some(permit) = bh.try_acquire(1) {
                        // Simulate work
                        std::thread::yield_now();
                        permit.release_to(&bh);
                    }
                }
            })
        }).collect();

        for h in handles {
            h.join().unwrap();
        }

        // All permits should be returned
        assert_eq!(bh.available_permits.load(Ordering::SeqCst), 10);
    }

    #[test]
    fn concurrent_never_exceeds_max() {
        use std::thread;
        use std::sync::atomic::AtomicU32;

        let bh = Arc::new(Bulkhead::new(BulkheadPolicy {
            max_concurrent: 5,
            ..Default::default()
        }));

        let current = Arc::new(AtomicU32::new(0));
        let peak = Arc::new(AtomicU32::new(0));

        let handles: Vec<_> = (0..50).map(|_| {
            let bh = bh.clone();
            let current = current.clone();
            let peak = peak.clone();

            thread::spawn(move || {
                for _ in 0..20 {
                    if let Some(permit) = bh.try_acquire(1) {
                        let c = current.fetch_add(1, Ordering::SeqCst) + 1;
                        peak.fetch_max(c, Ordering::SeqCst);

                        std::thread::yield_now();

                        current.fetch_sub(1, Ordering::SeqCst);
                        permit.release_to(&bh);
                    }
                }
            })
        }).collect();

        for h in handles {
            h.join().unwrap();
        }

        assert!(peak.load(Ordering::SeqCst) <= 5);
    }

    // =========================================================================
    // Error Display Tests
    // =========================================================================

    #[test]
    fn error_display() {
        let err: BulkheadError<&str> = BulkheadError::QueueFull;
        assert_eq!(format!("{}", err), "bulkhead queue full");

        let err: BulkheadError<&str> = BulkheadError::QueueTimeout { 
            waited: Duration::from_millis(500) 
        };
        assert!(format!("{}", err).contains("timeout"));

        let err: BulkheadError<&str> = BulkheadError::Cancelled;
        assert!(format!("{}", err).contains("cancelled"));

        let err: BulkheadError<&str> = BulkheadError::Inner("inner error");
        assert_eq!(format!("{}", err), "inner error");
    }
}
