```rust
impl StateDecoder {
    /// Decodes collected symbols to reconstruct the original data.
    pub fn decode(&mut self, params: &ObjectParams) -> Result<Vec<u8>, Error> {
        if !self.can_decode() {
            return Err(Error::new(ErrorKind::InsufficientSymbols)
                .with_context(format!(
                    "need {} symbols, have {}",
                    self.symbols_needed(params),
                    self.symbols_received()
                )));
        }

        self.decoder_state = DecoderState::Decoding;

        // RaptorQ decoding algorithm (simplified):
        // 1. Construct coefficient matrix from symbol ESIs
        // 2. Solve system using Gaussian elimination
        // 3. Extract original source blocks

        let decoded_data = self.raptorq_decode(params)?;

        // Verify integrity if configured
        if self.config.verify_integrity {
            self.verify_decoded_data(&decoded_data, params)?;
        }

        self.decoder_state = DecoderState::Complete;
        Ok(decoded_data)
    }

    /// Convenience method to decode directly to RegionSnapshot.
    pub fn decode_snapshot(
        &mut self,
        params: &ObjectParams,
    ) -> Result<RegionSnapshot, Error> {
        let data = self.decode(params)?;
        RegionSnapshot::from_bytes(&data)
    }
}
