### Shutdown Controller

```rust
// signal/src/shutdown.rs

use std::sync::Arc;
use tokio::sync::{broadcast, watch};

/// Controller for coordinated graceful shutdown.
///
/// This provides a clean way to propagate shutdown signals through an application.
pub struct ShutdownController {
    /// Sends shutdown signal
    shutdown_tx: broadcast::Sender<()>,
    /// Tracks whether shutdown has been initiated
    initiated: watch::Sender<bool>,
}

impl ShutdownController {
    /// Create a new shutdown controller.
    pub fn new() -> Self {
        let (shutdown_tx, _) = broadcast::channel(1);
        let (initiated, _) = watch::channel(false);

        tracing::debug!("Created shutdown controller");

        ShutdownController {
            shutdown_tx,
            initiated,
        }
    }

    /// Get a handle for receiving shutdown notifications.
    pub fn subscribe(&self) -> ShutdownReceiver {
        ShutdownReceiver {
            rx: self.shutdown_tx.subscribe(),
            initiated: self.initiated.subscribe(),
        }
    }

    /// Initiate shutdown.
    pub fn shutdown(&self) {
        tracing::info!("Initiating shutdown");
        self.initiated.send_replace(true);
        let _ = self.shutdown_tx.send(());
    }

    /// Check if shutdown has been initiated.
    pub fn is_shutting_down(&self) -> bool {
        *self.initiated.borrow()
    }

    /// Listen for shutdown signals and initiate shutdown.
    ///
    /// This spawns a background task that listens for:
    /// - SIGTERM (Unix)
    /// - SIGINT (Unix) / Ctrl+C (all platforms)
    pub fn listen_for_signals(self: &Arc<Self>) {
        let controller = self.clone();

        tokio::spawn(async move {
            #[cfg(unix)]
            {
                let mut sigterm = crate::sigterm().expect("Failed to register SIGTERM handler");
                let mut sigint = crate::sigint().expect("Failed to register SIGINT handler");

                tokio::select! {
                    _ = sigterm.recv() => {
                        tracing::info!("Received SIGTERM");
                    }
                    _ = sigint.recv() => {
                        tracing::info!("Received SIGINT");
                    }
                }
            }

            #[cfg(not(unix))]
            {
                crate::ctrl_c().await.expect("Failed to wait for Ctrl+C");
            }

            controller.shutdown();
        });

        tracing::debug!("Listening for shutdown signals");
    }
}

impl Default for ShutdownController {
    fn default() -> Self {
        Self::new()
    }
}

/// Receiver for shutdown notifications.
pub struct ShutdownReceiver {
    rx: broadcast::Receiver<()>,
    initiated: watch::Receiver<bool>,
}

impl ShutdownReceiver {
    /// Wait for shutdown to be initiated.
    pub async fn wait(&mut self) {
        if *self.initiated.borrow() {
            return;
        }

        // Wait for either the broadcast or the watch to signal
        tokio::select! {
            _ = self.rx.recv() => {}
            _ = self.initiated.changed() => {}
        }
    }

    /// Check if shutdown has been initiated.
    pub fn is_shutting_down(&self) -> bool {
        *self.initiated.borrow()
    }

    /// Clone this receiver.
    pub fn clone(&self) -> Self {
        ShutdownReceiver {
            rx: self.rx.resubscribe(),
            initiated: self.initiated.clone(),
        }
    }
}

impl Clone for ShutdownReceiver {
    fn clone(&self) -> Self {
        self.clone()
    }
}
```

### Graceful Shutdown Helper

```rust
// signal/src/graceful.rs

use std::future::Future;
use std::time::Duration;

use crate::ShutdownReceiver;

/// Run a future with graceful shutdown support.
///
/// When shutdown is signaled, the future is given `grace_period` to complete
/// before being cancelled.
pub async fn with_graceful_shutdown<F, T>(
    fut: F,
    mut shutdown: ShutdownReceiver,
    grace_period: Duration,
) -> Option<T>
where
    F: Future<Output = T>,
{
    tokio::select! {
        result = fut => {
            Some(result)
        }
        _ = shutdown.wait() => {
            tracing::info!(
                grace_period_ms = grace_period.as_millis(),
                "Shutdown signaled, entering grace period"
            );
            None
        }
    }
}

/// Wrapper for servers that supports graceful shutdown.
pub struct GracefulServer<S> {
    server: S,
    shutdown: ShutdownReceiver,
    grace_period: Duration,
}

impl<S> GracefulServer<S> {
    /// Create a new graceful server wrapper.
    pub fn new(server: S, shutdown: ShutdownReceiver) -> Self {
        GracefulServer {
            server,
            shutdown,
            grace_period: Duration::from_secs(30),
        }
    }

    /// Set the grace period.
    pub fn grace_period(mut self, duration: Duration) -> Self {
        self.grace_period = duration;
        self
    }
}

impl<S, F> GracefulServer<S>
where
    S: FnOnce() -> F,
    F: Future<Output = ()>,
{
    /// Run the server with graceful shutdown.
    pub async fn run(self) {
        let server_fut = (self.server)();

        tokio::select! {
            _ = server_fut => {
                tracing::info!("Server finished normally");
            }
            _ = self.shutdown.clone().wait() => {
                tracing::info!("Shutdown signaled, stopping server");
                // Give ongoing requests time to complete
                tokio::time::sleep(self.grace_period).await;
                tracing::info!("Grace period elapsed");
            }
        }
    }
}
```

