    fn test_dispatch_result_quorum() {
        let result = DispatchResult {
            successes: 3,
            failures: 1,
            sent_to: vec![EndpointId(1), EndpointId(2), EndpointId(3)],
            failed_endpoints: vec![],
            duration: Time::ZERO,
        };

        assert!(result.quorum_reached(2));
