### SYNC-003: RwLock Read Concurrency
```rust
conformance_test! {
    id: "sync-003",
    name: "RwLock concurrent reads",
    description: "Multiple readers can hold lock simultaneously",
    category: TestCategory::Sync,
    tags: ["rwlock", "read"],
    expected: "All readers can access data concurrently",
    test: |rt| {
        rt.block_on(async {
            let lock = Arc::new(rt.rwlock(42i32));
            let active_readers = Arc::new(AtomicU32::new(0));
            let max_concurrent = Arc::new(AtomicU32::new(0));

            let handles: Vec<_> = (0..10)
                .map(|_| {
                    let lock = lock.clone();
                    let active = active_readers.clone();
                    let max = max_concurrent.clone();
                    rt.spawn(async move {
                        let guard = lock.read().await;
                        let current = active.fetch_add(1, Ordering::SeqCst) + 1;
                        max.fetch_max(current, Ordering::SeqCst);

                        rt.sleep(Duration::from_millis(10)).await;
                        assert_eq!(*guard, 42);

                        active.fetch_sub(1, Ordering::SeqCst);
                    })
                })
                .collect();

            join_all(handles).await;

            let max = max_concurrent.load(Ordering::SeqCst);
            checkpoint("max_concurrent_readers", json!({"value": max}));
            assert!(max > 1, "Should have concurrent readers");
            TestResult::passed()
        })
    }
}
