### SYNC-006: Barrier Synchronization
```rust
conformance_test! {
    id: "sync-006",
    name: "Barrier synchronization",
    description: "All tasks wait at barrier until all arrive",
    category: TestCategory::Sync,
    tags: ["barrier"],
    expected: "Tasks proceed only after all reach barrier",
    test: |rt| {
        rt.block_on(async {
            let barrier = Arc::new(rt.barrier(10));
            let before_count = Arc::new(AtomicU32::new(0));
            let after_count = Arc::new(AtomicU32::new(0));

            let handles: Vec<_> = (0..10)
                .map(|i| {
                    let barrier = barrier.clone();
                    let before = before_count.clone();
                    let after = after_count.clone();
                    rt.spawn(async move {
                        // Stagger arrivals
                        rt.sleep(Duration::from_millis(i as u64 * 10)).await;
                        before.fetch_add(1, Ordering::SeqCst);

                        barrier.wait().await;

                        // After barrier, all should have arrived
                        let before_val = before.load(Ordering::SeqCst);
                        after.fetch_add(1, Ordering::SeqCst);
                        before_val
                    })
                })
                .collect();

            let results: Vec<_> = join_all(handles).await;

            // All tasks should see 10 arrivals before barrier
            assert!(results.iter().all(|&r| r == 10));
            TestResult::passed()
        })
    }
}
