```rust
/// Test case: Sleep accuracy
#[conformance_test]
async fn sleep_accuracy() -> TestResult {
    let durations = [
        Duration::from_millis(1),
        Duration::from_millis(10),
        Duration::from_millis(100),
        Duration::from_secs(1),
    ];

    for expected in durations {
        let start = Instant::now();
        sleep(expected).await;
        let elapsed = start.elapsed();

        // Allow 20% tolerance
        let lower = expected.mul_f64(0.8);
        let upper = expected.mul_f64(1.2);
        assert!(elapsed >= lower && elapsed <= upper,
            "sleep({:?}) took {:?}", expected, elapsed);
    }
    Ok(())
}

/// Test case: Interval tick consistency
#[conformance_test]
async fn interval_consistency() -> TestResult {
    let mut interval = interval(Duration::from_millis(10));
    let mut ticks = Vec::new();

    for _ in 0..10 {
        interval.tick().await;
        ticks.push(Instant::now());
    }

    // Verify spacing between ticks
    for window in ticks.windows(2) {
        let delta = window[1] - window[0];
        assert!(delta >= Duration::from_millis(8));
        assert!(delta <= Duration::from_millis(15));
    }
    Ok(())
}
