```rust
/// Benchmark definition
pub struct Benchmark {
    pub name: &'static str,
    pub description: &'static str,
    pub warmup_iterations: u32,
    pub measurement_iterations: u32,
    pub workload: Box<dyn Fn() -> BoxFuture<'static, ()>>,
}

/// Benchmark result
pub struct BenchmarkResult {
    pub name: String,
    pub asupersync_times: Vec<Duration>,
    pub tokio_times: Vec<Duration>,
    pub asupersync_stats: Stats,
    pub tokio_stats: Stats,
}

pub struct Stats {
    pub min: Duration,
    pub max: Duration,
    pub mean: Duration,
    pub median: Duration,
    pub p95: Duration,
    pub p99: Duration,
    pub std_dev: Duration,
}

impl BenchmarkResult {
    pub fn speedup(&self) -> f64 {
        self.tokio_stats.mean.as_nanos() as f64 /
        self.asupersync_stats.mean.as_nanos() as f64
    }

    pub fn report(&self) -> String {
        format!(
            "{}: asupersync={:?} tokio={:?} speedup={:.2}x",
            self.name,
            self.asupersync_stats.mean,
            self.tokio_stats.mean,
            self.speedup()
        )
    }
}
