# Combination and Buffering Combinators

## Overview
Combinators for merging streams, buffering, and concurrent processing.

## Implementation Steps

### Step 1: Chain Combinator
```rust
/// Chain two streams together
#[pin_project]
pub struct Chain<S1, S2> {
    #[pin]
    first: Option<S1>,
    #[pin]
    second: S2,
}

impl<S1, S2> Chain<S1, S2> {
    pub fn new(first: S1, second: S2) -> Self {
        Self {
            first: Some(first),
            second,
        }
    }
}

impl<S1, S2> Stream for Chain<S1, S2>
where
    S1: Stream,
    S2: Stream<Item = S1::Item>,
{
    type Item = S1::Item;

    fn poll_next(self: Pin<&mut Self>, cx: &mut Context<'_>) -> Poll<Option<Self::Item>> {
        let mut this = self.project();

        if let Some(first) = this.first.as_mut().as_pin_mut() {
            match first.poll_next(cx) {
                Poll::Ready(Some(item)) => return Poll::Ready(Some(item)),
                Poll::Ready(None) => {
                    this.first.set(None);
                }
                Poll::Pending => return Poll::Pending,
            }
        }

        this.second.poll_next(cx)
    }
}

// Extension method
fn chain<S2>(self, other: S2) -> Chain<Self, S2>
where
    Self: Sized,
    S2: Stream<Item = Self::Item>,
{
    Chain::new(self, other)
}
```

### Step 2: Zip Combinator
```rust
/// Zip two streams together
#[pin_project]
pub struct Zip<S1, S2> {
    #[pin]
    stream1: S1,
    #[pin]
    stream2: S2,
    queued1: Option<S1::Item>,
    queued2: Option<S2::Item>,
}

impl<S1: Stream, S2: Stream> Stream for Zip<S1, S2> {
    type Item = (S1::Item, S2::Item);

    fn poll_next(self: Pin<&mut Self>, cx: &mut Context<'_>) -> Poll<Option<Self::Item>> {
        let mut this = self.project();

        // Poll first stream if needed
        if this.queued1.is_none() {
            match this.stream1.as_mut().poll_next(cx) {
                Poll::Ready(Some(item)) => *this.queued1 = Some(item),
                Poll::Ready(None) => return Poll::Ready(None),
                Poll::Pending => {}
            }
        }

        // Poll second stream if needed
        if this.queued2.is_none() {
            match this.stream2.as_mut().poll_next(cx) {
                Poll::Ready(Some(item)) => *this.queued2 = Some(item),
                Poll::Ready(None) => return Poll::Ready(None),
                Poll::Pending => {}
            }
        }

        // If both ready, emit
        if this.queued1.is_some() && this.queued2.is_some() {
            let item1 = this.queued1.take().unwrap();
            let item2 = this.queued2.take().unwrap();
            Poll::Ready(Some((item1, item2)))
        } else {
            Poll::Pending
        }
    }
}
```

### Step 3: Merge Combinator (Non-deterministic)
```rust
/// Merge multiple streams (round-robin polling)
#[pin_project]
pub struct Merge<S> {
    #[pin]
    streams: Vec<S>,
    next_poll: usize,
}

impl<S: Stream> Stream for Merge<S> {
    type Item = S::Item;

    fn poll_next(self: Pin<&mut Self>, cx: &mut Context<'_>) -> Poll<Option<Self::Item>> {
        let mut this = self.project();
        let len = this.streams.len();

        if len == 0 {
            return Poll::Ready(None);
        }

        let start = *this.next_poll;

        for i in 0..len {
            let idx = (start + i) % len;

            // SAFETY: We're only accessing one stream at a time
            let stream = unsafe { 
                this.streams.as_mut().get_unchecked_mut().get_unchecked_mut(idx)
            };

            match Pin::new(stream).poll_next(cx) {
                Poll::Ready(Some(item)) => {
                    *this.next_poll = (idx + 1) % len;
                    return Poll::Ready(Some(item));
                }
                Poll::Ready(None) => {
                    // Stream exhausted, remove it
                    // (simplified - real impl needs careful handling)
                }
                Poll::Pending => {}
            }
        }

        Poll::Pending
    }
}

/// Merge helper function
pub fn merge<S: Stream>(streams: impl IntoIterator<Item = S>) -> Merge<S> {
    Merge {
        streams: streams.into_iter().collect(),
        next_poll: 0,
    }
}
```

### Step 4: Buffered Combinator
```rust
/// Process stream items with limited concurrency
#[pin_project]
pub struct Buffered<S>
where
    S: Stream,
    S::Item: Future,
{
    #[pin]
    stream: S,
    in_progress: FuturesUnordered<<S::Item as Future>::Output>,
    limit: usize,
}

impl<S> Buffered<S>
where
    S: Stream,
    S::Item: Future,
{
    pub fn new(stream: S, limit: usize) -> Self {
        Self {
            stream,
            in_progress: FuturesUnordered::new(),
            limit,
        }
    }
}

impl<S> Stream for Buffered<S>
where
    S: Stream,
    S::Item: Future,
{
    type Item = <S::Item as Future>::Output;

    fn poll_next(self: Pin<&mut Self>, cx: &mut Context<'_>) -> Poll<Option<Self::Item>> {
        let mut this = self.project();

        // Try to spawn more futures if under limit
        while this.in_progress.len() < *this.limit {
            match this.stream.as_mut().poll_next(cx) {
                Poll::Ready(Some(fut)) => {
                    this.in_progress.push(fut);
                }
                Poll::Ready(None) => break,
                Poll::Pending => break,
            }
        }

        // Check for completed futures
        match Pin::new(&mut this.in_progress).poll_next(cx) {
            Poll::Ready(Some(output)) => Poll::Ready(Some(output)),
            Poll::Ready(None) if this.in_progress.is_empty() => {
                // Check if stream is also done
                match this.stream.as_mut().poll_next(cx) {
                    Poll::Ready(None) => Poll::Ready(None),
                    _ => Poll::Pending,
                }
            }
            _ => Poll::Pending,
        }
    }
}

// Extension method
fn buffered(self, n: usize) -> Buffered<Self>
where
    Self: Sized,
    Self::Item: Future,
{
    Buffered::new(self, n)
}

// Unordered variant
fn buffer_unordered(self, n: usize) -> BufferUnordered<Self>
where
    Self: Sized,
    Self::Item: Future,
{
    BufferUnordered::new(self, n)
}
```

### Step 5: Chunks Combinator
```rust
/// Collect stream into chunks
#[pin_project]
pub struct Chunks<S: Stream> {
    #[pin]
    stream: S,
    items: Vec<S::Item>,
    cap: usize,
}

impl<S: Stream> Stream for Chunks<S> {
    type Item = Vec<S::Item>;

    fn poll_next(self: Pin<&mut Self>, cx: &mut Context<'_>) -> Poll<Option<Self::Item>> {
        let mut this = self.project();

        loop {
            match this.stream.as_mut().poll_next(cx) {
                Poll::Ready(Some(item)) => {
                    this.items.push(item);
                    if this.items.len() >= *this.cap {
                        return Poll::Ready(Some(std::mem::take(this.items)));
                    }
                }
                Poll::Ready(None) => {
                    if this.items.is_empty() {
                        return Poll::Ready(None);
                    } else {
                        return Poll::Ready(Some(std::mem::take(this.items)));
                    }
                }
                Poll::Pending => {
                    return Poll::Pending;
                }
            }
        }
    }
}

// Extension method
fn chunks(self, capacity: usize) -> Chunks<Self>
where
    Self: Sized,
{
    assert!(capacity > 0);
    Chunks {
        stream: self,
        items: Vec::with_capacity(capacity),
        cap: capacity,
    }
}

/// Ready chunks - return immediately available items
#[pin_project]
pub struct ReadyChunks<S: Stream> {
    #[pin]
    stream: S,
    cap: usize,
}

impl<S: Stream> Stream for ReadyChunks<S> {
    type Item = Vec<S::Item>;

    fn poll_next(self: Pin<&mut Self>, cx: &mut Context<'_>) -> Poll<Option<Self::Item>> {
        let mut this = self.project();
        let mut items = Vec::with_capacity(*this.cap);

        loop {
            match this.stream.as_mut().poll_next(cx) {
                Poll::Ready(Some(item)) => {
                    items.push(item);
                    if items.len() >= *this.cap {
                        return Poll::Ready(Some(items));
                    }
                }
                Poll::Ready(None) => {
                    if items.is_empty() {
                        return Poll::Ready(None);
                    } else {
                        return Poll::Ready(Some(items));
                    }
                }
                Poll::Pending => {
                    if items.is_empty() {
                        return Poll::Pending;
                    } else {
                        return Poll::Ready(Some(items));
                    }
                }
            }
        }
    }
}
```

