## Overview

Implement the `Chain` and `Take` buffer adapters for composing and limiting buffer operations.

## Rationale

These adapters enable:
- Composing multiple buffers without copying
- Limiting reads to a specific number of bytes
- Building complex buffer pipelines
- Zero-copy protocol parsing

Used extensively in:
- HTTP chunked transfer encoding
- Length-prefixed protocols
- Scatter/gather I/O

## Implementation

### Chain Adapter

```rust
// bytes/src/buf/chain.rs

use super::Buf;

/// Chain two `Buf` implementations together.
///
/// When the first buffer is exhausted, reading continues from the second.
pub struct Chain<T, U> {
    a: T,
    b: U,
}

impl<T, U> Chain<T, U> {
    /// Create a new Chain.
    pub(crate) fn new(a: T, b: U) -> Self {
        Chain { a, b }
    }

    /// Get a reference to the first buffer.
    pub fn first_ref(&self) -> &T {
        &self.a
    }

    /// Get a mutable reference to the first buffer.
    pub fn first_mut(&mut self) -> &mut T {
        &mut self.a
    }

    /// Get a reference to the second buffer.
    pub fn last_ref(&self) -> &U {
        &self.b
    }

    /// Get a mutable reference to the second buffer.
    pub fn last_mut(&mut self) -> &mut U {
        &mut self.b
    }

    /// Destructure into the two underlying buffers.
    pub fn into_inner(self) -> (T, U) {
        (self.a, self.b)
    }
}

impl<T: Buf, U: Buf> Buf for Chain<T, U> {
    fn remaining(&self) -> usize {
        self.a.remaining().saturating_add(self.b.remaining())
    }

    fn chunk(&self) -> &[u8] {
        if self.a.has_remaining() {
            self.a.chunk()
        } else {
            self.b.chunk()
        }
    }

    fn advance(&mut self, mut cnt: usize) {
        // Advance through first buffer
        let a_rem = self.a.remaining();
        if cnt <= a_rem {
            self.a.advance(cnt);
            return;
        }

        // Exhaust first buffer
        if a_rem > 0 {
            self.a.advance(a_rem);
            cnt -= a_rem;
        }

        // Continue into second buffer
        self.b.advance(cnt);
    }

    fn copy_to_slice(&mut self, mut dst: &mut [u8]) {
        while !dst.is_empty() && self.has_remaining() {
            let chunk = self.chunk();
            let cnt = std::cmp::min(chunk.len(), dst.len());
            dst[..cnt].copy_from_slice(&chunk[..cnt]);
            self.advance(cnt);
            dst = &mut dst[cnt..];
        }
    }
}

// Allow chaining more buffers
impl<T: Buf, U: Buf> Chain<T, U> {
    /// Chain another buffer onto this chain.
    pub fn chain<V: Buf>(self, next: V) -> Chain<Self, V> {
        Chain::new(self, next)
    }
}
```

### Take Adapter

```rust
// bytes/src/buf/take.rs

use super::Buf;

/// Limit the number of bytes that can be read from a `Buf`.
pub struct Take<T> {
    inner: T,
    limit: usize,
}

impl<T> Take<T> {
    /// Create a new Take.
    pub(crate) fn new(inner: T, limit: usize) -> Self {
        Take { inner, limit }
    }

    /// Get a reference to the underlying buffer.
    pub fn get_ref(&self) -> &T {
        &self.inner
    }

    /// Get a mutable reference to the underlying buffer.
    pub fn get_mut(&mut self) -> &mut T {
        &mut self.inner
    }

    /// Destructure into the underlying buffer.
    pub fn into_inner(self) -> T {
        self.inner
    }

    /// Returns the current limit.
    pub fn limit(&self) -> usize {
        self.limit
    }

    /// Set the limit.
    pub fn set_limit(&mut self, limit: usize) {
        self.limit = limit;
    }
}

impl<T: Buf> Buf for Take<T> {
    fn remaining(&self) -> usize {
        std::cmp::min(self.inner.remaining(), self.limit)
    }

    fn chunk(&self) -> &[u8] {
        let chunk = self.inner.chunk();
        let limit = std::cmp::min(chunk.len(), self.limit);
        &chunk[..limit]
    }

    fn advance(&mut self, cnt: usize) {
        assert!(cnt <= self.limit, "cannot advance past limit");
        self.inner.advance(cnt);
        self.limit -= cnt;
    }
}
