### UnixStream Extension

```rust
impl UnixStream {
    /// Get the credentials of the connected peer.
    ///
    /// # Platform Differences
    /// - Linux: Uses SO_PEERCRED socket option
    /// - macOS: Uses LOCAL_PEERCRED or getpeereid()
    /// - FreeBSD: Uses LOCAL_PEERCRED
    ///
    /// # Example
    /// ```rust
    /// let (server, client) = UnixStream::pair()?;
    /// let cred = server.peer_cred()?;
    /// println\!("Connected by UID {}", cred.uid);
    /// ```
    pub fn peer_cred(&self) -> io::Result<UCred> {
        #[cfg(target_os = "linux")]
        {
            use libc::{c_void, getsockopt, socklen_t, ucred, SOL_SOCKET, SO_PEERCRED};
            use std::mem;

            let mut ucred: ucred = unsafe { mem::zeroed() };
            let mut len = mem::size_of::<ucred>() as socklen_t;

            let ret = unsafe {
                getsockopt(
                    self.inner.as_raw_fd(),
                    SOL_SOCKET,
                    SO_PEERCRED,
                    &mut ucred as *mut _ as *mut c_void,
                    &mut len,
                )
            };

            if ret \!= 0 {
                return Err(io::Error::last_os_error());
            }

            Ok(UCred {
                pid: Some(ucred.pid as u32),
                uid: ucred.uid,
                gid: ucred.gid,
            })
        }

        #[cfg(target_os = "macos")]
        {
            use libc::{c_void, getsockopt, socklen_t, xucred, LOCAL_PEERCRED, SOL_LOCAL};
            use std::mem;

            let mut xucred: xucred = unsafe { mem::zeroed() };
            let mut len = mem::size_of::<xucred>() as socklen_t;

            let ret = unsafe {
                getsockopt(
                    self.inner.as_raw_fd(),
                    SOL_LOCAL,
                    LOCAL_PEERCRED,
                    &mut xucred as *mut _ as *mut c_void,
                    &mut len,
                )
            };

            if ret \!= 0 {
                return Err(io::Error::last_os_error());
            }

            Ok(UCred {
                pid: None, // macOS LOCAL_PEERCRED doesn't include PID
                uid: xucred.cr_uid,
                gid: xucred.cr_gid,
            })
        }
    }
}
```

