# Decoder and Encoder Traits

## Overview
Core codec traits for bidirectional message framing.

## Implementation

### Decoder Trait
```rust
use crate::bytes::BytesMut;

/// Decode bytes into frames
pub trait Decoder {
    /// Type of decoded frames
    type Item;
    /// Decoding error type  
    type Error: From<io::Error>;

    /// Attempt to decode a frame from the buffer
    /// 
    /// Returns:
    /// - Ok(Some(item)) - complete frame decoded
    /// - Ok(None) - need more data
    /// - Err(e) - decoding error
    fn decode(&mut self, src: &mut BytesMut) -> Result<Option<Self::Item>, Self::Error>;

    /// Called when EOF is reached
    fn decode_eof(&mut self, src: &mut BytesMut) -> Result<Option<Self::Item>, Self::Error> {
        match self.decode(src)? {
            Some(frame) => Ok(Some(frame)),
            None if src.is_empty() => Ok(None),
            None => Err(io::Error::new(
                io::ErrorKind::UnexpectedEof,
                "incomplete frame at EOF"
            ).into()),
        }
    }
}

/// Encoder trait
pub trait Encoder<Item> {
    /// Encoding error type
    type Error: From<io::Error>;

    /// Encode an item into the buffer
    fn encode(&mut self, item: Item, dst: &mut BytesMut) -> Result<(), Self::Error>;
}
```

### LinesCodec
```rust
/// Codec for newline-delimited text
pub struct LinesCodec {
    max_length: usize,
    next_index: usize,
}

impl LinesCodec {
    pub fn new() -> Self {
        Self::new_with_max_length(usize::MAX)
    }

    pub fn new_with_max_length(max_length: usize) -> Self {
        Self { max_length, next_index: 0 }
    }

    pub fn max_length(&self) -> usize {
        self.max_length
    }
}

impl Decoder for LinesCodec {
    type Item = String;
    type Error = LinesCodecError;

    fn decode(&mut self, src: &mut BytesMut) -> Result<Option<String>, Self::Error> {
        // Search for newline starting from last position
        let read_to = std::cmp::min(self.max_length.saturating_add(1), src.len());

        let newline_offset = src[self.next_index..read_to]
            .iter()
            .position(|b| *b == b'\n');

        match newline_offset {
            Some(offset) => {
                let newline_index = self.next_index + offset;
                self.next_index = 0;

                // Extract line (without newline)
                let mut line = src.split_to(newline_index + 1);
                line.truncate(line.len() - 1);

                // Handle \r\n
                if line.last() == Some(&b'\r') {
                    line.truncate(line.len() - 1);
                }

                let s = String::from_utf8(line.to_vec())
                    .map_err(|_| LinesCodecError::InvalidUtf8)?;
                Ok(Some(s))
            }
            None => {
                if src.len() > self.max_length {
                    return Err(LinesCodecError::MaxLineLengthExceeded);
                }
                self.next_index = read_to;
                Ok(None)
            }
        }
    }
}

impl Encoder<String> for LinesCodec {
    type Error = io::Error;

    fn encode(&mut self, line: String, dst: &mut BytesMut) -> Result<(), io::Error> {
        dst.reserve(line.len() + 1);
        dst.put_slice(line.as_bytes());
        dst.put_u8(b'\n');
        Ok(())
    }
}
```

