## Mock Sink Implementation

```rust
/// Mock symbol sink for testing send operations.
pub struct MockSymbolSink {
    config: MockTransportConfig,
    inner: Arc<Mutex<MockSinkInner>>,
}

struct MockSinkInner {
    sent_symbols: Vec<AuthenticatedSymbol>,
    rng: DetRng,
    operation_count: usize,
    closed: bool,
}

impl MockSymbolSink {
    /// Create a new mock sink with given configuration.
    pub fn new(config: MockTransportConfig) -> Self { /* ... */ }

    /// Get all symbols that were successfully "sent" (for verification).
    pub async fn sent_symbols(&self) -> Vec<AuthenticatedSymbol> { /* ... */ }

    /// Get count of sent symbols.
    pub async fn sent_count(&self) -> usize { /* ... */ }

    /// Clear the sent symbols buffer.
    pub async fn clear(&self) { /* ... */ }

    /// Reset operation counter (for fail_after behavior).
    pub async fn reset_counter(&self) { /* ... */ }
}

impl SymbolSink for MockSymbolSink {
    type Error = TransportError;

    async fn reserve(&self) -> Result<SendPermit<'_>, Self::Error> {
        let inner = self.inner.lock().await;

        // Check fail_after
        if let Some(limit) = self.config.fail_after {
            if inner.operation_count >= limit {
                return Err(TransportError::injected("fail_after limit reached"));
            }
        }

        // Simulate backpressure
        if inner.sent_symbols.len() >= self.config.capacity {
            return Err(TransportError::backpressure());
        }

        // Apply latency
        if self.config.base_latency > Duration::ZERO {
            let jitter = inner.rng.gen_range(Duration::ZERO..self.config.latency_jitter);
            tokio::time::sleep(self.config.base_latency + jitter).await;
        }

        Ok(SendPermit::new(self))
    }

    async fn send(&self, permit: SendPermit<'_>, symbol: AuthenticatedSymbol) -> Result<(), Self::Error> {
        let mut inner = self.inner.lock().await;
        inner.operation_count += 1;

        // Simulate loss
        if inner.rng.gen::<f64>() < self.config.loss_rate {
            tracing::debug!(symbol_id = %symbol.id(), "Mock: symbol lost");
            return Ok(()); // Silent loss
        }

        // Simulate corruption
        if inner.rng.gen::<f64>() < self.config.corruption_rate {
            tracing::debug!(symbol_id = %symbol.id(), "Mock: symbol corrupted");
            let corrupted = corrupt_symbol(symbol);
            inner.sent_symbols.push(corrupted);
            return Ok(());
        }

        // Simulate duplication
        if inner.rng.gen::<f64>() < self.config.duplication_rate {
            tracing::debug!(symbol_id = %symbol.id(), "Mock: symbol duplicated");
            inner.sent_symbols.push(symbol.clone());
        }

        inner.sent_symbols.push(symbol);
        Ok(())
    }

    async fn flush(&self) -> Result<(), Self::Error> {
        Ok(()) // Mock flush is a no-op
    }

    async fn close(&self) -> Result<(), Self::Error> {
        let mut inner = self.inner.lock().await;
        inner.closed = true;
        Ok(())
    }
}
