#[cfg(test)]
mod cancel_reason_tests {
    use super::*;

    #[test]
    fn basic_construction() {
        init_cancel_test_logging();

        let reason = CancelReason::new(CancelKind::User, RegionId(1));

        assert_eq!(reason.kind, CancelKind::User);
        assert_eq!(reason.origin_region, RegionId(1));
        assert!(reason.cause.is_none());

        tracing::info!(kind = ?reason.kind, "Basic reason constructed");
    }

    #[test]
    fn with_message() {
        init_cancel_test_logging();

        let reason = CancelReason::new(CancelKind::User, RegionId(1))
            .with_message("User pressed Ctrl+C");

        assert_eq!(reason.message, Some("User pressed Ctrl+C".to_string()));

        tracing::info!(message = ?reason.message, "Reason with message");
    }

    #[test]
    fn with_task() {
        init_cancel_test_logging();

        let reason = CancelReason::new(CancelKind::Deadline, RegionId(1))
            .with_task(TaskId(42));

        assert_eq!(reason.origin_task, Some(TaskId(42)));

        tracing::info!(task = ?reason.origin_task, "Reason with task");
    }

    #[test]
    fn cause_chain_construction() {
        init_cancel_test_logging();

        let root = CancelReason::new(CancelKind::Deadline, RegionId(1));
        let middle = CancelReason::new(CancelKind::ParentCancelled, RegionId(2))
            .caused_by(root);
        let leaf = CancelReason::new(CancelKind::ParentCancelled, RegionId(3))
            .caused_by(middle);

        // Chain should have 3 elements
        let chain: Vec<_> = leaf.chain().collect();
        assert_eq!(chain.len(), 3);

        // Order: leaf -> middle -> root
        assert_eq!(chain[0].kind, CancelKind::ParentCancelled);
        assert_eq!(chain[0].origin_region, RegionId(3));
        assert_eq!(chain[1].kind, CancelKind::ParentCancelled);
        assert_eq!(chain[1].origin_region, RegionId(2));
        assert_eq!(chain[2].kind, CancelKind::Deadline);
        assert_eq!(chain[2].origin_region, RegionId(1));

        log_cancel_chain(&leaf);
    }

    #[test]
    fn root_cause() {
        init_cancel_test_logging();

        let root = CancelReason::new(CancelKind::Deadline, RegionId(1))
            .with_message("5 second timeout");
        let leaf = CancelReason::new(CancelKind::ParentCancelled, RegionId(5))
            .caused_by(CancelReason::new(CancelKind::ParentCancelled, RegionId(4))
                .caused_by(CancelReason::new(CancelKind::ParentCancelled, RegionId(3))
                    .caused_by(CancelReason::new(CancelKind::ParentCancelled, RegionId(2))
                        .caused_by(root.clone()))));

        let found_root = leaf.root_cause();
        assert_eq!(found_root.kind, CancelKind::Deadline);
        assert_eq!(found_root.message, Some("5 second timeout".to_string()));

        tracing::info!(
            root_kind = ?found_root.kind,
            root_region = ?found_root.origin_region,
            "Found root cause through 5-level chain"
        );
    }

    #[test]
    fn any_cause_is() {
        init_cancel_test_logging();

        let reason = CancelReason::new(CancelKind::ParentCancelled, RegionId(3))
            .caused_by(CancelReason::new(CancelKind::ParentCancelled, RegionId(2))
                .caused_by(CancelReason::new(CancelKind::PollQuota, RegionId(1))));

        // Immediate cause is ParentCancelled
        assert!(reason.is_kind(CancelKind::ParentCancelled));
        assert!(!reason.is_kind(CancelKind::PollQuota));

        // But PollQuota is in the chain
        assert!(reason.any_cause_is(CancelKind::PollQuota));
        assert!(!reason.any_cause_is(CancelKind::Deadline));

        tracing::info!("any_cause_is() correctly traverses chain");
    }
}
