#[test]
fn e2e_debugging_workflow() {
    init_cancel_test_logging();

    tracing::info!("═══════════════════════════════════════════");
    tracing::info!("E2E: Cancel Attribution Debugging Workflow");
    tracing::info!("═══════════════════════════════════════════");

    let lab = LabRuntimeBuilder::new()
        .rng_seed(42)
        .build();

    // Simulate a service with nested timeouts
    lab.run_with_cx(|cx| async move {
        // Service-level timeout: 5 seconds
        let result = cx.with_budget(
            Budget::deadline(Duration::from_secs(5)),
            async {
                // Handler timeout: 1 second
                cx.with_budget(
                    Budget::deadline(Duration::from_secs(1)),
                    async {
                        // Database timeout: 100ms
                        cx.with_budget(
                            Budget::deadline(Duration::from_millis(100)),
                            async {
                                // Slow query that takes too long
                                sleep(Duration::from_millis(200)).await;
                                42
                            }
                        ).await
                    }
                ).await
            }
        ).await;

        // Debugging: What happened?
        if let Outcome::Cancelled(_) = &result {
            tracing::info!("Request was cancelled - investigating...");

            if let Some(reason) = cx.cancel_reason() {
                // Print the full chain
                tracing::info!("Cancel attribution chain:");
                for (depth, cause) in reason.chain().enumerate() {
                    let indent = "  ".repeat(depth);
                    tracing::info!(
                        "{}{:?} at region {:?} ({:?})",
                        indent,
                        cause.kind,
                        cause.origin_region,
                        cause.message.as_deref().unwrap_or("no message")
                    );
                }

                // Actionable insight
                let root = reason.root_cause();
                if root.kind == CancelKind::Deadline {
                    tracing::warn!(
                        "Root cause: Deadline at region {:?}",
                        root.origin_region
                    );
                    tracing::warn!("Consider: Increase timeout or optimize query");
                }
            }
        }
    });

    tracing::info!("E2E debugging workflow completed");
}

