fn e2e_metrics_collection() {
    init_cancel_test_logging();

    tracing::info!("═══════════════════════════════════════════");
    tracing::info!("E2E: Cancel Attribution Metrics Collection");
    tracing::info!("═══════════════════════════════════════════");

    // Simulate collecting metrics from cancellation reasons
    struct CancelMetrics {
        by_kind: HashMap<CancelKind, usize>,
        total_chain_depth: usize,
        count: usize,
    }

    let metrics = Arc::new(Mutex::new(CancelMetrics {
        by_kind: HashMap::new(),
        total_chain_depth: 0,
        count: 0,
    }));

    let lab = LabRuntimeBuilder::new().rng_seed(42).build();

    // Run several requests with various cancellation scenarios
    for i in 0..10 {
        let metrics = metrics.clone();

        lab.run_with_cx(|cx| async move {
            let budget = match i % 3 {
                0 => Budget::deadline(Duration::from_millis(10)),
                1 => Budget::poll_quota(5),
                _ => Budget::cost(100),
            };

            let result = cx.with_budget(budget, async {
                // Simulate work that might exceed budget
                for _ in 0..20 {
                    yield_now().await;
                }
            }).await;

            if let Outcome::Cancelled(_) = result {
                if let Some(reason) = cx.cancel_reason() {
                    let mut m = metrics.lock().unwrap();

                    // Count by kind
                    *m.by_kind.entry(reason.kind).or_insert(0) += 1;

                    // Track chain depth
                    let depth = reason.chain().count();
                    m.total_chain_depth += depth;
                    m.count += 1;
                }
            }
        });
    }

    let m = metrics.lock().unwrap();
    tracing::info!("Cancellation metrics collected:");
    for (kind, count) in &m.by_kind {
        tracing::info!("  {:?}: {}", kind, count);
    }
    if m.count > 0 {
        tracing::info!(
            "  Average chain depth: {:.1}",
            m.total_chain_depth as f64 / m.count as f64
        );
    }
