# Service and Layer Traits

## Overview
Core service abstraction for composable middleware.

## Implementation

### Service Trait
```rust
pub trait Service<Request> {
    type Response;
    type Error;
    type Future: Future<Output = Result<Self::Response, Self::Error>>;

    fn poll_ready(&mut self, cx: &mut Context<'_>) -> Poll<Result<(), Self::Error>>;
    fn call(&mut self, req: Request) -> Self::Future;
}

// Convenience extensions
pub trait ServiceExt<Request>: Service<Request> {
    fn ready(&mut self) -> Ready<'_, Self, Request> { Ready { service: self } }
    fn oneshot(self, req: Request) -> Oneshot<Self, Request> where Self: Sized {
        Oneshot::new(self, req)
    }
}
impl<T: Service<R> + ?Sized, R> ServiceExt<R> for T {}
```

### Layer Trait
```rust
pub trait Layer<S> {
    type Service;
    fn layer(&self, inner: S) -> Self::Service;
}

// Identity layer
pub struct Identity;
impl<S> Layer<S> for Identity {
    type Service = S;
    fn layer(&self, inner: S) -> S { inner }
}

// Stack of layers
pub struct Stack<Inner, Outer> {
    inner: Inner,
    outer: Outer,
}
impl<S, Inner, Outer> Layer<S> for Stack<Inner, Outer>
where
    Inner: Layer<S>,
    Outer: Layer<Inner::Service>,
{
    type Service = Outer::Service;
    fn layer(&self, service: S) -> Self::Service {
        self.outer.layer(self.inner.layer(service))
    }
}
