#[tokio::test]
async fn test_basic_object_transfer() {
    setup_logging();
    tracing::info!("=== E2E: Basic Object Transfer ===");

    // Setup
    let (sender_ctx, receiver_ctx) = create_test_contexts();
    let (tx_sink, rx_stream) = create_channel_transport();

    // Create test data
    let original_data = generate_random_data(100_000);
    let object_id = ObjectId::new_random();

    tracing::info!(
        object_id = %object_id,
        data_size = original_data.len(),
        "Starting transfer"
    );

    // Encode and send
    let encode_start = Instant::now();
    let mut encoder = EncodingPipeline::new(config, pool);
    let mut sent_count = 0;

    for symbol in encoder.encode(object_id, &original_data) {
        let auth_symbol = sender_ctx.sign_symbol(&symbol?);
        tx_sink.send(auth_symbol).await?;
        sent_count += 1;
    }
    tx_sink.close().await?;

    tracing::info!(
        sent_count,
        encode_time_ms = encode_start.elapsed().as_millis(),
        "Encoding and sending complete"
    );

    // Receive and decode
    let decode_start = Instant::now();
    let mut decoder = DecodingPipeline::with_auth(config, receiver_ctx);
    let mut received_count = 0;

    while let Some(symbol) = rx_stream.next().await {
        match decoder.feed(symbol?)? {
            SymbolAcceptResult::BlockComplete { .. } => {
                tracing::debug!("Block decoded");
            }
            _ => {}
        }
        received_count += 1;

        if decoder.is_complete() {
            break;
        }
    }

    let decoded_data = decoder.into_data()?;

    tracing::info!(
        received_count,
        decode_time_ms = decode_start.elapsed().as_millis(),
        "Decoding complete"
    );

    // Verify
    assert_eq!(original_data, decoded_data, "Data mismatch");
    tracing::info!("=== PASSED: Basic Object Transfer ===");
}
```

