### 2. Core API
```rust
impl<T, E> Outcome<T, E> {
    // Construction
    pub fn ok(value: T) -> Self;
    pub fn err(error: E) -> Self;
    pub fn cancelled(reason: CancelReason) -> Self;
    pub fn panicked(payload: PanicPayload) -> Self;

    // Inspection
    pub fn is_ok(&self) -> bool;
    pub fn is_err(&self) -> bool;
    pub fn is_cancelled(&self) -> bool;
    pub fn is_panicked(&self) -> bool;
    pub fn severity(&self) -> Severity;

    // Transformation
    pub fn map<U>(self, f: impl FnOnce(T) -> U) -> Outcome<U, E>;
    pub fn map_err<F>(self, f: impl FnOnce(E) -> F) -> Outcome<T, F>;
    pub fn and_then<U>(self, f: impl FnOnce(T) -> Outcome<U, E>) -> Outcome<U, E>;

    // Conversion
    pub fn into_result(self) -> Result<T, OutcomeError<E>>;
    pub fn ok_or_else<F>(self, f: impl FnOnce() -> F) -> Result<T, F>;

    // Aggregation (for join semantics)
    pub fn join(self, other: Outcome<T, E>) -> Outcome<T, E>
    where T: Default;  // Or use Join trait
}
```

### 3. HTTP Mapping Guidelines
Document recommended mapping to HTTP status codes:
```rust
impl<T, E: HttpError> Outcome<T, E> {
    pub fn to_http_status(&self) -> StatusCode {
        match self {
            Outcome::Ok(_) => StatusCode::OK,  // Or custom
            Outcome::Err(e) => e.status_code(),
            Outcome::Cancelled(_) => StatusCode::from_u16(499).unwrap(),
            Outcome::Panicked(_) => StatusCode::INTERNAL_SERVER_ERROR,
