            Poll::Ready(r) => { self.overloaded = false; Poll::Ready(r.map_err(Into::into)) }
            Poll::Pending => { self.overloaded = true; Poll::Ready(Ok(())) }
        }
    }

    fn call(&mut self, req: Req) -> Self::Future {
        if self.overloaded {
            return LoadShedFuture::overloaded();
        }
        LoadShedFuture::inner(self.inner.call(req))
    }
}
