/// Circuit breaker state
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum State {
    /// Normal operation, tracking failures
    Closed,

    /// Rejecting all calls, waiting for open_duration
    Open { since_millis: u64 },

    /// Testing recovery with limited probes
    HalfOpen { probes_active: u32, successes: u32 },
}

impl State {
    /// Pack state into u64 for atomic operations.
    /// Format: [state_type:8][data:56]
    fn to_bits(self) -> u64 {
        match self {
            State::Closed => 0,
            State::Open { since_millis } => 1 | (since_millis << 8),
            State::HalfOpen { probes_active, successes } => {
                2 | ((probes_active as u64) << 8) | ((successes as u64) << 32)
            }
        }
    }

    /// Unpack state from u64.
    fn from_bits(bits: u64) -> Self {
        let state_type = bits & 0xFF;
        match state_type {
            0 => State::Closed,
            1 => State::Open { since_millis: bits >> 8 },
            2 => State::HalfOpen {
                probes_active: ((bits >> 8) & 0xFFFFFF) as u32,
                successes: (bits >> 32) as u32,
            },
            _ => State::Closed, // Fallback
        }
    }
}

