/// Thread-safe circuit breaker
pub struct CircuitBreaker {
    policy: CircuitBreakerPolicy,

    // Atomic state representation
    state_bits: AtomicU64,
    failure_count: AtomicU32,
    success_count: AtomicU32,
    probes_active: AtomicU32,

    // Metrics (needs lock for complex updates)
    metrics: RwLock<CircuitBreakerMetrics>,

    // Sliding window (if enabled)
    sliding_window: Option<Mutex<SlidingWindow>>,
}

impl CircuitBreaker {
    pub fn new(policy: CircuitBreakerPolicy) -> Self {
        let sliding_window = policy.sliding_window.as_ref()
            .map(|config| Mutex::new(SlidingWindow::new(config.clone())));

        Self {
            policy,
            state_bits: AtomicU64::new(State::Closed.to_bits()),
            failure_count: AtomicU32::new(0),
            success_count: AtomicU32::new(0),
            probes_active: AtomicU32::new(0),
            metrics: RwLock::new(CircuitBreakerMetrics::default()),
            sliding_window,
        }
    }

    /// Get current state
    pub fn state(&self) -> State {
        State::from_bits(self.state_bits.load(Ordering::SeqCst))
    }

    /// Get current metrics
    pub fn metrics(&self) -> CircuitBreakerMetrics {
        self.metrics.read().clone()
    }

    /// Check if call should be allowed
    fn should_allow(&self, now: Time) -> Result<Permit, CircuitBreakerError> {
        let now_millis = now.as_millis() as u64;

        loop {
            let current_bits = self.state_bits.load(Ordering::SeqCst);
            let state = State::from_bits(current_bits);

            match state {
                State::Closed => {
                    return Ok(Permit::Normal);
                }

                State::Open { since_millis } => {
                    let elapsed = Duration::from_millis(now_millis.saturating_sub(since_millis));
                    if elapsed >= self.policy.open_duration {
                        // Transition to half-open
                        let new_state = State::HalfOpen { probes_active: 1, successes: 0 };
                        if self.state_bits.compare_exchange(
                            current_bits,
                            new_state.to_bits(),
                            Ordering::SeqCst,
                            Ordering::SeqCst,
                        ).is_ok() {
                            self.probes_active.store(1, Ordering::SeqCst);
                            self.success_count.store(0, Ordering::SeqCst);

                            tracing::info!(
                                circuit = %self.policy.name,
                                "circuit_breaker: transitioning to half-open"
                            );

                            return Ok(Permit::Probe);
                        }
                        // CAS failed, retry
                        continue;
                    } else {
                        let remaining = self.policy.open_duration - elapsed;
                        // Track rejection
                        self.metrics.write().total_rejected += 1;
                        return Err(CircuitBreakerError::Open { remaining });
                    }
                }

                State::HalfOpen { probes_active, .. } => {
                    if probes_active < self.policy.half_open_max_probes {
                        // Try to acquire probe slot
                        let current_probes = self.probes_active.load(Ordering::SeqCst);
                        if current_probes < self.policy.half_open_max_probes {
                            if self.probes_active.compare_exchange(
                                current_probes,
                                current_probes + 1,
                                Ordering::SeqCst,
                                Ordering::SeqCst,
                            ).is_ok() {
                                return Ok(Permit::Probe);
                            }
                        }
                        // CAS failed, retry
                        continue;
                    } else {
                        // Max probes active, reject
                        self.metrics.write().total_rejected += 1;
                        return Err(CircuitBreakerError::HalfOpenFull);
                    }
                }
            }
        }
    }

    /// Record a successful call
    fn record_success(&self, permit: Permit, now: Time) {
        let now_millis = now.as_millis() as u64;

        tracing::trace!(
            circuit = %self.policy.name,
            permit = ?permit,
            "circuit_breaker: success"
        );

        let mut metrics = self.metrics.write();
        metrics.total_success += 1;

        match permit {
            Permit::Normal => {
                self.failure_count.store(0, Ordering::SeqCst);
                metrics.current_failure_streak = 0;
            }
            Permit::Probe => {
                self.probes_active.fetch_sub(1, Ordering::SeqCst);
                let successes = self.success_count.fetch_add(1, Ordering::SeqCst) + 1;

                if successes >= self.policy.success_threshold {
                    self.transition_to_closed(now_millis, &mut metrics);
                }
            }
        }

        if let Some(ref window) = self.sliding_window {
            window.lock().record_success(now_millis);
        }
    }

    /// Record a failed call
    fn record_failure(&self, permit: Permit, error: &Error, now: Time) {
        let now_millis = now.as_millis() as u64;

        // Check if this error counts as a failure
        let counts_as_failure = match &self.policy.failure_predicate {
            FailurePredicate::AllErrors => true,
            FailurePredicate::ByType(pred) => pred(error),
            FailurePredicate::Custom(pred) => pred(error),
        };

        let mut metrics = self.metrics.write();

        if !counts_as_failure {
            tracing::trace!(
                circuit = %self.policy.name,
                error = ?error,
                "circuit_breaker: error ignored (not counted as failure)"
            );
            metrics.total_ignored_errors += 1;

            // Still need to release probe if applicable
            if matches!(permit, Permit::Probe) {
                self.probes_active.fetch_sub(1, Ordering::SeqCst);
            }
            return;
        }

        tracing::debug!(
            circuit = %self.policy.name,
            permit = ?permit,
            error = ?error,
            "circuit_breaker: failure recorded"
        );

        metrics.total_failure += 1;

        match permit {
            Permit::Normal => {
                let failures = self.failure_count.fetch_add(1, Ordering::SeqCst) + 1;
                metrics.current_failure_streak = failures;

                // Check sliding window if enabled
                let window_triggered = if let Some(ref window) = self.sliding_window {
                    let mut w = window.lock();
                    w.record_failure(now_millis);
                    metrics.sliding_window_failure_rate = Some(w.failure_rate());
                    w.should_open()
                } else {
                    false
                };

                if failures >= self.policy.failure_threshold || window_triggered {
                    self.transition_to_open(now_millis, &mut metrics);
                }
            }
            Permit::Probe => {
                self.probes_active.fetch_sub(1, Ordering::SeqCst);
                // Probe failed, go back to open
                self.transition_to_open(now_millis, &mut metrics);
            }
        }
    }

    fn transition_to_open(&self, now_millis: u64, metrics: &mut CircuitBreakerMetrics) {
        let old_state = self.state();
        let new_state = State::Open { since_millis: now_millis };

        self.state_bits.store(new_state.to_bits(), Ordering::SeqCst);
        self.failure_count.store(0, Ordering::SeqCst);
        self.success_count.store(0, Ordering::SeqCst);
        self.probes_active.store(0, Ordering::SeqCst);

        // Reset sliding window
        if let Some(ref window) = self.sliding_window {
            window.lock().reset();
        }

        metrics.times_opened += 1;
        metrics.current_state = new_state;

        tracing::warn!(
            circuit = %self.policy.name,
            from = ?old_state,
            to = ?new_state,
            "circuit_breaker: OPENED"
        );

        if let Some(ref callback) = self.policy.on_state_change {
            callback(old_state, new_state, metrics);
        }
    }

    fn transition_to_closed(&self, _now_millis: u64, metrics: &mut CircuitBreakerMetrics) {
        let old_state = self.state();
        let new_state = State::Closed;

        self.state_bits.store(new_state.to_bits(), Ordering::SeqCst);
        self.failure_count.store(0, Ordering::SeqCst);
        self.success_count.store(0, Ordering::SeqCst);
        self.probes_active.store(0, Ordering::SeqCst);

        metrics.times_closed += 1;
        metrics.current_state = new_state;
        metrics.current_failure_streak = 0;

        tracing::info!(
            circuit = %self.policy.name,
            from = ?old_state,
            to = ?new_state,
            "circuit_breaker: CLOSED (recovered)"
        );

        if let Some(ref callback) = self.policy.on_state_change {
            callback(old_state, new_state, metrics);
        }
    }
}

