//! E2E tests for circuit breaker combinator.

use asupersync::combinator::circuit_breaker::*;
use asupersync::lab::{LabRuntime, LabConfig};
use std::time::Duration;
use std::sync::atomic::{AtomicUsize, Ordering};
use std::sync::Arc;

#[test]
fn e2e_circuit_breaker_basic_flow() {
    let mut rt = LabRuntime::new();

    let policy = CircuitBreakerPolicy {
        name: "test-service".into(),
        failure_threshold: 3,
        success_threshold: 2,
        open_duration: Duration::from_secs(5),
        ..Default::default()
    };

    let breaker = Arc::new(CircuitBreaker::new(policy));

    rt.block_on(async {
        let cx = rt.root_cx();

        // Simulate 3 failures to open circuit
        for i in 0..3 {
            let result: Result<(), CircuitBreakerError<String>> = 
                with_circuit_breaker(&cx, &breaker, async {
                    Err::<(), _>(format!("failure {}", i))
                }).await;

            assert!(matches!(result, Err(CircuitBreakerError::Inner(_))));
        }

        // Circuit should be open
        assert!(matches!(breaker.state(), State::Open { .. }));

        // Next call should be rejected
        let result: Result<(), CircuitBreakerError<String>> = 
            with_circuit_breaker(&cx, &breaker, async {
                Ok(())
            }).await;

        assert!(matches!(result, Err(CircuitBreakerError::Open { .. })));

        // Wait for open_duration
        cx.sleep(Duration::from_secs(6)).await;

        // Should transition to half-open and allow probe
        let result: Result<i32, CircuitBreakerError<String>> = 
            with_circuit_breaker(&cx, &breaker, async {
                Ok(42)
            }).await;

        assert!(result.is_ok());

        // One more success to close
        let result: Result<i32, CircuitBreakerError<String>> = 
            with_circuit_breaker(&cx, &breaker, async {
                Ok(42)
            }).await;

        assert!(result.is_ok());
        assert_eq!(breaker.state(), State::Closed);
    });
}

