```rust
// In src/cx/cx.rs

impl Cx {
    /// Get the entropy source for this context.
    /// 
    /// In production mode, returns OS entropy.
    /// In lab mode, returns deterministic seeded entropy.
    pub fn entropy(&self) -> &dyn EntropySource {
        self.inner.read().expect("lock poisoned")
            .runtime_ref()
            .entropy_source()
    }

    /// Generate a random u64 via capability.
    /// 
    /// This is the ONLY way to obtain random numbers in tasks.
    /// Using std::rand, thread_rng(), or similar will break determinism.
    pub fn random_u64(&self) -> u64 {
        let val = self.entropy().next_u64();

        #[cfg(feature = "trace-entropy")]
        tracing::trace!(
            source = self.entropy().source_id(),
            value = val,
            task = %self.task_id(),
            "entropy: random_u64"
        );

        val
    }

    /// Generate random bytes via capability.
    pub fn random_bytes(&self, dest: &mut [u8]) {
        self.entropy().fill_bytes(dest);

        #[cfg(feature = "trace-entropy")]
        tracing::trace!(
            source = self.entropy().source_id(),
            len = dest.len(),
            task = %self.task_id(),
            "entropy: random_bytes"
        );
    }

    /// Generate a random value in range [0, bound).
    /// 
    /// Uses rejection sampling to avoid modulo bias.
    pub fn random_usize(&self, bound: usize) -> usize {
        assert!(bound > 0, "bound must be non-zero");

        // Rejection sampling for unbiased results
        let bound = bound as u64;
        let threshold = u64::MAX - (u64::MAX % bound);

        loop {
            let val = self.random_u64();
            if val < threshold {
                return (val % bound) as usize;
            }
        }
    }

    /// Shuffle a slice in place deterministically.
    pub fn shuffle<T>(&self, slice: &mut [T]) {
        // Fisher-Yates shuffle
        for i in (1..slice.len()).rev() {
            let j = self.random_usize(i + 1);
            slice.swap(i, j);
        }
    }

    /// Generate a random boolean.
    pub fn random_bool(&self) -> bool {
        self.random_u64() & 1 == 1
    }

    /// Generate a random f64 in range [0, 1).
    pub fn random_f64(&self) -> f64 {
        // Use 53 bits for mantissa precision
        (self.random_u64() >> 11) as f64 / (1u64 << 53) as f64
    }
}
