        sum
    });

    let elapsed = start.elapsed();
    let ops_per_sec = iterations as f64 / elapsed.as_secs_f64();

    println!("Entropy performance: {ops_per_sec:.0} ops/sec");

    // Should be at least 1M ops/sec on reasonable hardware
    assert!(
        ops_per_sec > 100_000.0,
        "Entropy performance too slow: {ops_per_sec:.0} ops/sec"
    );
}

#[test]
fn e2e_many_tasks_deterministic() {
    const NUM_TASKS: usize = 1000;

    let collect_results = |seed| {
        let config = LabConfig {
            entropy_seed: seed,
            ..Default::default()
        };

        let mut rt = LabRuntime::with_config(config);

        rt.block_on(async {
            let cx = rt.root_cx();

            cx.region(|sub| async move {
                let handles: Vec<_> = (0..NUM_TASKS)
                    .map(|_| sub.spawn(async move |cx| cx.random_u64()))
                    .collect();

                let mut results = Vec::with_capacity(NUM_TASKS);
                for h in handles {
                    results.push(h.await);
                }
                results
            }).await
        })
    };

    let results1 = collect_results(42);
    let results2 = collect_results(42);

    assert_eq!(results1.len(), NUM_TASKS);
