fn e2e_concurrent_entropy_access() {
    // Test that multiple tasks accessing entropy concurrently is deterministic
    let config = LabConfig {
        entropy_seed: 12345,
        ..Default::default()
    };

    let mut rt = LabRuntime::with_config(config);

    let results: Vec<u64> = rt.block_on(async {
        let cx = rt.root_cx();

        cx.region(|sub| async move {
            let results = Arc::new(parking_lot::Mutex::new(Vec::new()));

            // Spawn 100 tasks that each generate 10 random numbers
            let handles: Vec<_> = (0..100).map(|_| {
                let res = results.clone();
                sub.spawn(async move |cx| {
                    let mut local = Vec::new();
                    for _ in 0..10 {
