            for h in handles {
                h.await;
            }

            Arc::try_unwrap(results).unwrap().into_inner()
        }).await
    });

    // Run again with same seed
    let mut rt2 = LabRuntime::with_config(LabConfig {
        entropy_seed: 12345,
        ..Default::default()
    });

    let results2: Vec<u64> = rt2.block_on(async {
        let cx = rt2.root_cx();

        cx.region(|sub| async move {
            let results = Arc::new(parking_lot::Mutex::new(Vec::new()));

            let handles: Vec<_> = (0..100).map(|_| {
                let res = results.clone();
                sub.spawn(async move |cx| {
                    let mut local = Vec::new();
                    for _ in 0..10 {
                        local.push(cx.random_u64());
                    }
                    res.lock().extend(local);
                })
            }).collect();

            for h in handles {
                h.await;
            }

            Arc::try_unwrap(results).unwrap().into_inner()
        }).await
    });

