```rust
#[derive(Debug, Error)]
pub enum DecodingError {
    #[error("Authentication failed for symbol {symbol_id}")]
    AuthenticationFailed { symbol_id: SymbolId },

    #[error("Insufficient symbols: have {received}, need {needed}")]
    InsufficientSymbols { received: usize, needed: usize },

    #[error("Matrix inversion failed: {reason}")]
    MatrixInversionFailed { reason: String },

    #[error("Block timeout after {elapsed:?}")]
    BlockTimeout { sbn: u8, elapsed: Duration },

    #[error("Inconsistent block metadata")]
    InconsistentMetadata { sbn: u8, details: String },

    #[error("Memory limit exceeded")]
    MemoryLimitExceeded,

    #[error("Symbol size mismatch: expected {expected}, got {actual}")]
    SymbolSizeMismatch { expected: u16, actual: u16 },
}

pub enum RejectReason {
    WrongObjectId,
    AuthenticationFailed,
    SymbolSizeMismatch,
    BlockAlreadyDecoded,
    MemoryLimitReached,
}
