# Task: Implement LabReactor Fault Injection API

## What

Add APIs to LabReactor for injecting I/O failures, simulating network conditions, and testing error handling paths.

## Location

`src/runtime/reactor/lab.rs` or `src/lab/fault_injection.rs`

## Design

```rust
/// Fault injection configuration for a token.
#[derive(Clone, Debug)]
pub struct FaultConfig {
    /// Probability of read failure (0.0 - 1.0)
    pub read_fail_probability: f64,
    /// Probability of write failure (0.0 - 1.0)
    pub write_fail_probability: f64,
    /// Error to return on failure
    pub error_kind: io::ErrorKind,
    /// Simulate connection reset after N operations
    pub reset_after_ops: Option<u64>,
    /// Simulate slow connection (delay added to each op)
    pub latency: Duration,
}

impl Default for FaultConfig {
    fn default() -> Self {
        Self {
            read_fail_probability: 0.0,
            write_fail_probability: 0.0,
            error_kind: io::ErrorKind::Other,
            reset_after_ops: None,
            latency: Duration::ZERO,
        }
    }
}

impl LabReactor {
    /// Set fault injection config for a specific token.
    pub fn set_fault_config(&self, token: Token, config: FaultConfig) {
        self.sources.borrow_mut()
            .get_mut(&token)
            .map(|s| s.fault_config = Some(config));
    }

    /// Inject an immediate error for a token.
    pub fn inject_error(&self, token: Token, error: io::ErrorKind) {
        self.sources.borrow_mut()
            .get_mut(&token)
            .map(|s| s.pending_error = Some(error));
    }

    /// Simulate connection close/reset.
    pub fn inject_close(&self, token: Token) {
        // Deliver HUP event
        self.set_ready(token, Interest::HUP);
    }

    /// Simulate network partition (all I/O fails).
    pub fn partition(&self, enable: bool) {
        self.partitioned.set(enable);
    }

    /// Check if an operation should fail based on fault config.
    pub(crate) fn should_fail(&self, token: Token, is_read: bool) -> Option<io::Error> {
        if self.partitioned.get() {
            return Some(io::Error::new(
                io::ErrorKind::ConnectionReset,
                "simulated network partition",
            ));
        }

        let sources = self.sources.borrow();
        let source = sources.get(&token)?;
        let config = source.fault_config.as_ref()?;

        let prob = if is_read {
            config.read_fail_probability
        } else {
            config.write_fail_probability
        };

        if prob > 0.0 {
            let roll: f64 = self.rng.borrow_mut().gen();
            if roll < prob {
                return Some(io::Error::new(
                    config.error_kind,
                    "injected fault",
                ));
            }
        }

        None
    }
}
```

