## What

Create the EpollReactor struct with epoll file descriptor management and basic lifecycle.

## Location

`src/runtime/reactor/epoll.rs` (new file)

## Design

```rust
use nix::sys::epoll::{epoll_create1, EpollFlags};
use std::os::unix::io::RawFd;
use std::sync::Mutex;

/// Epoll-based reactor for Linux.
///
/// Uses edge-triggered mode (EPOLLET) for efficiency.
/// Thread-safe via internal synchronization.
pub struct EpollReactor {
    /// The epoll file descriptor
    epoll_fd: RawFd,
    /// Eventfd for cross-thread wakeup
    wake_fd: RawFd,
    /// Internal state protected by mutex
    inner: Mutex<EpollInner>,
}

struct EpollInner {
    /// Token → Waker mapping
    wakers: TokenSlab,
    /// Token → RawFd mapping (for deregistration)
    fds: HashMap<Token, RawFd>,
    /// Is the reactor shut down?
    shutdown: bool,
}

impl EpollReactor {
    /// Create a new epoll reactor.
    pub fn new() -> io::Result<Self> {
        // Create epoll instance
        let epoll_fd = epoll_create1(EpollFlags::EPOLL_CLOEXEC)
            .map_err(|e| io::Error::from_raw_os_error(e as i32))?;

        // Create eventfd for wakeup
        let wake_fd = nix::sys::eventfd::eventfd(
            0,
            nix::sys::eventfd::EfdFlags::EFD_CLOEXEC | 
            nix::sys::eventfd::EfdFlags::EFD_NONBLOCK,
        ).map_err(|e| io::Error::from_raw_os_error(e as i32))?;

        let reactor = Self {
            epoll_fd,
            wake_fd,
            inner: Mutex::new(EpollInner {
                wakers: TokenSlab::new(),
                fds: HashMap::new(),
                shutdown: false,
            }),
        };

        // Register wake_fd with epoll
        reactor.register_wake_fd()?;

        Ok(reactor)
    }

    fn register_wake_fd(&self) -> io::Result<()> {
        // ... register wake_fd for EPOLLIN
    }
}

impl Drop for EpollReactor {
    fn drop(&mut self) {
        // Close epoll_fd and wake_fd
        unsafe {
            libc::close(self.epoll_fd);
            libc::close(self.wake_fd);
        }
    }
}
```

## Dependencies

This uses the `nix` crate for safe syscall wrappers. Add to Cargo.toml:

```toml
[target.'cfg(target_os = "linux")'.dependencies]
nix = { version = "0.27", features = ["event", "poll"] }
```

## Safety Considerations

1. **File descriptor ownership**: epoll_fd and wake_fd owned by EpollReactor
2. **Close-on-exec**: Use CLOEXEC to prevent fd leak to child processes
3. **Thread safety**: All mutable access through Mutex<EpollInner>

