### 3. HTTP Timeout Integration Pattern
Document the recommended pattern:
```rust
// In fastapi_rust middleware:
async fn timeout_middleware<B>(
    req: Request<B>,
    next: Next<B>,
    timeout: Duration,
) -> Outcome<Response, TimeoutError> {
    let budget = Budget::deadline(Instant::now() + timeout);
    let cx = req.extensions().get::<Cx>()?.with_budget(budget);

    // Handler runs with budget; exceeding deadline -> Cancelled
    match next.run_with_cx(req, &cx).await {
        Outcome::Cancelled(reason) if reason.is_deadline() => {
            Outcome::Err(TimeoutError::RequestTimeout)
        }
        other => other,
    }
}
```

