## What

Implement the full Reactor trait for KqueueReactor.

## Location

`src/runtime/reactor/kqueue.rs`

## Design

```rust
impl Reactor for KqueueReactor {
    fn register(
        &self,
        source: &dyn Source,
        interest: Interest,
        waker: Waker,
    ) -> io::Result<Registration> {
        let fd = source.raw_fd();

        let mut inner = self.inner.lock().unwrap();
        let token = inner.wakers.insert(waker);

        // Build kevents for requested interest
        let mut changes = Vec::new();

        if interest.contains(Interest::READABLE) {
            changes.push(libc::kevent {
                ident: fd as usize,
                filter: libc::EVFILT_READ,
                flags: libc::EV_ADD | libc::EV_CLEAR,
                fflags: 0,
                data: 0,
                udata: token.to_usize() as *mut libc::c_void,
            });
        }

        if interest.contains(Interest::WRITABLE) {
            changes.push(libc::kevent {
                ident: fd as usize,
                filter: libc::EVFILT_WRITE,
                flags: libc::EV_ADD | libc::EV_CLEAR,
                fflags: 0,
                data: 0,
                udata: token.to_usize() as *mut libc::c_void,
            });
        }

        // Submit changes
        let ret = unsafe {
            libc::kevent(
                self.kq_fd,
                changes.as_ptr(),
                changes.len() as i32,
                std::ptr::null_mut(),
                0,
                std::ptr::null(),
            )
        };

        if ret < 0 {
            inner.wakers.remove(token);
            return Err(io::Error::last_os_error());
        }

        let filter_set = FilterSet {
            read: interest.contains(Interest::READABLE),
            write: interest.contains(Interest::WRITABLE),
        };
        inner.registrations.insert(token, (fd, filter_set));

        Ok(Registration::new(token, /* weak self */, interest))
    }

    fn poll(&self, events: &mut Events, timeout: Option<Duration>) -> io::Result<usize> {
        events.clear();

        let timespec = timeout.map(|d| libc::timespec {
            tv_sec: d.as_secs() as i64,
            tv_nsec: d.subsec_nanos() as i64,
        });

        let mut kevents = [libc::kevent {
            ident: 0,
            filter: 0,
            flags: 0,
            fflags: 0,
            data: 0,
            udata: std::ptr::null_mut(),
        }; 256];

        let n = unsafe {
            libc::kevent(
                self.kq_fd,
                std::ptr::null(),
                0,
                kevents.as_mut_ptr(),
                kevents.len() as i32,
                timespec.as_ref().map_or(std::ptr::null(), |t| t),
            )
        };

        if n < 0 {
            let err = io::Error::last_os_error();
            if err.kind() == io::ErrorKind::Interrupted {
                return Ok(0);
            }
            return Err(err);
        }

        for i in 0..n as usize {
            let kev = &kevents[i];

            // Skip wake pipe
            if kev.ident == self.wake_pipe.0 as usize {
                self.drain_wake_pipe();
                continue;
            }

            let token = Token::from_usize(kev.udata as usize);
            let ready = self.filter_to_interest(kev.filter, kev.flags);
            events.push(Event { token, ready });
        }

        Ok(events.len())
    }

    fn wake(&self) -> io::Result<()> {
        // Write a byte to wake pipe
        let buf = [1u8];
        match unsafe { libc::write(self.wake_pipe.1, buf.as_ptr() as *const _, 1) } {
            n if n > 0 => Ok(()),
            _ => {
                let err = io::Error::last_os_error();
                if err.kind() == io::ErrorKind::WouldBlock {
                    Ok(()) // Pipe already has data
                } else {
                    Err(err)
                }
            }
        }
    }

    fn deregister(&self, token: Token) -> io::Result<()> {
        let mut inner = self.inner.lock().unwrap();

        let (fd, filter_set) = inner.registrations.remove(&token)
            .ok_or_else(|| io::Error::new(io::ErrorKind::NotFound, "not registered"))?;

        // Remove kevents
        let mut changes = Vec::new();
        if filter_set.read {
            changes.push(libc::kevent {
                ident: fd as usize,
                filter: libc::EVFILT_READ,
                flags: libc::EV_DELETE,
                fflags: 0,
                data: 0,
                udata: std::ptr::null_mut(),
            });
        }
        if filter_set.write {
            changes.push(libc::kevent {
                ident: fd as usize,
                filter: libc::EVFILT_WRITE,
                flags: libc::EV_DELETE,
                fflags: 0,
                data: 0,
                udata: std::ptr::null_mut(),
            });
        }

        // Ignore errors (fd may already be closed)
        unsafe {
            libc::kevent(
                self.kq_fd,
                changes.as_ptr(),
                changes.len() as i32,
                std::ptr::null_mut(),
                0,
                std::ptr::null(),
            );
        }

        inner.wakers.remove(token);
        Ok(())
    }

    fn modify(&self, token: Token, interest: Interest) -> io::Result<()> {
        // kqueue: deregister old filters, register new
        // ... implementation similar to register but with EV_DELETE first
    }

    fn len(&self) -> usize {
        self.inner.lock().unwrap().wakers.len()
    }
}
```

