## API Surface

### Encoding API

```rust
impl StateEncoder {
    /// One-shot encoding of a snapshot.
    pub fn encode(&mut self, snapshot: &RegionSnapshot) -> Result<EncodedState, Error> {
        // 1. Serialize snapshot to bytes
        let data = snapshot.to_bytes();

        // 2. Generate object ID
        let object_id = ObjectId::new_random(&mut self.rng);

        // 3. Calculate encoding parameters
        let params = self.calculate_params(data.len(), object_id);

        // 4. Split into source symbols
        let source_symbols = self.create_source_symbols(&data, &params);

        // 5. Generate repair symbols
        let repair_symbols = self.create_repair_symbols(&source_symbols, &params);

        // 6. Combine and return
        Ok(EncodedState {
            params,
            symbols: [source_symbols, repair_symbols].concat(),
            source_count: params.symbols_per_block,
            repair_count: self.config.min_repair_symbols,
            original_size: data.len(),
            encoded_at: Time::now(), // Or passed in for determinism
        })
    }

    fn calculate_params(&self, data_size: usize, object_id: ObjectId) -> ObjectParams {
        let symbol_size = self.config.symbol_size as usize;
        let symbols_needed = (data_size + symbol_size - 1) / symbol_size;

        ObjectParams::new(
            object_id,
            data_size as u64,
            self.config.symbol_size,
            1, // source_blocks
            symbols_needed as u16,
        )
    }
}
```

### Distribution API

```rust
impl SymbolDistributor {
    /// Distributes encoded state to replicas.
    pub async fn distribute(
        &mut self,
        encoded: &EncodedState,
        replicas: &[ReplicaInfo],
    ) -> Result<DistributionResult, Error> {
        let start = Instant::now();

        // 1. Assign symbols to replicas
        let assigner = SymbolAssigner::new(AssignmentStrategy::Full);
        let assignments = assigner.assign(
            &encoded.symbols,
            replicas,
            encoded.source_count,
        );

        // 2. Calculate required acks based on consistency
        let required_acks = match self.config.consistency {
            ConsistencyLevel::One => 1,
            ConsistencyLevel::Quorum => (replicas.len() / 2) + 1,
            ConsistencyLevel::All => replicas.len(),
            ConsistencyLevel::Local => 0, // No distribution
        };

        // 3. Send symbols to replicas concurrently
        let outcomes = self.send_to_replicas(&assignments, &encoded.symbols).await;

        // 4. Apply quorum semantics
        let quorum_result = quorum_outcomes(required_acks, outcomes);

        // 5. Build result
        Ok(DistributionResult {
            object_id: encoded.params.object_id,
            symbols_distributed: encoded.symbols.len() as u32,
            acks: quorum_result.successes.into_iter().map(|(_, ack)| ack).collect(),
            failures: quorum_result.failures.into_iter().filter_map(|(_, f)| {
                match f {
                    QuorumFailure::Error(e) => Some(e),
                    _ => None,
                }
            }).collect(),
            quorum_achieved: quorum_result.quorum_met,
            duration: start.elapsed(),
        })
    }
}
```

