## Logging Strategy

```rust
use crate::observability::{LogEntry, LogLevel};

impl StateEncoder {
    fn log_encoding_start(&self, snapshot: &RegionSnapshot) {
        LogEntry::new(LogLevel::Debug, "state_encoding_start")
            .with_field("region_id", snapshot.region_id.to_string())
            .with_field("sequence", snapshot.sequence.to_string())
            .with_field("tasks", snapshot.tasks.len().to_string())
            .with_field("estimated_size", snapshot.size_estimate().to_string());
    }

    fn log_encoding_complete(&self, encoded: &EncodedState) {
        LogEntry::new(LogLevel::Info, "state_encoding_complete")
            .with_field("object_id", encoded.params.object_id.to_string())
            .with_field("source_symbols", encoded.source_count.to_string())
            .with_field("repair_symbols", encoded.repair_count.to_string())
            .with_field("original_size", encoded.original_size.to_string())
            .with_field("redundancy", format!("{:.2}", encoded.redundancy_factor()));
    }
}

impl SymbolDistributor {
    fn log_distribution_start(&self, object_id: ObjectId, replica_count: usize) {
        LogEntry::new(LogLevel::Debug, "symbol_distribution_start")
            .with_field("object_id", object_id.to_string())
            .with_field("replicas", replica_count.to_string())
            .with_field("consistency", format!("{:?}", self.config.consistency));
    }

    fn log_distribution_complete(&self, result: &DistributionResult) {
        let level = if result.quorum_achieved {
            LogLevel::Info
        } else {
            LogLevel::Warn
        };

        LogEntry::new(level, "symbol_distribution_complete")
            .with_field("object_id", result.object_id.to_string())
            .with_field("symbols_distributed", result.symbols_distributed.to_string())
            .with_field("acks", result.acks.len().to_string())
            .with_field("failures", result.failures.len().to_string())
            .with_field("quorum_achieved", result.quorum_achieved.to_string())
            .with_field("duration_ms", result.duration.as_millis().to_string());
    }

    fn log_replica_ack(&self, ack: &ReplicaAck) {
        LogEntry::new(LogLevel::Trace, "replica_ack_received")
            .with_field("replica_id", ack.replica_id.clone())
            .with_field("symbols_received", ack.symbols_received.to_string());
    }

    fn log_replica_failure(&self, failure: &ReplicaFailure) {
        LogEntry::new(LogLevel::Warn, "replica_distribution_failed")
            .with_field("replica_id", failure.replica_id.clone())
            .with_field("error", failure.error.clone())
            .with_field("error_kind", format!("{:?}", failure.error_kind));
    }
}

// Log level guidelines:
// - TRACE: Individual symbol sends, replica heartbeats
// - DEBUG: Encoding start, assignment calculations
// - INFO:  Encoding complete, distribution complete (success)
// - WARN:  Distribution with failures, quorum not achieved
// - ERROR: Encoding failure, all replicas failed
```

