#[tokio::test]
async fn test_missed_tick_burst() {
    let start = Instant::now();
    let mut interval = interval_at(start, Duration::from_millis(10));
    interval.set_missed_tick_behavior(MissedTickBehavior::Burst);

    // Intentionally delay
    sleep(Duration::from_millis(35)).await;

    // Should get multiple ticks quickly
    let t1 = interval.tick().await;
    let t2 = interval.tick().await;
    let t3 = interval.tick().await;

    // Ticks should be close together (catching up)
    let now = Instant::now();
    assert!(now.duration_since(t1) < Duration::from_millis(20));
}

#[tokio::test]
async fn test_missed_tick_delay() {
    let start = Instant::now();
    let mut interval = interval_at(start, Duration::from_millis(10));
    interval.set_missed_tick_behavior(MissedTickBehavior::Delay);

    // Intentionally delay
    sleep(Duration::from_millis(35)).await;

    let before = Instant::now();
    interval.tick().await;

    // Next tick should be period from now, not catch up
    let t2 = interval.tick().await;
    assert!(t2 >= before + Duration::from_millis(10));
}

#[tokio::test]
async fn test_missed_tick_skip() {
    let start = Instant::now();
    let mut interval = interval_at(start, Duration::from_millis(10));
    interval.set_missed_tick_behavior(MissedTickBehavior::Skip);

    // Intentionally delay past several periods
    sleep(Duration::from_millis(35)).await;

    // Should skip to next aligned tick
    let t1 = interval.tick().await;
    assert!(t1 >= start + Duration::from_millis(40)); // Aligned to next period
}

