```rust
// src/cli/output.rs

use clap::ValueEnum;
use serde::Serialize;
use std::io::{self, IsTerminal, Write};

/// Output format selection
#[derive(Clone, Copy, Debug, Default, ValueEnum)]
pub enum OutputFormat {
    /// Human-readable with colors and formatting
    #[default]
    Human,

    /// Compact JSON (one object per line for streaming)
    Json,

    /// Streaming JSON (newline-delimited JSON)
    StreamJson,

    /// Pretty-printed JSON (for debugging)
    JsonPretty,

    /// Tab-separated values (for shell scripting)
    Tsv,
}

impl OutputFormat {
    /// Detect appropriate format based on environment
    pub fn auto_detect() -> Self {
        // Use JSON when:
        // 1. CI environment detected
        // 2. Not a TTY (piped output)
        // 3. ASUPERSYNC_OUTPUT_FORMAT env var set to json
        if std::env::var("CI").is_ok() {
            return Self::Json;
        }

        if !io::stdout().is_terminal() {
            return Self::Json;
        }

        if let Ok(format) = std::env::var("ASUPERSYNC_OUTPUT_FORMAT") {
            match format.to_lowercase().as_str() {
                "json" => return Self::Json,
                "stream-json" | "streamjson" => return Self::StreamJson,
                "json-pretty" | "jsonpretty" => return Self::JsonPretty,
                "tsv" => return Self::Tsv,
                _ => {}
            }
        }

        Self::Human
    }
}

/// Color choice for output
#[derive(Clone, Copy, Debug)]
pub enum ColorChoice {
    Auto,
    Always,
    Never,
}

impl ColorChoice {
    /// Detect appropriate color setting based on environment
    pub fn auto_detect() -> Self {
        // NO_COLOR takes precedence (https://no-color.org/)
        if std::env::var("NO_COLOR").is_ok() {
            return Self::Never;
        }

        // CLICOLOR_FORCE forces colors
        if std::env::var("CLICOLOR_FORCE").is_ok() {
            return Self::Always;
        }

        // Auto-detect based on terminal
        if io::stdout().is_terminal() {
            Self::Auto
        } else {
            Self::Never
        }
    }

    /// Check if colors should be used
    pub fn should_colorize(&self) -> bool {
        match self {
            Self::Always => true,
            Self::Never => false,
            Self::Auto => io::stdout().is_terminal(),
        }
    }
}

/// Trait for types that can be output in multiple formats
pub trait Outputtable: Serialize {
    /// Human-readable representation
    fn human_format(&self) -> String;

    /// Short one-line summary for human output
    fn human_summary(&self) -> String {
        self.human_format()
    }

    /// TSV representation (tab-separated fields)
    fn tsv_format(&self) -> String {
        self.human_summary()
    }
}

/// Output writer that handles format switching
pub struct Output {
    format: OutputFormat,
    color: ColorChoice,
    writer: Box<dyn Write>,
}

impl Output {
    pub fn new(format: OutputFormat) -> Self {
        Self {
            format,
            color: ColorChoice::auto_detect(),
            writer: Box::new(io::stdout()),
        }
    }

    pub fn with_writer(format: OutputFormat, writer: Box<dyn Write>) -> Self {
        Self {
            format,
            color: ColorChoice::Never, // No colors for custom writers
            writer,
        }
    }

    pub fn with_color(mut self, color: ColorChoice) -> Self {
        self.color = color;
        self
    }

    /// Check if colors should be used
    pub fn use_colors(&self) -> bool {
        self.color.should_colorize()
    }

    /// Write a single value
    pub fn write<T: Outputtable>(&mut self, value: &T) -> io::Result<()> {
        match self.format {
            OutputFormat::Human => {
                writeln!(self.writer, "{}", value.human_format())?;
            }
            OutputFormat::Json => {
                let json = serde_json::to_string(value)
                    .map_err(|e| io::Error::new(io::ErrorKind::InvalidData, e))?;
                writeln!(self.writer, "{}", json)?;
            }
            OutputFormat::JsonPretty => {
                let json = serde_json::to_string_pretty(value)
                    .map_err(|e| io::Error::new(io::ErrorKind::InvalidData, e))?;
                writeln!(self.writer, "{}", json)?;
            }
            OutputFormat::StreamJson => {
                let json = serde_json::to_string(value)
                    .map_err(|e| io::Error::new(io::ErrorKind::InvalidData, e))?;
                writeln!(self.writer, "{}", json)?;
                self.writer.flush()?; // Flush for streaming
            }
            OutputFormat::Tsv => {
                writeln!(self.writer, "{}", value.tsv_format())?;
            }
        }
        Ok(())
    }

    /// Write a list of values
    pub fn write_list<T: Outputtable>(&mut self, values: &[T]) -> io::Result<()> {
        match self.format {
            OutputFormat::Human => {
                for value in values {
                    writeln!(self.writer, "{}", value.human_format())?;
                }
            }
            OutputFormat::Json => {
                let json = serde_json::to_string(values)
                    .map_err(|e| io::Error::new(io::ErrorKind::InvalidData, e))?;
                writeln!(self.writer, "{}", json)?;
            }
            OutputFormat::StreamJson => {
                for value in values {
                    let json = serde_json::to_string(value)
                        .map_err(|e| io::Error::new(io::ErrorKind::InvalidData, e))?;
                    writeln!(self.writer, "{}", json)?;
                    self.writer.flush()?;
                }
            }
            _ => {
                for value in values {
                    self.write(value)?;
                }
            }
        }
        Ok(())
    }

    /// Flush the output
    pub fn flush(&mut self) -> io::Result<()> {
        self.writer.flush()
    }
}
```

### 2. Structured Error Messages (RFC 9457 Style)

```rust
// src/cli/error.rs

use serde::{Serialize, Deserialize};
use std::collections::HashMap;

/// Structured error following RFC 9457 (Problem Details)
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct CliError {
    /// Error type identifier (machine-readable)
    #[serde(rename = "type")]
    pub error_type: String,

    /// Short human-readable title
    pub title: String,

    /// Detailed explanation
    #[serde(default, skip_serializing_if = "String::is_empty")]
    pub detail: String,

    /// Suggested action for recovery
    #[serde(skip_serializing_if = "Option::is_none")]
    pub suggestion: Option<String>,

    /// Related documentation URL
    #[serde(skip_serializing_if = "Option::is_none")]
    pub docs_url: Option<String>,

    /// Additional context (varies by error type)
    #[serde(default, skip_serializing_if = "HashMap::is_empty")]
    pub context: HashMap<String, serde_json::Value>,

    /// Exit code for this error
    pub exit_code: i32,
}

impl CliError {
    pub fn new(error_type: impl Into<String>, title: impl Into<String>) -> Self {
        Self {
            error_type: error_type.into(),
            title: title.into(),
            detail: String::new(),
            suggestion: None,
            docs_url: None,
            context: HashMap::new(),
            exit_code: 1,
        }
    }

    pub fn detail(mut self, detail: impl Into<String>) -> Self {
        self.detail = detail.into();
        self
    }

    pub fn suggestion(mut self, suggestion: impl Into<String>) -> Self {
        self.suggestion = Some(suggestion.into());
        self
    }

    pub fn docs(mut self, url: impl Into<String>) -> Self {
        self.docs_url = Some(url.into());
        self
    }

    pub fn context(mut self, key: impl Into<String>, value: impl Serialize) -> Self {
        if let Ok(v) = serde_json::to_value(value) {
            self.context.insert(key.into(), v);
        }
        self
    }

    pub fn exit_code(mut self, code: i32) -> Self {
        self.exit_code = code;
        self
    }

    /// Format for human output
    pub fn human_format(&self, color: bool) -> String {
        let mut out = String::new();

        // Error title in red
        if color {
            out.push_str("\x1b[1;31m"); // Bold red
        }
        out.push_str("Error: ");
        out.push_str(&self.title);
        if color {
            out.push_str("\x1b[0m"); // Reset
        }
        out.push(n);

        // Detail in normal text
        if !self.detail.is_empty() {
            out.push_str(&self.detail);
            out.push(n);
        }

        // Suggestion in yellow
        if let Some(ref suggestion) = self.suggestion {
            out.push(n);
            if color {
                out.push_str("\x1b[33m"); // Yellow
            }
            out.push_str("Suggestion: ");
            out.push_str(suggestion);
            if color {
                out.push_str("\x1b[0m");
            }
            out.push(n);
        }

        // Docs link in blue/underline
        if let Some(ref docs) = self.docs_url {
            if color {
                out.push_str("\x1b[4;34m"); // Underline blue
            }
            out.push_str("See: ");
            out.push_str(docs);
            if color {
                out.push_str("\x1b[0m");
            }
            out.push(n);
        }

        // Context in dim
        if !self.context.is_empty() {
            out.push(n);
            if color {
                out.push_str("\x1b[2m"); // Dim
            }
            out.push_str("Context:\n");
            for (k, v) in &self.context {
                out.push_str(&format!("  {}: {}\n", k, v));
            }
            if color {
                out.push_str("\x1b[0m");
            }
        }

        out
    }

    /// Format as JSON
    pub fn json_format(&self) -> String {
        serde_json::to_string(self).unwrap_or_else(|_| self.title.clone())
    }
}

impl std::fmt::Display for CliError {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        write!(f, "{}: {}", self.error_type, self.title)
    }
}

