### 4. Signal Handling

```rust
// src/cli/signal.rs

use std::sync::atomic::{AtomicBool, Ordering};
use std::sync::Arc;

/// Global cancellation flag for signal handling
static CANCELLED: AtomicBool = AtomicBool::new(false);

/// Check if cancellation has been requested
pub fn is_cancelled() -> bool {
    CANCELLED.load(Ordering::SeqCst)
}

/// Request cancellation (called by signal handler)
pub fn request_cancel() {
    CANCELLED.store(true, Ordering::SeqCst);
}

/// Reset cancellation flag (for testing)
pub fn reset_cancel() {
    CANCELLED.store(false, Ordering::SeqCst);
}

/// Install signal handlers for graceful shutdown
/// 
/// Handles:
/// - SIGINT (Ctrl+C)
/// - SIGTERM (kill)
/// 
/// On first signal: sets cancellation flag
/// On second signal: exits immediately
pub fn install_signal_handlers() -> Result<(), Box<dyn std::error::Error>> {
    #[cfg(unix)]
    {
        use signal_hook::consts::{SIGINT, SIGTERM};
        use signal_hook::iterator::Signals;
        use std::thread;

        let mut signals = Signals::new(&[SIGINT, SIGTERM])?;

        thread::spawn(move || {
            let mut first_signal = true;
            for sig in signals.forever() {
                match sig {
                    SIGINT | SIGTERM => {
                        if first_signal {
                            eprintln!("\nReceived signal, cancelling... (press again to force quit)");
                            request_cancel();
                            first_signal = false;
                        } else {
                            eprintln!("\nForce quitting");
                            std::process::exit(ExitCode::CANCELLED);
                        }
                    }
                    _ => {}
                }
            }
        });
    }

    #[cfg(windows)]
    {
        ctrlc::set_handler(move || {
            static FIRST: AtomicBool = AtomicBool::new(true);

            if FIRST.swap(false, Ordering::SeqCst) {
                eprintln!("\nReceived Ctrl+C, cancelling... (press again to force quit)");
                request_cancel();
            } else {
                eprintln!("\nForce quitting");
                std::process::exit(ExitCode::CANCELLED);
            }
        })?;
    }

    Ok(())
}

/// Signal-aware iterator wrapper
pub struct Interruptible<I> {
    inner: I,
}

impl<I> Interruptible<I> {
    pub fn new(inner: I) -> Self {
        Self { inner }
    }
}

impl<I: Iterator> Iterator for Interruptible<I> {
    type Item = Result<I::Item, ()>;

    fn next(&mut self) -> Option<Self::Item> {
        if is_cancelled() {
            return Some(Err(()));
        }
        self.inner.next().map(Ok)
    }
}

/// Extension trait for making iterators interruptible
pub trait InterruptibleExt: Iterator + Sized {
    fn interruptible(self) -> Interruptible<Self> {
        Interruptible::new(self)
    }
}

impl<I: Iterator> InterruptibleExt for I {}
