### 6. Progress Reporting

```rust
// src/cli/progress.rs

use serde::Serialize;
use std::io::{self, IsTerminal, Write};
use std::time::Instant;

/// Progress event for streaming output
#[derive(Debug, Clone, Serialize)]
#[serde(tag = "type")]
pub enum ProgressEvent {
    /// Operation started
    #[serde(rename = "started")]
    Started {
        message: String,
        total: Option<u64>,
    },

    /// Progress update
    #[serde(rename = "progress")]
    Progress {
        current: u64,
        total: Option<u64>,
        message: String,
        percent: Option<f64>,
    },

    /// Operation completed
    #[serde(rename = "completed")]
    Completed {
        message: String,
        duration_ms: u64,
    },

    /// Operation failed
    #[serde(rename = "failed")]
    Failed {
        error: String,
    },

    /// Log message
    #[serde(rename = "log")]
    Log {
        level: String,
        message: String,
    },
}

/// Progress reporter that handles format switching
pub struct ProgressReporter {
    format: super::output::OutputFormat,
    bar: Option<indicatif::ProgressBar>,
    start_time: Instant,
    total: Option<u64>,
}

impl ProgressReporter {
    pub fn new(format: super::output::OutputFormat, total: Option<u64>) -> Self {
        let bar = match format {
            super::output::OutputFormat::Human if io::stdout().is_terminal() => {
                let style = indicatif::ProgressStyle::default_bar()
                    .template("{spinner:.green} [{bar:40.cyan/blue}] {pos}/{len} {msg}")
                    .unwrap_or_else(|_| indicatif::ProgressStyle::default_bar())
                    .progress_chars("#>-");

                let bar = if let Some(total) = total {
                    indicatif::ProgressBar::new(total)
                } else {
                    indicatif::ProgressBar::new_spinner()
                };
                bar.set_style(style);
                Some(bar)
            }
            _ => None,
        };

        Self {
            format,
            bar,
            start_time: Instant::now(),
            total,
        }
    }

    pub fn start(&self, message: &str) {
        match self.format {
            super::output::OutputFormat::Human => {
                if let Some(ref bar) = self.bar {
                    bar.set_message(message.to_string());
                } else {
                    eprintln!("{}", message);
                }
            }
            super::output::OutputFormat::Json 
            | super::output::OutputFormat::StreamJson => {
                let event = ProgressEvent::Started {
                    message: message.to_string(),
                    total: self.total,
                };
                let _ = writeln!(io::stderr(), "{}", serde_json::to_string(&event).unwrap_or_default());
            }
            _ => {}
        }
    }

    pub fn update(&self, current: u64, message: &str) {
        // Check for cancellation
        if super::signal::is_cancelled() {
            return;
        }

        match self.format {
            super::output::OutputFormat::Human => {
                if let Some(ref bar) = self.bar {
                    bar.set_position(current);
                    bar.set_message(message.to_string());
                }
            }
            super::output::OutputFormat::StreamJson => {
                let percent = self.total.map(|t| {
                    if t > 0 { current as f64 / t as f64 * 100.0 } else { 0.0 }
                });

                let event = ProgressEvent::Progress {
                    current,
                    total: self.total,
                    message: message.to_string(),
                    percent,
                };
                let _ = writeln!(io::stderr(), "{}", serde_json::to_string(&event).unwrap_or_default());
            }
            _ => {}
        }
    }

    pub fn log(&self, level: &str, message: &str) {
        match self.format {
            super::output::OutputFormat::Human => {
                if let Some(ref bar) = self.bar {
                    bar.suspend(|| eprintln!("[{}] {}", level, message));
                } else {
                    eprintln!("[{}] {}", level, message);
                }
            }
            super::output::OutputFormat::Json
            | super::output::OutputFormat::StreamJson => {
                let event = ProgressEvent::Log {
                    level: level.to_string(),
                    message: message.to_string(),
                };
                let _ = writeln!(io::stderr(), "{}", serde_json::to_string(&event).unwrap_or_default());
            }
            _ => {}
        }
    }

    pub fn finish(&self, message: &str) {
        let duration = self.start_time.elapsed();

        match self.format {
            super::output::OutputFormat::Human => {
                if let Some(ref bar) = self.bar {
                    bar.finish_with_message(message.to_string());
                } else {
                    eprintln!("{} ({:.2}s)", message, duration.as_secs_f64());
                }
            }
            super::output::OutputFormat::Json
            | super::output::OutputFormat::StreamJson => {
                let event = ProgressEvent::Completed {
                    message: message.to_string(),
                    duration_ms: duration.as_millis() as u64,
                };
                let _ = writeln!(io::stderr(), "{}", serde_json::to_string(&event).unwrap_or_default());
            }
            _ => {}
        }
    }

    pub fn fail(&self, error: &str) {
        match self.format {
            super::output::OutputFormat::Human => {
                if let Some(ref bar) = self.bar {
                    bar.abandon_with_message(format!("Failed: {}", error));
                } else {
                    eprintln!("Failed: {}", error);
                }
            }
            super::output::OutputFormat::Json
            | super::output::OutputFormat::StreamJson => {
                let event = ProgressEvent::Failed {
                    error: error.to_string(),
                };
                let _ = writeln!(io::stderr(), "{}", serde_json::to_string(&event).unwrap_or_default());
            }
            _ => {}
        }
    }
}
