// src/cli/args.rs

use clap::Parser;
use super::output::OutputFormat;

/// Standard arguments available to all Asupersync CLI tools
#[derive(Parser, Debug, Clone)]
pub struct StandardArgs {
    /// Output format
    #[arg(long, value_enum, default_value = "human", env = "ASUPERSYNC_OUTPUT_FORMAT")]
    pub output_format: OutputFormat,

    /// Shorthand for --output-format=json
    #[arg(long, conflicts_with = "output_format")]
    pub json: bool,

    /// Disable all interactive prompts
    #[arg(long, env = "ASUPERSYNC_NO_PROMPT")]
    pub no_interactive: bool,

    /// Disable colored output
    #[arg(long, env = "NO_COLOR")]
    pub no_color: bool,

    /// Enable verbose output (-v, -vv, -vvv for more)
    #[arg(short, long, action = clap::ArgAction::Count)]
    pub verbose: u8,

    /// Suppress all output except errors
    #[arg(short, long)]
    pub quiet: bool,

    /// Include timestamps in output
    #[arg(long)]
    pub timestamps: bool,
}

impl StandardArgs {
    /// Get effective output format
    pub fn effective_format(&self) -> OutputFormat {
        if self.json {
            OutputFormat::Json
        } else {
            self.output_format
        }
    }

    /// Check if colors should be used
    pub fn use_colors(&self) -> bool {
        !self.no_color && std::io::stdout().is_terminal()
    }

    /// Get verbosity level (0=quiet, 1=normal, 2+=verbose)
    pub fn verbosity(&self) -> u8 {
        if self.quiet {
            0
        } else {
            1 + self.verbose
        }
    }
}

impl Default for StandardArgs {
    fn default() -> Self {
        Self {
            output_format: OutputFormat::Human,
            json: false,
            no_interactive: false,
            no_color: false,
            verbose: 0,
            quiet: false,
            timestamps: false,
        }
    }
}
