## API Surface

### Encoding API

```rust
impl StateEncoder {
    /// One-shot encoding of a snapshot.
    pub fn encode(&mut self, snapshot: &RegionSnapshot) -> Result<EncodedState, Error> {
        // 1. Serialize snapshot to bytes
        let data = snapshot.to_bytes();

        // 2. Generate object ID
        let object_id = ObjectId::new_random(&mut self.rng);

        // 3. Calculate encoding parameters
        let params = self.calculate_params(data.len(), object_id);

        // 4. Split into source symbols
        let source_symbols = self.create_source_symbols(&data, &params);

        // 5. Generate repair symbols
        let repair_symbols = self.create_repair_symbols(&source_symbols, &params);

        // 6. Combine and return
        Ok(EncodedState {
            params,
            symbols: [source_symbols, repair_symbols].concat(),
            source_count: params.symbols_per_block,
            repair_count: self.config.min_repair_symbols,
            original_size: data.len(),
            encoded_at: Time::now(), // Or passed in for determinism
        })
    }

    fn calculate_params(&self, data_size: usize, object_id: ObjectId) -> ObjectParams {
        let symbol_size = self.config.symbol_size as usize;
        let symbols_needed = (data_size + symbol_size - 1) / symbol_size;

        ObjectParams::new(
            object_id,
            data_size as u64,
            self.config.symbol_size,
            1, // source_blocks
            symbols_needed as u16,
        )
    }
}
