async fn handle_request(cx: &Cx) -> Result<Response, Error> {
    match do_work(cx).await {
        Outcome::Ok(response) => Ok(response),
        Outcome::Cancelled(_) => {
            // Log detailed attribution
            if let Some(reason) = cx.cancel_reason() {
                tracing::info!(
                    kind = ?reason.kind,
                    origin = ?reason.origin_region,
                    message = reason.message.as_deref(),
                    "Request cancelled"
                );

                // Check root cause
                if cx.any_cause_is(CancelKind::Deadline) {
                    metrics::increment("requests.timeout");
                }
            }
            Err(Error::Cancelled)
        }
        // ... other outcomes
    }
}
