#[tokio::test]
async fn test_transfer_with_symbol_loss() {
    setup_logging();
    tracing::info!("=== E2E: Transfer with Symbol Loss ===");

    let loss_rates = [0.05, 0.10, 0.20, 0.30];

    for loss_rate in loss_rates {
        tracing::info!(loss_rate, "Testing with loss rate");

        let original = generate_random_data(50_000);
        let (tx, rx) = create_lossy_channel(loss_rate);

        // Send all symbols
        let symbols = encode_all(&original);
        let sent = symbols.len();
        for symbol in symbols {
            tx.send(symbol).await.ok(); // May fail due to simulated loss
        }

        // Receive with loss
        let received = collect_available(&rx).await;
        let received_count = received.len();
        let loss_actual = 1.0 - (received_count as f64 / sent as f64);

        tracing::info!(sent, received = received_count, actual_loss = %loss_actual, "Transfer stats");

        // Decode
        let result = decode_symbols(received);

        if result.is_ok() {
            assert_eq!(original, result.unwrap());
            tracing::info!(loss_rate, "PASSED with symbol loss");
        } else {
            // Expected failure at high loss rates
            assert!(loss_rate >= 0.25, "Should succeed at loss rate {}", loss_rate);
            tracing::warn!(loss_rate, "Failed as expected at high loss rate");
        }
    }
}
