#[tokio::test]
async fn test_mid_transfer_cancellation() {
    setup_logging();
    tracing::info!("=== E2E: Mid-Transfer Cancellation ===");

    let lab = LabRuntime::new(LabConfig::default());

    lab.run(|mut cx| async move {
        let (tx, rx) = create_channel_transport();
        let original = generate_random_data(100_000);
        let symbols = encode_all(&original);
        let total_symbols = symbols.len();
        let cancel_at = total_symbols / 2;

        // Spawn sender that will be cancelled
        let send_handle = cx.spawn(async move |cx| {
            for (i, symbol) in symbols.into_iter().enumerate() {
                cx.check_cancelled().await?;

                if i == cancel_at {
                    tracing::info!(i, "Cancellation point reached");
                }

                tx.send(symbol).await?;
            }
            Ok(())
        });

        // Wait a bit then cancel
        cx.sleep(Duration::from_millis(50)).await;
        tracing::info!("Requesting cancellation");
        send_handle.cancel();

        // Verify cancellation completed cleanly
        let result = send_handle.await;
        assert!(matches!(result, Outcome::Cancelled(_)));

        tracing::info!("Sender cancelled cleanly");

        // Verify receiver sees partial data
        let received = collect_available(&rx).await;
        tracing::info!(received = received.len(), "Partial symbols received");
        assert!(received.len() < total_symbols);
        assert!(received.len() >= cancel_at - 10); // Approximate

        tracing::info!("=== PASSED: Mid-Transfer Cancellation ===");
    }).await;
}
