    tracing::info!("=== E2E: Resource Pressure ===");

    // Create constrained resource tracker
    let limits = ResourceLimits {
        max_symbol_memory: 1024 * 1024, // 1MB
        max_encoding_ops: 2,
        max_decoding_ops: 2,
        max_symbols_in_flight: 1000,
    };
    let tracker = Arc::new(Mutex::new(ResourceTracker::new(limits)));

    // Try to encode multiple large objects concurrently
    let objects: Vec<_> = (0..5)
        .map(|i| generate_random_data(500_000))
        .collect();

    let mut handles = vec![];

    for (i, data) in objects.into_iter().enumerate() {
        let tracker = tracker.clone();
        handles.push(tokio::spawn(async move {
            let guard = tracker.lock().await.try_acquire_encoding(data.len());
            match guard {
                Ok(_guard) => {
                    tracing::info!(object = i, "Acquired resources, encoding");
                    let _symbols = encode_all(&data);
                    tracing::info!(object = i, "Encoding complete");
                    Ok(())
                }
                Err(e) => {
                    tracing::warn!(object = i, error = %e, "Resource acquisition failed");
                    Err(e)
                }
            }
        }));
    }

    // Some should succeed, some should fail due to limits
    let results: Vec<_> = futures::future::join_all(handles).await;
    let successes = results.iter().filter(|r| r.as_ref().map(|r| r.is_ok()).unwrap_or(false)).count();
    let failures = results.len() - successes;

    tracing::info!(successes, failures, "Resource pressure results");

    // At least some should succeed, and at least some should be limited
    assert!(successes >= 1, "At least one should succeed");
    assert!(failures >= 1, "Resource limits should kick in");

    tracing::info!("=== PASSED: Resource Pressure ===");
}
```

### Scenario 6: Determinism Verification

```rust
#[tokio::test]
async fn test_determinism() {
    setup_logging();
    tracing::info!("=== E2E: Determinism Verification ===");

    let data = generate_random_data(10_000);

    // Run twice with same seed
    let trace1 = run_with_lab_runtime(42, &data).await;
    let trace2 = run_with_lab_runtime(42, &data).await;

    // Traces should be identical
    assert_eq!(trace1.events.len(), trace2.events.len(), "Event count mismatch");

    for (i, (e1, e2)) in trace1.events.iter().zip(trace2.events.iter()).enumerate() {
        assert_eq!(e1, e2, "Event {} differs", i);
    }

    // Run with different seed
    let trace3 = run_with_lab_runtime(43, &data).await;

    // Should have different timing/ordering
    assert_ne!(trace1.events, trace3.events, "Different seeds should produce different traces");

    tracing::info!("=== PASSED: Determinism Verification ===");
}

async fn run_with_lab_runtime(seed: u64, data: &[u8]) -> Trace {
    let lab = LabRuntime::new(LabConfig { seed, ..Default::default() });

    lab.run_traced(|cx| async move {
        let symbols = encode_all(data);
        let decoded = decode_symbols(symbols)?;
        assert_eq!(data, &decoded[..]);
        Ok(())
    }).await
}
