## Implementation

### TlsAcceptor

```rust
// tls/src/acceptor.rs

use std::sync::Arc;
use std::path::Path;
use rustls::{ServerConfig, ServerConnection};

use crate::{Certificate, CertificateChain, PrivateKey, RootCertStore, TlsError, TlsStream};

/// Server-side TLS acceptor.
///
/// This is typically configured once and reused to accept many connections.
pub struct TlsAcceptor {
    config: Arc<ServerConfig>,
}

impl TlsAcceptor {
    /// Create from a raw rustls ServerConfig.
    pub fn new(config: ServerConfig) -> Self {
        TlsAcceptor {
            config: Arc::new(config),
        }
    }

    /// Create a builder for constructing a TlsAcceptor.
    pub fn builder(chain: CertificateChain, key: PrivateKey) -> TlsAcceptorBuilder {
        TlsAcceptorBuilder::new(chain, key)
    }

    /// Accept a TLS connection, performing the handshake.
    ///
    /// # Cancel-Safety
    /// This method is NOT cancel-safe during handshake. If cancelled mid-handshake,
    /// the connection is in an undefined state and should be dropped.
    pub async fn accept<IO>(
        &self,
        stream: IO,
    ) -> Result<TlsStream<IO>, TlsError>
    where
        IO: AsyncRead + AsyncWrite + Unpin,
    {
        tracing::debug!("Starting TLS accept handshake");

        let conn = ServerConnection::new(self.config.clone())
            .map_err(|e| TlsError::Handshake(e.to_string()))?;

        let mut tls_stream = TlsStream::new_server(stream, conn);

        // Perform the handshake
        tls_stream.handshake().await?;

        tracing::info!(
            protocol = ?tls_stream.protocol_version(),
            alpn = ?tls_stream.alpn_protocol(),
            sni = ?tls_stream.sni_hostname(),
            "TLS accept complete"
        );

        Ok(tls_stream)
    }

    /// Get the inner config (for advanced use).
    pub fn config(&self) -> &Arc<ServerConfig> {
        &self.config
    }
}

impl Clone for TlsAcceptor {
    fn clone(&self) -> Self {
        TlsAcceptor {
            config: self.config.clone(),
        }
    }
}
```

### TlsAcceptorBuilder

```rust
// tls/src/acceptor.rs (continued)

/// Client authentication configuration.
#[derive(Debug, Clone)]
pub enum ClientAuth {
    /// No client authentication required.
    None,
    /// Client certificate is optional.
    Optional(RootCertStore),
    /// Client certificate is required.
    Required(RootCertStore),
}

impl Default for ClientAuth {
    fn default() -> Self {
        ClientAuth::None
    }
}

/// Builder for `TlsAcceptor`.
pub struct TlsAcceptorBuilder {
    cert_chain: CertificateChain,
    key: PrivateKey,
    client_auth: ClientAuth,
    alpn_protocols: Vec<Vec<u8>>,
    session_memory_limit: usize,
    max_fragment_size: Option<usize>,
}

impl TlsAcceptorBuilder {
    /// Create a new builder with the server's certificate and key.
    pub fn new(chain: CertificateChain, key: PrivateKey) -> Self {
        TlsAcceptorBuilder {
            cert_chain: chain,
            key,
            client_auth: ClientAuth::None,
            alpn_protocols: Vec::new(),
            session_memory_limit: 256 * 1024 * 1024, // 256 MB default
            max_fragment_size: None,
        }
    }

    /// Load certificate chain from PEM file.
    pub fn from_pem_file(
        cert_path: impl AsRef<Path>,
        key_path: impl AsRef<Path>,
    ) -> Result<Self, TlsError> {
        let cert_pem = std::fs::read(cert_path.as_ref())
            .map_err(|e| TlsError::Certificate(format!("reading cert: {}", e)))?;
        let key_pem = std::fs::read(key_path.as_ref())
            .map_err(|e| TlsError::Certificate(format!("reading key: {}", e)))?;

        let certs = Certificate::from_pem(&cert_pem)?;
        let key = PrivateKey::from_pem(&key_pem)?;

        tracing::debug!(
            cert_count = certs.len(),
            cert_path = %cert_path.as_ref().display(),
            "Loaded server certificates"
        );

        Ok(Self::new(CertificateChain(certs), key))
    }

    /// Set client authentication mode.
    pub fn client_auth(mut self, auth: ClientAuth) -> Self {
        self.client_auth = auth;
        self
    }

    /// Require client certificates.
    pub fn require_client_auth(self, root_certs: RootCertStore) -> Self {
        self.client_auth(ClientAuth::Required(root_certs))
    }

    /// Allow optional client certificates.
    pub fn optional_client_auth(self, root_certs: RootCertStore) -> Self {
        self.client_auth(ClientAuth::Optional(root_certs))
    }

    /// Set ALPN protocols.
    pub fn alpn_protocols(mut self, protocols: Vec<Vec<u8>>) -> Self {
        self.alpn_protocols = protocols;
        self
    }

    /// Convenience method for HTTP/2 ALPN.
    pub fn alpn_h2(self) -> Self {
        self.alpn_protocols(vec![b"h2".to_vec()])
    }

    /// Convenience method for HTTP/1.1 and HTTP/2 ALPN.
    pub fn alpn_http(self) -> Self {
        self.alpn_protocols(vec![b"h2".to_vec(), b"http/1.1".to_vec()])
    }

    /// Set session memory limit.
    pub fn session_memory_limit(mut self, bytes: usize) -> Self {
        self.session_memory_limit = bytes;
        self
    }

    /// Set maximum TLS fragment size.
    pub fn max_fragment_size(mut self, size: usize) -> Self {
        self.max_fragment_size = Some(size);
        self
    }

    /// Build the TlsAcceptor.
    pub fn build(self) -> Result<TlsAcceptor, TlsError> {
        let mut config = ServerConfig::builder()
            .with_safe_defaults();

        // Configure client auth
        let config = match self.client_auth {
            ClientAuth::None => {
                config.with_no_client_auth()
            }
            ClientAuth::Optional(roots) => {
                let verifier = rustls::server::AllowAnyAnonymousOrAuthenticatedClient::new(roots.into());
                config.with_client_cert_verifier(Arc::new(verifier))
            }
            ClientAuth::Required(roots) => {
                let verifier = rustls::server::AllowAnyAuthenticatedClient::new(roots.into());
                config.with_client_cert_verifier(Arc::new(verifier))
            }
        };

        let mut config = config
            .with_single_cert(self.cert_chain.into(), self.key.into())
            .map_err(|e| TlsError::Configuration(e.to_string()))?;

        // Set ALPN if specified
        if !self.alpn_protocols.is_empty() {
            config.alpn_protocols = self.alpn_protocols;
        }

        // Set max fragment size if specified
        if let Some(size) = self.max_fragment_size {
            config.max_fragment_size = Some(size);
        }

        tracing::debug!(
            alpn = ?config.alpn_protocols,
            client_auth = match &self.client_auth {
                ClientAuth::None => "none",
                ClientAuth::Optional(_) => "optional",
                ClientAuth::Required(_) => "required",
            },
            "TlsAcceptor built"
        );

        Ok(TlsAcceptor::new(config))
    }
}
