## Implementation Steps

### Step 1: Create Route Matching Types

```rust
// src/web/router/route.rs

use std::collections::HashMap;

/// A segment in a route pattern.
#[derive(Debug, Clone, PartialEq, Eq)]
pub enum RouteSegment {
    /// Exact match: `/users`
    Static(String),
    /// Parameter capture: `/:id`
    Param(String),
    /// Wildcard: `/*path` (captures rest)
    Wildcard(String),
}

/// Compiled route pattern for efficient matching.
#[derive(Debug, Clone)]
pub struct RoutePattern {
    segments: Vec<RouteSegment>,
    param_names: Vec<String>,
}

impl RoutePattern {
    /// Parse a route pattern string.
    pub fn parse(pattern: &str) -> Result<Self, RouteError> {
        let mut segments = Vec::new();
        let mut param_names = Vec::new();

        for part in pattern.split('/').filter(|s| !s.is_empty()) {
            let segment = if let Some(name) = part.strip_prefix(':') {
                if name.is_empty() {
                    return Err(RouteError::InvalidPattern("empty parameter name".into()));
                }
                param_names.push(name.to_string());
                RouteSegment::Param(name.to_string())
            } else if let Some(name) = part.strip_prefix('*') {
                if name.is_empty() {
                    return Err(RouteError::InvalidPattern("empty wildcard name".into()));
                }
                param_names.push(name.to_string());
                RouteSegment::Wildcard(name.to_string())
            } else {
                RouteSegment::Static(part.to_string())
            };
            segments.push(segment);
        }

        Ok(Self { segments, param_names })
    }

    /// Match a path and extract parameters.
    pub fn match_path(&self, path: &str) -> Option<PathParams> {
        let parts: Vec<&str> = path.split('/').filter(|s| !s.is_empty()).collect();
        let mut params = HashMap::new();
        let mut part_idx = 0;

        for segment in &self.segments {
            match segment {
                RouteSegment::Static(expected) => {
                    if part_idx >= parts.len() || parts[part_idx] != expected {
                        return None;
                    }
                    part_idx += 1;
                }
                RouteSegment::Param(name) => {
                    if part_idx >= parts.len() {
                        return None;
                    }
                    params.insert(name.clone(), parts[part_idx].to_string());
                    part_idx += 1;
                }
                RouteSegment::Wildcard(name) => {
                    // Capture all remaining segments
                    let rest = parts[part_idx..].join("/");
                    params.insert(name.clone(), rest);
                    return Some(PathParams(params));
                }
            }
        }

        // Must consume all parts
        if part_idx == parts.len() {
            Some(PathParams(params))
        } else {
            None
        }
    }
}

/// Extracted path parameters.
#[derive(Debug, Clone, Default)]
pub struct PathParams(HashMap<String, String>);

impl PathParams {
    /// Get a parameter value.
    pub fn get(&self, name: &str) -> Option<&str> {
        self.0.get(name).map(|s| s.as_str())
    }

    /// Parse a parameter as a specific type.
    pub fn parse<T: std::str::FromStr>(&self, name: &str) -> Option<T> {
        self.0.get(name).and_then(|s| s.parse().ok())
    }
}
```

