### Recoverability
```rust
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Recoverability {
    /// Temporary failure, safe to retry
    Transient,
    /// Unrecoverable, do not retry
    Permanent,
    /// Depends on context
    Unknown,
}

impl ErrorKind {
    pub fn recoverability(&self) -> Recoverability {
        match self {
            // Transient - safe to retry
            ChannelFull | ChannelEmpty | ConnectionLost |
            NodeUnavailable | QuorumNotReached | ThresholdTimeout |
            LeaseRenewalFailed => Recoverability::Transient,

            // Permanent - do not retry
            Cancelled | CancelTimeout | ChannelClosed |
            ObligationLeak | ObligationAlreadyResolved |
            RegionClosed | InvalidEncodingParams | DataTooLarge |
            ObjectMismatch | Internal | InvalidStateTransition
                => Recoverability::Permanent,

            // Unknown - context-dependent
            _ => Recoverability::Unknown,
        }
    }
}
```

