    message = ?error.message(),
    "Error details"
);
tracing::warn!(
    kind = ?error.kind(),
    attempt = attempt,
    "Retrying after transient error"
);
tracing::error!(
    kind = ?error.kind(),
    attempts = attempts,
    "Recovery abandoned"
);
```

