```rust
use asupersync::error::{Error, ErrorKind, Recoverability};

// Create an error with context
let error = Error::new(ErrorKind::InsufficientSymbols)
    .with_message("Need 1000 symbols, have 950")
    .with_context(ErrorContext {
        object_id: Some(object_id),
        ..Default::default()
    });

// Check recoverability
match error.recoverability() {
    Recoverability::Transient => {
        // Retry with backoff
        tokio::time::sleep(backoff.next_duration()).await;
        continue;
    }
    Recoverability::Permanent => {
        // Give up immediately
        return Err(error);
    }
    Recoverability::Unknown => {
        // Use circuit breaker
        if circuit_breaker.should_try() {
            continue;
        }
        return Err(error);
    }
}
