            let lim = limiter.clone();
            let canc = cancelled.clone();
            let waiter = sub.spawn(async move |cx| {
                println!("    [waiter] attempting to acquire (will wait)");
                let result = with_rate_limit(&cx, &lim, async { Ok::<_, String>(()) }).await;

                if matches!(result, Err(RateLimitError::Cancelled)) {
                    println!("    [waiter] received Cancelled error");
                    canc.fetch_add(1, Ordering::SeqCst);
                }
            });

            // Cancel it
            sub.sleep(Duration::from_millis(10)).await;
            println!("    [test] cancelling waiter");
            waiter.cancel();
        }).await;
    });

    let cancelled_count = cancelled.load(Ordering::SeqCst);
    println!("  Result: cancelled_count={}", cancelled_count);

    assert_eq!(cancelled_count, 1);

    println!("  PASSED\n");
}

