### 1. Entropy Source Trait Hierarchy
```rust
// src/util/entropy.rs

use std::sync::Arc;
use parking_lot::Mutex;

/// Core trait for entropy providers
pub trait EntropySource: Send + Sync + 'static {
    /// Fill buffer with entropy bytes
    fn fill_bytes(&self, dest: &mut [u8]);

    /// Get next u64 value
    fn next_u64(&self) -> u64;

    /// Fork entropy source for child task (must be deterministic)
    fn fork(&self, task_id: TaskId) -> Arc<dyn EntropySource>;

    /// Get source identifier for tracing
    fn source_id(&self) -> &'static str;
}

/// Production: delegates to OS entropy
pub struct OsEntropy;

impl EntropySource for OsEntropy {
    fn fill_bytes(&self, dest: &mut [u8]) {
        getrandom::getrandom(dest).expect("OS entropy failed");
    }

    fn next_u64(&self) -> u64 {
        let mut buf = [0u8; 8];
        self.fill_bytes(&mut buf);
        u64::from_le_bytes(buf)
    }

    fn fork(&self, _task_id: TaskId) -> Arc<dyn EntropySource> {
        Arc::new(OsEntropy) // OS entropy does not need forking
    }

    fn source_id(&self) -> &'static str { "os" }
}

/// Lab: deterministic seeded PRNG with hierarchical forking
/// 
/// IMPORTANT: Uses Mutex for thread-safety. This is critical because
/// tasks may be polled from different worker threads in multi-threaded scenarios.
pub struct DetEntropy {
    inner: Mutex<DetEntropyInner>,
    seed: u64,
}

struct DetEntropyInner {
    rng: DetRng,
    fork_counter: u64,
}

impl DetEntropy {
    pub fn new(seed: u64) -> Self {
        Self {
            inner: Mutex::new(DetEntropyInner {
                rng: DetRng::new(seed),
                fork_counter: 0,
            }),
            seed,
        }
    }

    /// Create with explicit fork counter (for child sources)
    fn with_fork_counter(seed: u64, fork_counter: u64) -> Self {
        Self {
            inner: Mutex::new(DetEntropyInner {
                rng: DetRng::new(seed),
                fork_counter,
            }),
            seed,
        }
    }
}

impl EntropySource for DetEntropy {
    fn fill_bytes(&self, dest: &mut [u8]) {
        let mut inner = self.inner.lock();
        for byte in dest.iter_mut() {
            *byte = (inner.rng.next_u64() & 0xFF) as u8;
        }
    }

    fn next_u64(&self) -> u64 {
        self.inner.lock().rng.next_u64()
    }

    fn fork(&self, task_id: TaskId) -> Arc<dyn EntropySource> {
        let mut inner = self.inner.lock();
        let counter = inner.fork_counter;
        inner.fork_counter += 1;

        // Deterministic child seed using SplitMix64-style mixing
        // This provides good entropy distribution while being fully deterministic
        let mut child_seed = self.seed;
        child_seed = child_seed.wrapping_add(0x9e3779b97f4a7c15); // golden ratio
        child_seed = (child_seed ^ (child_seed >> 30)).wrapping_mul(0xbf58476d1ce4e5b9);
        child_seed = child_seed.wrapping_add(task_id.as_u64());
        child_seed = (child_seed ^ (child_seed >> 27)).wrapping_mul(0x94d049bb133111eb);
        child_seed = child_seed.wrapping_add(counter);
        child_seed ^= child_seed >> 31;

        Arc::new(DetEntropy::with_fork_counter(child_seed, 0))
    }

    fn source_id(&self) -> &'static str { "deterministic" }
}

/// Thread-local entropy source for worker threads
/// 
/// In multi-threaded runtimes, each worker thread gets its own entropy source
/// derived deterministically from the global seed + thread index.
pub struct ThreadLocalEntropy {
    global_seed: u64,
}

impl ThreadLocalEntropy {
    pub fn new(global_seed: u64) -> Self {
        Self { global_seed }
    }

    /// Get entropy source for current thread
    pub fn for_thread(&self, thread_index: usize) -> DetEntropy {
        let thread_seed = self.global_seed
            .wrapping_mul(0x517cc1b727220a95)
            .wrapping_add(thread_index as u64);
        DetEntropy::new(thread_seed)
    }
}
