                Ok::<_, String>(1)
            }).await;

            // Failure (triggers WARN log)
            let _: Result<i32, _> = with_circuit_breaker(&cx, &breaker, async {
                Err::<i32, _>("fail".to_string())
            }).await;
        });
    });

    // Log output verified visually or with log capture
}
