## Unit Tests

### Pool Construction Tests
```rust
#[cfg(test)]
mod pool_construction_tests {
    #[test]
    fn pool_respects_min_connections() {
        init_pool_test_logging();

        let pool = GenericPool::new(
            || async { Ok(MockConnection::new()) },
            PoolConfig {
                min_connections: 5,
                max_connections: 10,
                ..Default::default()
            },
        );

        // Pool should pre-create min connections
        assert!(pool.stats().idle >= 5);
        tracing::info!(idle = %pool.stats().idle, "Min connections created");
    }

    #[test]
    fn pool_enforces_max_connections() {
        init_pool_test_logging();

        let pool = GenericPool::new(...);

        // Acquire max + 1 should block
        let mut conns = Vec::new();
        for _ in 0..10 {
            conns.push(pool.try_acquire().unwrap());
        }

        // 11th should fail immediately with try_acquire
        assert!(pool.try_acquire().is_none());

        tracing::info!("Max connection limit enforced");
    }
}
```

### PooledResource Tests
```rust
#[cfg(test)]
mod pooled_resource_tests {
    #[test]
    fn explicit_return_discharges_obligation() {
        init_pool_test_logging();

        let pool = GenericPool::new(...);
        let resource = pool.acquire(&cx).await.unwrap();

        let token = resource.return_permit().clone();
        resource.return_to_pool();

        // Obligation should be discharged
        assert!(token.is_discharged());
        tracing::info!("Return discharges obligation");
    }

    #[test]
    fn discard_marks_resource_broken() {
        init_pool_test_logging();

        let pool = GenericPool::new(...);
        let initial_total = pool.stats().total;

        let resource = pool.acquire(&cx).await.unwrap();
        resource.discard();

        // Total should decrease (resource not returned to pool)
        assert!(pool.stats().total < initial_total || pool.stats().broken > 0);
        tracing::info!("Discard marks resource broken");
    }
}
