// src/lab/network/metrics.rs

use serde::{Serialize, Deserialize};
use std::time::Duration;

/// Metrics collected by the simulated network
#[derive(Clone, Debug, Default, Serialize, Deserialize)]
pub struct NetworkMetrics {
    /// Total packets sent
    pub packets_sent: u64,

    /// Total packets delivered
    pub packets_delivered: u64,

    /// Total packets dropped
    pub packets_dropped: u64,

    /// Total packets corrupted
    pub packets_corrupted: u64,

    /// Total bytes sent
    pub bytes_sent: u64,

    /// Total bytes delivered
    pub bytes_delivered: u64,

    /// Average latency
    pub avg_latency: Duration,

    /// Min latency observed
    pub min_latency: Duration,

    /// Max latency observed
    pub max_latency: Duration,

    /// P50 latency
    pub p50_latency: Duration,

    /// P99 latency
    pub p99_latency: Duration,

    /// Packet loss rate
    pub loss_rate: f64,

    /// Current network utilization (0.0 - 1.0)
    pub utilization: f64,
}

impl NetworkMetrics {
    pub fn delivery_rate(&self) -> f64 {
        if self.packets_sent == 0 {
            1.0
        } else {
            self.packets_delivered as f64 / self.packets_sent as f64
        }
    }
}
