### IO-002: File Seek
```rust
conformance_test! {
    id: "io-002",
    name: "File seek operations",
    description: "Seek to positions and read",
    category: TestCategory::IO,
    tags: ["file", "seek"],
    expected: "Seeking works correctly",
    test: |rt| {
        rt.block_on(async {
            let dir = tempdir().unwrap();
            let path = dir.path().join("seek_test.txt");

            // Write test data
            let mut file = rt.file_create(&path).await.unwrap();
            file.write_all(b"0123456789").await.unwrap();
            drop(file);

            // Read with seeking
            let mut file = rt.file_open(&path).await.unwrap();

            // Seek to middle
            file.seek(SeekFrom::Start(5)).await.unwrap();
            let mut buf = [0u8; 3];
            file.read_exact(&mut buf).await.unwrap();
            assert_eq!(&buf, b"567");

            // Seek from end
            file.seek(SeekFrom::End(-2)).await.unwrap();
            file.read_exact(&mut buf[..2]).await.unwrap();
            assert_eq!(&buf[..2], b"89");

            // Seek from current
            file.seek(SeekFrom::Start(2)).await.unwrap();
            file.seek(SeekFrom::Current(3)).await.unwrap();
            file.read_exact(&mut buf[..1]).await.unwrap();
            assert_eq!(&buf[..1], b"5");

            TestResult::passed()
        })
    }
}
