### IO-004: TCP Concurrent Connections
```rust
conformance_test! {
    id: "io-004",
    name: "TCP concurrent connections",
    description: "Handle multiple simultaneous TCP connections",
    category: TestCategory::IO,
    tags: ["tcp", "concurrent"],
    expected: "All connections handled correctly",
    test: |rt| {
        rt.block_on(async {
            let listener = rt.tcp_listen("127.0.0.1:0").await.unwrap();
            let addr = listener.local_addr().unwrap();

            let server = rt.spawn(async move {
                let mut handles = Vec::new();
                for _ in 0..10 {
                    let (mut socket, _) = listener.accept().await.unwrap();
                    handles.push(rt.spawn(async move {
                        let mut buf = [0u8; 100];
                        let n = socket.read(&mut buf).await.unwrap();
                        socket.write_all(&buf[..n]).await.unwrap();
                    }));
                }
                join_all(handles).await;
            });

            let clients: Vec<_> = (0..10)
                .map(|i| {
                    let addr = addr.clone();
                    rt.spawn(async move {
                        let mut socket = rt.tcp_connect(addr).await.unwrap();
                        let msg = format!("client-{}", i);
                        socket.write_all(msg.as_bytes()).await.unwrap();

                        let mut buf = vec![0u8; msg.len()];
                        socket.read_exact(&mut buf).await.unwrap();
