```

## Receiver Side

```rust
impl<T> Receiver<T> {
    /// Receive a message. Cancel-safe (two-phase on receiver too).
    pub async fn recv(&self, cx: &mut Cx<'_>) -> Result<RecvPermit<'_, T>, RecvError>;
}

pub struct RecvPermit<'a, T> {
    // Contains the received message
    value: T,
    ack_obligation: ObligationId,
}

impl<T> RecvPermit<'_, T> {
    /// Acknowledge receipt. Returns the message.
    pub fn ack(self) -> T {
        // Resolve ack obligation as Committed
        self.value
    }

    /// Reject message (return to queue).
    pub fn nack(self) {
