### Signal Stream (Unix)

```rust
// signal/src/unix.rs

use std::io;
use tokio::signal::unix::{signal, Signal, SignalKind};

/// Create a stream that receives a signal.
pub fn signal_stream(kind: SignalKind) -> io::Result<SignalStream> {
    let inner = signal(kind)?;
    tracing::debug!(signal = ?kind, "Registered signal handler");
    Ok(SignalStream { inner })
}

/// Async stream of signals.
pub struct SignalStream {
    inner: Signal,
}

impl SignalStream {
    /// Wait for the next signal.
    pub async fn recv(&mut self) -> Option<()> {
        self.inner.recv().await
    }
}

/// Create a SIGINT (Ctrl+C) handler.
pub fn sigint() -> io::Result<SignalStream> {
    signal_stream(SignalKind::interrupt())
}

/// Create a SIGTERM handler.
pub fn sigterm() -> io::Result<SignalStream> {
    signal_stream(SignalKind::terminate())
}

/// Create a SIGHUP handler.
pub fn sighup() -> io::Result<SignalStream> {
    signal_stream(SignalKind::hangup())
}

/// Create a SIGUSR1 handler.
pub fn sigusr1() -> io::Result<SignalStream> {
    signal_stream(SignalKind::user_defined1())
}

/// Create a SIGUSR2 handler.
pub fn sigusr2() -> io::Result<SignalStream> {
    signal_stream(SignalKind::user_defined2())
}

/// Create a SIGQUIT handler.
pub fn sigquit() -> io::Result<SignalStream> {
    signal_stream(SignalKind::quit())
}

/// Create a SIGCHLD handler (for process spawning).
pub fn sigchld() -> io::Result<SignalStream> {
    signal_stream(SignalKind::child())
}

/// Create a SIGWINCH handler (terminal resize).
pub fn sigwinch() -> io::Result<SignalStream> {
    signal_stream(SignalKind::window_change())
}
