    rt.block_on(async {
        info\!("Starting stream aggregation E2E test");

        // Simulate aggregating data from multiple sources
        let data = stream::iter(vec\![
            Ok(10),
            Ok(20),
            Ok(30),
            Ok(40),
            Ok(50),
        ]);

