        let data = stream::iter(vec\![10, 20, 30, 40, 50]);
        let stats = data.fold(
            (0, 0, i32::MAX, i32::MIN), // (count, sum, min, max)
            |(count, sum, min, max), x| {
                (count + 1, sum + x, min.min(x), max.max(x))
            }
        ).await;

        info\!(
            count = stats.0,
            sum = stats.1,
            min = stats.2,
            max = stats.3,
            avg = stats.1 as f64 / stats.0 as f64,
            "Statistics computed"
        );

        assert_eq\!(stats.0, 5);
        assert_eq\!(stats.1, 150);
        assert_eq\!(stats.2, 10);
        assert_eq\!(stats.3, 50);

        info\!("E2E test completed successfully");
    });
