### Test: Cancel During Wait
```rust
#[test]
fn cancel_during_acquire_wait() {
    let pool = GenericPool::new(
        || async { Ok(MockResource::new()) },
        PoolConfig { max_size: 1, ..Default::default() },
    );

    lab.run(|cx| async {
        // Acquire the only resource
        let r1 = pool.acquire(&cx).await.unwrap();

        // Start second acquire (will wait)
        let handle = cx.spawn(async {
            pool.acquire(&cx).await
        });

        // Cancel while waiting
        cx.cancel(CancelReason::user());

        // No resource leaked
        r1.return_to_pool();
        assert_eq!(pool.stats().total, 1);
    });
}
```

### Test: Cancel While Holding
```rust
#[test]
fn cancel_while_holding_resource() {
    lab.run(|cx| async {
        cx.region(|child_cx| {
            let conn = pool.acquire(&child_cx).await.unwrap();

            // Use connection...

            // Cancel parent (will cancel child)
            cx.cancel(CancelReason::user());

            // Drain phase: return resource
            conn.return_to_pool();
        });

        // Resource back in pool
        assert_eq!(pool.stats().idle, 1);
    });
}
