    let config = MockTransportConfig {
        fail_after: Some(10),
        ..Default::default()
    };
    let (sink, _stream) = mock_channel(config);

    // When: Send 10 symbols (should succeed)
    for i in 0..10 {
        let permit = sink.reserve().await.unwrap();
