## Overview

Implement the async DNS resolver with caching and Happy Eyeballs (RFC 6555) support.

## Rationale

DNS resolution is required for:
- HTTP clients connecting to hosts by name
- gRPC clients
- Any network client that needs to resolve hostnames
- Connection pooling with host-based lookups

## Implementation

### Resolver

```rust
// dns/src/resolver.rs

use std::net::{IpAddr, SocketAddr};
use std::sync::Arc;
use std::time::{Duration, Instant};
use parking_lot::RwLock;

use crate::{DnsError, LookupIp, LookupMx, LookupSrv, LookupTxt};

/// DNS resolver configuration.
#[derive(Clone, Debug)]
pub struct ResolverConfig {
    /// Nameservers to use (default: system).
    pub nameservers: Vec<SocketAddr>,
    /// Enable caching.
    pub cache_enabled: bool,
    /// Maximum cache size.
    pub max_cache_size: usize,
    /// Minimum TTL for cache entries.
    pub min_ttl: Duration,
    /// Maximum TTL for cache entries.
    pub max_ttl: Duration,
    /// Lookup timeout.
    pub timeout: Duration,
    /// Number of retries.
    pub retries: u32,
    /// Enable Happy Eyeballs (RFC 6555).
    pub happy_eyeballs: bool,
    /// Happy Eyeballs first address delay.
    pub happy_eyeballs_delay: Duration,
}

impl Default for ResolverConfig {
    fn default() -> Self {
        ResolverConfig {
            nameservers: Vec::new(), // Use system
            cache_enabled: true,
            max_cache_size: 10_000,
            min_ttl: Duration::from_secs(60),
            max_ttl: Duration::from_secs(86400), // 24 hours
            timeout: Duration::from_secs(5),
            retries: 3,
            happy_eyeballs: true,
            happy_eyeballs_delay: Duration::from_millis(250),
        }
    }
}

/// Async DNS resolver with caching.
pub struct Resolver {
    config: ResolverConfig,
    cache: Arc<RwLock<DnsCache>>,
}

impl Resolver {
    /// Create a resolver with default configuration.
    pub fn new() -> Self {
        Self::with_config(ResolverConfig::default())
    }

    /// Create a resolver with custom configuration.
    pub fn with_config(config: ResolverConfig) -> Self {
        tracing::debug!(
            cache = config.cache_enabled,
            happy_eyeballs = config.happy_eyeballs,
            "Creating DNS resolver"
        );

        Resolver {
            config,
            cache: Arc::new(RwLock::new(DnsCache::new())),
        }
    }

    /// Lookup IP addresses for a hostname.
    pub async fn lookup_ip(&self, host: &str) -> Result<LookupIp, DnsError> {
        // Check cache first
        if self.config.cache_enabled {
            if let Some(cached) = self.cache.read().get_ip(host) {
                tracing::debug!(host = host, "DNS cache hit");
                return Ok(cached);
            }
        }

        tracing::debug!(host = host, "DNS lookup");

        let result = self.do_lookup_ip(host).await?;

        // Cache the result
        if self.config.cache_enabled {
            self.cache.write().put_ip(host, &result);
        }

        Ok(result)
    }

    async fn do_lookup_ip(&self, host: &str) -> Result<LookupIp, DnsError> {
        // If it's already an IP address, return it directly
        if let Ok(ip) = host.parse::<IpAddr>() {
            return Ok(LookupIp::new(vec![ip], Duration::from_secs(0)));
        }

        let timeout = self.config.timeout;
        let retries = self.config.retries;

        for attempt in 0..=retries {
            if attempt > 0 {
                tracing::debug!(host = host, attempt = attempt, "DNS retry");
            }

            match tokio::time::timeout(timeout, self.query_ip(host)).await {
                Ok(Ok(result)) => return Ok(result),
                Ok(Err(e)) => {
                    if attempt == retries {
                        return Err(e);
                    }
                    tracing::warn!(
                        host = host,
                        error = %e,
                        attempt = attempt,
                        "DNS query failed, retrying"
                    );
                }
                Err(_) => {
                    if attempt == retries {
                        return Err(DnsError::Timeout);
                    }
                    tracing::warn!(
                        host = host,
                        attempt = attempt,
                        "DNS query timeout, retrying"
                    );
                }
            }
        }

        Err(DnsError::Timeout)
    }

    async fn query_ip(&self, host: &str) -> Result<LookupIp, DnsError> {
        // Query both A and AAAA records concurrently
        let (v4_result, v6_result) = tokio::join!(
            self.query_a(host),
            self.query_aaaa(host)
        );

        let mut addrs = Vec::new();
        let mut ttl = self.config.max_ttl;

        // Prefer IPv6 if Happy Eyeballs is enabled (but we'll sort later)
        if let Ok((v6_addrs, v6_ttl)) = v6_result {
            addrs.extend(v6_addrs);
            ttl = std::cmp::min(ttl, v6_ttl);
        }

        if let Ok((v4_addrs, v4_ttl)) = v4_result {
            addrs.extend(v4_addrs);
            ttl = std::cmp::min(ttl, v4_ttl);
        }

        if addrs.is_empty() {
            return Err(DnsError::NoRecords(host.to_string()));
        }

        // Apply TTL bounds
        ttl = std::cmp::max(ttl, self.config.min_ttl);
        ttl = std::cmp::min(ttl, self.config.max_ttl);

        tracing::info!(
            host = host,
            addrs = addrs.len(),
            ttl_secs = ttl.as_secs(),
            "DNS lookup complete"
        );

        Ok(LookupIp::new(addrs, ttl))
    }

    async fn query_a(&self, host: &str) -> Result<(Vec<IpAddr>, Duration), DnsError> {
        // Use system resolver or custom nameservers
        // This is a simplified implementation - real code would use trust-dns
        let addrs = tokio::net::lookup_host(format!("{}:0", host))
            .await
            .map_err(|e| DnsError::Io(e.to_string()))?
            .filter_map(|addr| {
                if addr.ip().is_ipv4() {
                    Some(addr.ip())
                } else {
                    None
                }
            })
            .collect::<Vec<_>>();

        Ok((addrs, Duration::from_secs(300))) // Default TTL
    }

    async fn query_aaaa(&self, host: &str) -> Result<(Vec<IpAddr>, Duration), DnsError> {
        let addrs = tokio::net::lookup_host(format!("{}:0", host))
            .await
            .map_err(|e| DnsError::Io(e.to_string()))?
            .filter_map(|addr| {
                if addr.ip().is_ipv6() {
                    Some(addr.ip())
                } else {
                    None
                }
            })
            .collect::<Vec<_>>();

        Ok((addrs, Duration::from_secs(300)))
    }

    /// Perform Happy Eyeballs connection to a host.
    ///
    /// Tries to connect to all resolved addresses with a preference for IPv6,
    /// returning the first successful connection.
    pub async fn happy_eyeballs_connect(
        &self,
        host: &str,
        port: u16,
    ) -> Result<tokio::net::TcpStream, DnsError> {
        let lookup = self.lookup_ip(host).await?;
        let addrs = lookup.addresses();

        if addrs.is_empty() {
            return Err(DnsError::NoRecords(host.to_string()));
        }

        tracing::debug!(
            host = host,
            port = port,
            addrs = addrs.len(),
            "Starting Happy Eyeballs connection"
        );

        // Sort: IPv6 first, then IPv4
        let mut sorted_addrs: Vec<_> = addrs.iter()
            .map(|ip| SocketAddr::new(*ip, port))
            .collect();
        sorted_addrs.sort_by_key(|a| if a.is_ipv6() { 0 } else { 1 });

        let delay = self.config.happy_eyeballs_delay;

        // Try connections with staggered starts
        use tokio::sync::oneshot;
        let (done_tx, done_rx) = oneshot::channel::<()>();
        let done_tx = Arc::new(parking_lot::Mutex::new(Some(done_tx)));

        let connect_tasks: Vec<_> = sorted_addrs.iter().enumerate()
            .map(|(i, &addr)| {
                let delay = delay * i as u32;
                let done_tx = done_tx.clone();

                async move {
                    // Wait for our turn
                    tokio::time::sleep(delay).await;

                    // Check if someone else already succeeded
                    if done_tx.lock().is_none() {
                        return Err(DnsError::Cancelled);
                    }

                    tracing::debug!(addr = %addr, "Trying connection");

                    match tokio::net::TcpStream::connect(addr).await {
                        Ok(stream) => {
                            // Signal success
                            done_tx.lock().take();
                            tracing::info!(addr = %addr, "Happy Eyeballs connection succeeded");
                            Ok(stream)
                        }
                        Err(e) => {
                            tracing::debug!(addr = %addr, error = %e, "Connection attempt failed");
                            Err(DnsError::Connection(e.to_string()))
                        }
                    }
                }
            })
            .collect();

        // Race all connections
        let results = futures_util::future::join_all(connect_tasks).await;

        // Return first success
        for result in results {
            if let Ok(stream) = result {
                return Ok(stream);
            }
        }

        Err(DnsError::Connection(format!(
            "all {} connection attempts failed",
            sorted_addrs.len()
        )))
    }

    /// Lookup MX records.
    pub async fn lookup_mx(&self, domain: &str) -> Result<LookupMx, DnsError> {
        // Implementation would use trust-dns for MX queries
        tracing::debug!(domain = domain, "MX lookup");
        Err(DnsError::NotImplemented("MX lookup"))
    }

    /// Lookup SRV records.
    pub async fn lookup_srv(&self, name: &str) -> Result<LookupSrv, DnsError> {
        tracing::debug!(name = name, "SRV lookup");
        Err(DnsError::NotImplemented("SRV lookup"))
    }

    /// Lookup TXT records.
    pub async fn lookup_txt(&self, name: &str) -> Result<LookupTxt, DnsError> {
        tracing::debug!(name = name, "TXT lookup");
        Err(DnsError::NotImplemented("TXT lookup"))
    }

    /// Clear the cache.
    pub fn clear_cache(&self) {
        tracing::debug!("Clearing DNS cache");
        self.cache.write().clear();
    }

    /// Get cache statistics.
    pub fn cache_stats(&self) -> CacheStats {
        self.cache.read().stats()
    }
}

