use std::net::IpAddr;
use std::time::Duration;

/// Result of an IP address lookup.
#[derive(Debug, Clone)]
pub struct LookupIp {
    addresses: Vec<IpAddr>,
    ttl: Duration,
}

impl LookupIp {
    pub(crate) fn new(addresses: Vec<IpAddr>, ttl: Duration) -> Self {
        LookupIp { addresses, ttl }
    }

    /// Get the resolved addresses.
    pub fn addresses(&self) -> &[IpAddr] {
        &self.addresses
    }

    /// Get the TTL.
    pub fn ttl(&self) -> Duration {
        self.ttl
    }

    /// Get the first address (if any).
    pub fn first(&self) -> Option<IpAddr> {
        self.addresses.first().copied()
    }

    /// Iterate over addresses.
    pub fn iter(&self) -> impl Iterator<Item = &IpAddr> {
        self.addresses.iter()
    }
}

impl IntoIterator for LookupIp {
    type Item = IpAddr;
    type IntoIter = std::vec::IntoIter<IpAddr>;

    fn into_iter(self) -> Self::IntoIter {
        self.addresses.into_iter()
    }
}
