### Interceptors
```rust
/// Interceptor for modifying requests/responses
pub trait Interceptor: Send + Sync {
    fn intercept(&self, request: Request<()>) -> Result<Request<()>, Status>;
}

impl<F> Interceptor for F
where F: Fn(Request<()>) -> Result<Request<()>, Status> + Send + Sync {
    fn intercept(&self, request: Request<()>) -> Result<Request<()>, Status> {
        self(request)
    }
}

/// Layer-based interceptor
pub struct InterceptorLayer<I> {
    interceptor: I,
}

impl<S, I> Layer<S> for InterceptorLayer<I>
where I: Interceptor + Clone {
    type Service = InterceptedService<S, I>;

    fn layer(&self, service: S) -> Self::Service {
        InterceptedService {
            inner: service,
            interceptor: self.interceptor.clone(),
        }
    }
}

// Common interceptors
pub fn trace_interceptor(request: Request<()>) -> Result<Request<()>, Status> {
    let span = tracing::span\!(Level::INFO, "grpc", method = %request.uri().path());
    Ok(request.set_extension(span))
}

pub fn auth_interceptor(token: &str) -> impl Interceptor {
    let token = token.to_string();
    move |mut request: Request<()>| {
        request.metadata_mut().insert(
            "authorization",
            format\!("Bearer {}", token).parse().unwrap(),
        );
        Ok(request)
    }
}
