    async fn next(&self) -> Option<Result<AuthenticatedSymbol, Self::Error>> {
        let mut inner = self.inner.lock().await;

        // Check fail_after
        if let Some(limit) = self.config.fail_after {
            if inner.operation_count >= limit {
                return Some(Err(TransportError::injected("fail_after limit reached")));
            }
        }

        // Apply latency
        if self.config.base_latency > Duration::ZERO {
            let jitter = inner.rng.gen_range(Duration::ZERO..self.config.latency_jitter);
            tokio::time::sleep(self.config.base_latency + jitter).await;
        }

        // Get next symbol
        let symbol = if self.config.preserve_order {
            inner.symbols.pop_front()?
        } else {
            let idx = inner.rng.gen_range(0..inner.symbols.len());
            inner.symbols.remove(idx)?
        };

        inner.operation_count += 1;

        // Simulate loss
        if inner.rng.gen::<f64>() < self.config.loss_rate {
            tracing::debug!(symbol_id = %symbol.id(), "Mock: symbol lost on receive");
            return self.next().await; // Skip to next
        }

        Some(Ok(symbol))
    }
}
